{
    for (int r = 0; r < row; r++)
        if (col[r] == c || abs(col[r] - c) == row - r)
            return 0;
    return 1;
}

void place(int row)
{
    if (row == n) {
        solutions++;
        if (solutions == 1) {
            printf("First solution:\n");
