#include <stdio.h>
#include <stdlib.h>

struct Node
{
    int data;
    struct Node *next;   /* self-referential pointer */
};

int main(void)
{
    struct Node *head = NULL, *tail = NULL, *n, *cur;
    int values[4] = {10, 20, 30, 40};
    int i;

    for (i = 0; i < 4; i++)
    {
        n = (struct Node *)malloc(sizeof(struct Node));
        if (n == NULL)
        {
            printf("Memory allocation failed.\n");
            return 1;
        }
        n->data = values[i];
        n->next = NULL;
        if (head == NULL)
            head = n;
        else
            tail->next = n;
        tail = n;
    }

    printf("Linked list: ");
    for (cur = head; cur != NULL; cur = cur->next)
        printf("%d -> ", cur->data);
    printf("NULL\n");

    while (head != NULL)
    {
        cur = head;
        head = head->next;
        free(cur);
    }
    return 0;
}

