#include <stdio.h>

#define MAX(a, b) ((a) > (b) ? (a) : (b))

int main(void)
{
    int x = 10, y = 20;
    printf("MAX(%d, %d) = %d\n", x, y, MAX(x, y));

    /* Side effect: the macro argument is written twice in the expansion,
       so x++ can be evaluated twice. */
    int a = 5, b = 3;
    int m = MAX(a++, b);
    printf("MAX(a++, b): result = %d, a = %d (a was incremented twice!)\n", m, a);
    printf("Lesson: never pass expressions with ++, -- or function calls to a macro.\n");
