int square(int n) { return n * n; }
int cube(int n) { return n * n * n; }
int power(int base, int exp)
{
    int r = 1;
    while (exp-- > 0)
        r *= base;
    return r;
}
int gcd(int a, int b)
{
    while (b != 0)
    {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}
int is_even(int n) { return n % 2 == 0; }

