#include <stdio.h>

#define BAD_SQ(x) x * x            /* missing parentheses */
#define MAX_M(a, b) ((a) > (b) ? (a) : (b))

static int calls = 0;
static int next(void) { return ++calls; }   /* function with a side effect */

static inline int max_f(int a, int b) { return a > b ? a : b; }

int main(void)
{
    printf("BAD_SQ(2+3)   = %d (expected 25)\n", BAD_SQ(2 + 3));

    calls = 0;
    int m1 = MAX_M(next(), 0);
    printf("Macro : result=%d, next() ran %d times\n", m1, calls);

    calls = 0;
    int m2 = max_f(next(), 0);
    printf("Inline: result=%d, next() ran %d time\n", m2, calls);

    printf("The inline function checks types and evaluates arguments once.\n");
    return 0;
}

