/* ===== strutil.c ===== */
int count_vowels(const char *s)
{
    int c = 0;
    for (; *s; s++)
        if (strchr("aeiouAEIOU", *s))
            c++;
    return c;
}
void reverse_str(char *s)
{
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; i++)
    {
        char t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
}
void to_upper_str(char *s)
{
    for (; *s; s++)
        *s = (char)toupper((unsigned char)*s);
}

