/* ===== main.c ===== */
int main(void)
{
    int a = 10, b = 20;
    int arr[] = {4, 9, -2, 15, 7};
    int n = (int)(sizeof arr / sizeof arr[0]);
    int lo, hi;

    swap(&a, &b);
    printf("After swap: a=%d b=%d\n", a, b);
    printf("Sum = %d\n", array_sum(arr, n));
    min_max(arr, n, &lo, &hi);
    printf("Min = %d, Max = %d\n", lo, hi);
