}

/* ===== ptrutil.c : definitions ===== */
void swap(int *a, int *b)
{
    int t = *a;
    *a = *b;
    *b = t;
}
int array_sum(const int *p, int n)
{
    int s = 0;
    for (const int *e = p + n; p < e; p++)
        s += *p;
    return s;
}
void min_max(const int *p, int n, int *min, int *max)
{
    *min = *max = p[0];
    for (int i = 1; i < n; i++)
    {
        if (p[i] < *min) *min = p[i];
        if (p[i] > *max) *max = p[i];
    }
}

