/* ===== numutil.c ===== */
int is_prime(int n)
{
    if (n < 2) return 0;
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) return 0;
    return 1;
}
long factorial(int n)
{
    long f = 1;
    for (int i = 2; i <= n; i++) f *= i;
    return f;
}
int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
void print_primes(int limit)
{
    for (int i = 2; i <= limit; i++)
        if (is_prime(i)) printf(" %d", i);
    printf("\n");
}

