#define MATHUTIL_H
long power(long base, int exp);
int  gcd(int a, int b);
long fib(int n);
#endif

int main(void)
{
    printf("power(3, 13) = %ld\n", power(3, 13));
    printf("gcd(1071, 462) = %d\n", gcd(1071, 462));
    printf("fib(30) = %ld\n", fib(30));
    return 0;
}

/* Fast exponentiation by squaring.
   Time: O(log exp) multiplications. Space: O(1). */
long power(long base, int exp)
{
    long r = 1;
    while (exp > 0)
    {
        if (exp & 1) r *= base;
        base *= base;
        exp >>= 1;
    }
    return r;
}

/* Euclid's algorithm. Time: O(log min(a,b)). Space: O(1) (iterative). */
int gcd(int a, int b)
{
    while (b != 0)
    {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

/* Iterative Fibonacci. Time: O(n). Space: O(1).
   (A naive recursive version would be O(2^n) time.) */
long fib(int n)
{
    long a = 0, b = 1;
    for (int i = 0; i < n; i++)
    {
        long t = a + b;
        a = b;
        b = t;
    }
    return a;
}

