#include <stdio.h>

#define DIV_M(a, b) ((a) / (b))     /* no check, crashes on b == 0 */
#define MIN_M(a, b) ((a) < (b) ? (a) : (b))

static int calls;
static int next(void) { return ++calls; }

/* inline function: type-checked, one evaluation, can report failure */
static inline int safe_div(int a, int b, int *out)
{
    if (b == 0)
        return 0;          /* failure */
    *out = a / b;
    return 1;              /* success */
}

int main(void)
{
    int q;
    int pairs[][2] = {{20, 4}, {7, 0}, {-9, 3}};
    for (int i = 0; i < 3; i++)
    {
        if (safe_div(pairs[i][0], pairs[i][1], &q))
            printf("%d / %d = %d\n", pairs[i][0], pairs[i][1], q);
        else
            printf("%d / %d : error, division by zero avoided\n", pairs[i][0], pairs[i][1]);
    }
    printf("DIV_M(20, 4) = %d (macro only works when b is non-zero)\n", DIV_M(20, 4));

    calls = 5;
    int m = MIN_M(next(), 100);
    printf("MIN_M(next(),100) = %d, but next() ran %d times\n", m, calls - 5);
    return 0;
}

#include <stdio.h>

#define ALGO 2   /* 1 = loop, 2 = formula */

/* Sum of 1..n chosen at compile time.
   ALGO 1: time O(n), space O(1).
   ALGO 2: time O(1), space O(1).
   The unused branch is removed by the preprocessor, so it costs nothing. */
static long sum_to(long n)
{
#if ALGO == 1
    long s = 0;
    for (long i = 1; i <= n; i++)
        s += i;
    return s;
#elif ALGO == 2
    return n * (n + 1) / 2;
#else
    return -1;
#endif
}

int main(void)
{
#if ALGO == 1
    printf("Algorithm: loop (O(n) time)\n");
#elif ALGO == 2
    printf("Algorithm: closed formula (O(1) time)\n");
#else
    printf("Unknown algorithm\n");
#endif
    printf("sum_to(10)      = %ld\n", sum_to(10));
    printf("sum_to(100000)  = %ld\n", sum_to(100000));
    return 0;
}

