#include <stdio.h>
#include <limits.h>

/* returns 1 and stores the sum if no overflow, else 0 */
static int safeAdd(int a, int b, int *out)
{
    if ((b > 0 && a > INT_MAX - b) || (b < 0 && a < INT_MIN - b))
        return 0;
    *out = a + b;
    return 1;
}

int main(void)
{
    int r;
    printf("INT_MAX = %d, INT_MIN = %d, UINT_MAX = %u\n", INT_MAX, INT_MIN, UINT_MAX);
    printf("INT_MAX + 1 : %s\n", safeAdd(INT_MAX, 1, &r) ? "ok" : "overflow detected");
    printf("INT_MIN - 1 : %s\n", safeAdd(INT_MIN, -1, &r) ? "ok" : "overflow detected");
    if (safeAdd(INT_MAX - 5, 5, &r))
        printf("INT_MAX - 5 + 5 = %d (ok)\n", r);
    unsigned int u = UINT_MAX;
    u = u + 1;                       /* unsigned wraps defined: 0 */
    printf("UINT_MAX + 1 = %u (wraps)\n", u);
    printf("0u - 1 = %u (wraps)\n", 0u - 1u);
    return 0;
}

