    case '-': printf("Result = %.2f\n", a - b); break;
    case '*': printf("Result = %.2f\n", a * b); break;
    case '/':
        if (b == 0)                     /* reject division by zero */
            printf("Error: division by zero is not allowed.\n");
        else
            printf("Result = %.2f\n", a / b);
        break;
    default: printf("Unknown operator '%c'.\n", op);
    }
    return 0;
}

