/* keeps asking until the value is in [lo, hi]; returns -1 on EOF via *ok */
int get_int_in_range(const char *prompt, int lo, int hi, int *ok)
{
    int n, r;
    *ok = 1;
    for (;;)
    {
        printf("%s (%d-%d): ", prompt, lo, hi);
        r = scanf("%d", &n);
        if (r == EOF) { *ok = 0; return 0; }
        if (r == 0) { printf("Not a number.\n"); scanf("%*s"); continue; }
        if (n < lo || n > hi) { printf("Out of range.\n"); continue; }
        return n;
    }
}

