static int has_length(const char *s) { return strlen(s) >= 8; }
static int has_upper(const char *s) { for (; *s; s++) if (isupper((unsigned char)*s)) return 1; return 0; }
static int has_digit(const char *s) { for (; *s; s++) if (isdigit((unsigned char)*s)) return 1; return 0; }
static int has_space(const char *s) { return strchr(s, ' ') != NULL; }

