static struct node *rev(struct node *h)
{
    struct node *rest;
    if (h == NULL || h->next == NULL) return h;
    rest = rev(h->next);        /* reverse the tail */
    h->next->next = h;          /* tail's last node now points back */
    h->next = NULL;
    return rest;
}

