}

static struct node *rev(struct node *h)
{
    struct node *prev = NULL, *nx;
    while (h) { nx = h->next; h->next = prev; prev = h; h = nx; }
    return prev;
}

static void freelist(struct node *h)
{
    struct node *p;
    while (h) { p = h; h = h->next; free(p); }
}

/* palindrome test: reverse the second half and compare */
static int is_pal(struct node *head)
{
    struct node *slow = head, *fast = head, *second, *a, *b;
    int ok = 1;
    while (fast && fast->next) { slow = slow->next; fast = fast->next->next; }
    second = rev(slow);
    for (a = head, b = second; b; a = a->next, b = b->next)
        if (a->data != b->data) { ok = 0; break; }
    rev(second);            /* restore */
    return ok;
}

