#include <stdio.h>
#include <stdlib.h>

struct node { int data; struct node *next; };

/* Floyd detection, then find the loop start and cut the link */
static int remove_cycle(struct node *head)
{
    struct node *slow = head, *fast = head;
    while (fast && fast->next)
    {
        slow = slow->next; fast = fast->next->next;
        if (slow == fast) break;
    }
    if (!(fast && fast->next)) return 0;
    slow = head;
    if (slow == fast)           /* loop starts at head */
        while (fast->next != slow) fast = fast->next;
    else
        while (slow->next != fast->next) { slow = slow->next; fast = fast->next; }
    fast->next = NULL;          /* cut the link that closes the loop */
    return 1;
}

