static struct node *tail = NULL;     /* tail->next is the head */

static void show(void)
{
    struct node *p;
    if (!tail) { printf("(empty)\n"); return; }
    p = tail->next;
    do { printf("%d ", p->data); p = p->next; } while (p != tail->next);
