static void insert(int v)            /* insert at the end */
{
    struct node *p = malloc(sizeof *p);
    p->data = v;
    if (!tail) { p->next = p; }
    else { p->next = tail->next; tail->next = p; }
    tail = p;
}

static void del(int v)
{
    struct node *p, *prev;
    if (!tail) return;
    prev = tail; p = tail->next;
    do {
        if (p->data == v)
        {
            if (p == prev) tail = NULL;            /* only node */
            else { prev->next = p->next; if (p == tail) tail = prev; }
            free(p);
            printf("Deleted %d\n", v);
            return;
        }
        prev = p; p = p->next;
    } while (prev != tail);
    printf("%d not found\n", v);
}

