struct node { int data; struct node *next; };

static struct node *merge(struct node *a, struct node *b)
{
    if (!a) return b;
    if (!b) return a;
    if (a->data <= b->data) { a->next = merge(a->next, b); return a; }
    b->next = merge(a, b->next);
    return b;
}

static struct node *msort(struct node *h)
{
    struct node *slow, *fast, *second;
    if (!h || !h->next) return h;
    slow = h; fast = h->next;
    while (fast && fast->next) { slow = slow->next; fast = fast->next->next; }
    second = slow->next;
    slow->next = NULL;                      /* split in the middle */
    return merge(msort(h), msort(second));
}

