/* frees every node; takes the address of head so it can set it to NULL */
static int free_list(struct node **head)
{
    struct node *p;
    int count = 0;
    while (*head)
    {
        p = *head;
        *head = p->next;    /* save next BEFORE freeing */
        free(p);
        count++;
    }
    return count;
}

