struct node { int data; struct node *next; };

static int length(struct node *h)
{
    int n = 0;
    for (; h; h = h->next) n++;
    return n;
}

static struct node *mk(int v, struct node *next)
{
    struct node *p = malloc(sizeof *p);
    p->data = v; p->next = next;
    return p;
}

static struct node *intersect(struct node *a, struct node *b)
{
    int la = length(a), lb = length(b);
    while (la > lb) { a = a->next; la--; }      /* align the starts */
    while (lb > la) { b = b->next; lb--; }
    while (a && a != b) { a = a->next; b = b->next; }
    return a;
}

