    struct node *x = mk(5, NULL), *r;
    r = intersect(a, b);
    if (r) printf("Lists A and B meet at node with value %d\n", r->data);
    else printf("A and B do not intersect\n");
    r = intersect(a, x);
    if (r) printf("Lists A and X meet at node with value %d\n", r->data);
    else printf("A and X do not intersect\n");
    free(c1); free(c2); free(c3);
    free(a->next->next); free(a->next); free(a);
