    struct Node *l1 = build(a, 3), *l2 = build(b, 3);
    struct Node *res = NULL, *tail = NULL;
    int carry = 0;
    for (struct Node *p = l1, *q = l2; p || q || carry; ) {
        int s = carry + (p ? p->digit : 0) + (q ? q->digit : 0);
        struct Node *x = malloc(sizeof *x);
        if (!x) return 1;
        x->digit = s % 10; x->next = NULL; carry = s / 10;
        if (!res) res = x; else tail->next = x;
        tail = x;
        if (p) p = p->next;
        if (q) q = q->next;
    }
    int val = 0, mul = 1;
    for (struct Node *p = res; p; p = p->next) { val += p->digit * mul; mul *= 10; }
    printf("342 + 465 = %d\nResult list (reversed digits): ", val);
    for (struct Node *p = res; p; p = p->next) printf("%d ", p->digit);
    printf("\n");
    while (l1) { struct Node *t = l1->next; free(l1); l1 = t; }
    while (l2) { struct Node *t = l2->next; free(l2); l2 = t; }
    while (res) { struct Node *t = res->next; free(res); res = t; }
    return 0;
}

