    while (cur && cur->data != x) { prev = cur; cur = cur->next; }
    if (!cur) { printf("Value %d not found\n", x); return h; }
    if (prev) prev->next = cur->next; else h = cur->next;
    free(cur);
    printf("Deleted %d\n", x);
    return h;
}

