int balanced(const char *e)
{
    char st[100];
    int top = -1, i;
    for (i = 0; e[i]; i++)
    {
        char c = e[i];
        if (c == '(' || c == '[' || c == '{')
            st[++top] = c;
        else if (c == ')' || c == ']' || c == '}')
        {
            if (top < 0) return 0;
            char o = st[top--];
            if ((c == ')' && o != '(') || (c == ']' && o != '[') || (c == '}' && o != '{'))
                return 0;
        }
    }
    return top == -1;
}

