#include <stdio.h>
#include <string.h>

int prec(char c)
{
    if (c == '^') return 3;
    if (c == '*' || c == '/') return 2;
    if (c == '+' || c == '-') return 1;
    return 0;
}

void topost(const char *in, char *out)
{
    char st[50];
    int top = -1, k = 0, i;
    for (i = 0; in[i]; i++)
    {
        char c = in[i];
        if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))
            out[k++] = c;
        else if (c == '(')
            st[++top] = c;
        else if (c == ')')
        {
            while (top >= 0 && st[top] != '(') out[k++] = st[top--];
            top--;                      /* discard '(' */
        }
        else
        {
            while (top >= 0 && (prec(st[top]) > prec(c) ||
                   (prec(st[top]) == prec(c) && c != '^')))
                out[k++] = st[top--];
            st[++top] = c;
        }
    }
    while (top >= 0) out[k++] = st[top--];
    out[k] = '\0';
}

int main(void)
{
    const char *e[] = { "a+b*c", "(a+b)*c", "a+b*c-d/e", "a^b^c" };
    char post[50];
    int i;
    for (i = 0; i < 4; i++)
    {
        topost(e[i], post);
        printf("Infix: %-10s Postfix: %s\n", e[i], post);
    }
    return 0;
}

