            st[++top] = c - '0';
        else
        {
            int b = st[top--];
            int a = st[top--];
            switch (c)
            {
                case '+': st[++top] = a + b; break;
                case '-': st[++top] = a - b; break;
                case '*': st[++top] = a * b; break;
                case '/': st[++top] = a / b; break;
            }
        }
    }
