/* push costs O(n): new item goes in q2 first, then q1 is appended behind it */
void push(int v)
{
    int i;
    q2[n2++] = v;
    for (i = 0; i < n1; i++) q2[n2++] = q1[i];
    for (i = 0; i < n2; i++) q1[i] = q2[i];
    n1 = n2;
    n2 = 0;
}

int pop(void)
{
    int v = q1[0], i;               /* front of q1 is the stack top */
    for (i = 1; i < n1; i++) q1[i - 1] = q1[i];
    n1--;
    return v;
}

