#include <stdio.h>

/* returns 1 when every bracket is matched in the right order */
int balanced(const char *e)
{
    char st[100];
    int top = -1, i;
    for (i = 0; e[i]; i++)
    {
        char c = e[i];
        if (c == '(' || c == '[' || c == '{')
        {
            if (top == 99) return 0;            /* too deep for our stack */
            st[++top] = c;
        }
        else if (c == ')' || c == ']' || c == '}')
        {
            char o;
            if (top < 0) return 0;              /* closer with no opener */
            o = st[top--];
            if ((c == ')' && o != '(') || (c == ']' && o != '[') || (c == '}' && o != '{'))
                return 0;
        }
    }
    return top == -1;                           /* leftover openers fail */
}

