#include <stdio.h>

int prec(char c)
{
    if (c == '^') return 3;
    if (c == '*' || c == '/') return 2;
    if (c == '+' || c == '-') return 1;
    return 0;
}

void convert(const char *in)
{
    char st[50], out[50];
    int top = -1, k = 0, i;
    for (i = 0; in[i]; i++)
    {
        char c = in[i];
        if (c == '(') st[++top] = c;
        else if (c == ')')
        {
            while (top >= 0 && st[top] != '(') out[k++] = st[top--];
            top--;
        }
        else if (prec(c) > 0)
        {
            while (top >= 0 && prec(st[top]) >= prec(c) && c != '^')
                out[k++] = st[top--];
            st[++top] = c;
        }
        else out[k++] = c;
    }
    while (top >= 0) out[k++] = st[top--];
    out[k] = '\0';
    printf("Postfix: %s\n", out);
}

int main(void)
{
    int choice;
    char e[50];
    for (;;)
    {
        printf("\n1. Convert infix to postfix\n2. Show precedence\n3. Exit\nChoice: ");
        if (scanf("%d", &choice) != 1 || choice == 3) break;
        if (choice == 1)
        {
            printf("Enter infix (no spaces): ");
            if (scanf("%49s", e) != 1) break;
            convert(e);
        }
        else if (choice == 2)
            printf("^ (3)  * / (2)  + - (1)\n");
        else
            printf("Invalid choice.\n");
    }
    printf("Goodbye.\n");
    return 0;
}

