#include <stdio.h>
#define MAX 4

struct cqueue
{
    int data[MAX];
    int front;
    int count;
};

int enqueue(struct cqueue *q, int v)
{
    if (q->count == MAX) return 0;
    q->data[(q->front + q->count) % MAX] = v;
    q->count++;
    return 1;
}

int dequeue(struct cqueue *q, int *v)
{
    if (q->count == 0) return 0;
    *v = q->data[q->front];
    q->front = (q->front + 1) % MAX;
    q->count--;
    return 1;
}

