#include <stdio.h>
#define MAX 6

int val[MAX], pri[MAX], n = 0;

/* lower priority number = served first */
void insert(int v, int p)
{
    int i = n - 1;
    while (i >= 0 && pri[i] > p)
    {
        val[i + 1] = val[i];
        pri[i + 1] = pri[i];
        i--;
    }
    val[i + 1] = v;
    pri[i + 1] = p;
    n++;
}

