    {
        printf("Enter value and priority (1-5): ");
        if (scanf("%d %d", &v, &p) != 2)
        {
            printf("Not numbers, stopping.\n");
            break;
        }
        if (p < 1 || p > 5) { printf("Rejected %d: priority %d invalid\n", v, p); continue; }
        if (n == MAX) { printf("Rejected %d: queue full\n", v); continue; }
        insert(v, p);
    }
    printf("Serving order:\n");
    for (i = 0; i < n; i++)
        printf("  value %d (priority %d)\n", val[i], pri[i]);
