int push1(int v) { if (t1 + 1 == t2) return 0; a[++t1] = v; return 1; }
int push2(int v) { if (t1 + 1 == t2) return 0; a[--t2] = v; return 1; }
int pop1(int *v) { if (t1 == -1) return 0; *v = a[t1--]; return 1; }
int pop2(int *v) { if (t2 == SIZE) return 0; *v = a[t2++]; return 1; }

void show(void)
{
    int i;
    printf("Stack1:");
    for (i = t1; i >= 0; i--) printf(" %d", a[i]);
    printf("\nStack2:");
    for (i = t2; i < SIZE; i++) printf(" %d", a[i]);
    printf("\n");
}

