/* Cost: each element is moved to the stack once and back once, so
   time is O(n). The stack needs n slots, so extra space is O(n). */
void reverse(int q[], int *front, int *rear)
{
    int st[MAX], top = -1;
    while (*front <= *rear) st[++top] = q[(*front)++];
    *front = 0;
    *rear = -1;
    while (top >= 0) q[++(*rear)] = st[top--];
}

