int add_task(int id, int burst)
{
    if (burst <= 0) { printf("Task %d rejected: invalid burst %d\n", id, burst); return 0; }
    if (count == MAX) { printf("Task %d rejected: queue full\n", id); return 0; }
    q[(front + count) % MAX].id = id;
    q[(front + count) % MAX].burst = burst;
    count++;
    printf("Task %d added (burst %d)\n", id, burst);
    return 1;
}

int next_task(struct task *t)
{
    if (count == 0) return 0;
    *t = q[front];
    front = (front + 1) % MAX;
    count--;
    return 1;
}

