    add_task(2, 0);
    add_task(3, 2);
    add_task(4, 5);
    add_task(5, 1);
    add_task(6, 4);
    add_task(7, 9);
    while (next_task(&t))
        printf("Running task %d for %d units\n", t.id, t.burst);
    if (!next_task(&t)) printf("No more tasks: scheduler idle\n");
    return 0;
}

#include <stdio.h>
#include <string.h>

/* Time: every character is read once and pushed/popped at most once,
   so the conversion is O(n). Space: the operator stack and the output
   string each hold at most n characters, so O(n) extra space. */
int prec(char c)
{
    if (c == '^') return 3;
    if (c == '*' || c == '/') return 2;
    if (c == '+' || c == '-') return 1;
    return 0;
}

void topost(const char *in, char *out)
{
    char st[50];
    int top = -1, k = 0, i;
    for (i = 0; in[i]; i++)
    {
        char c = in[i];
        if (c == '(') st[++top] = c;
        else if (c == ')')
        {
            while (top >= 0 && st[top] != '(') out[k++] = st[top--];
            top--;
        }
        else if (prec(c))
        {
            while (top >= 0 && prec(st[top]) >= prec(c))
                out[k++] = st[top--];
            st[++top] = c;
        }
        else out[k++] = c;
    }
    while (top >= 0) out[k++] = st[top--];
    out[k] = '\0';
}

int main(void)
{
    const char *e[] = { "a*(b+c)/d", "a-b-c", "x+y*z" };
    char out[50];
    int i;
    for (i = 0; i < 3; i++)
    {
        topost(e[i], out);
        printf("%-10s => %s\n", e[i], out);
    }
    return 0;
}

