int main(void)
{
    char e[50];
    int st[50], top = -1, i, ok = 1;

    printf("Enter a prefix expression of single digits (e.g. +*234): ");
    if (scanf("%49s", e) != 1)
    {
        printf("No input.\n");
        return 0;
    }
    for (i = (int)strlen(e) - 1; i >= 0 && ok; i--)
    {
        char c = e[i];
        if (c >= '0' && c <= '9') st[++top] = c - '0';
        else if (strchr("+-*/", c) && top >= 1)
        {
            int a = st[top--], b = st[top--];
            if (c == '/' && b == 0) { printf("Division by zero.\n"); ok = 0; }
            else st[++top] = c == '+' ? a + b : c == '-' ? a - b : c == '*' ? a * b : a / b;
        }
        else
        {
            printf("Bad expression at character '%c'.\n", c);
            ok = 0;
        }
    }
    if (ok && top == 0) printf("%s = %d\n", e, st[0]);
    else if (ok) printf("Malformed expression.\n");
    return 0;
}

