struct Node *minNode(struct Node *r) { while (r->left) r = r->left; return r; }

struct Node *delete(struct Node *r, int key) {
    if (r == NULL) return NULL;
    if (key < r->data) r->left = delete(r->left, key);
    else if (key > r->data) r->right = delete(r->right, key);
    else {
        if (r->left == NULL) { struct Node *t = r->right; free(r); return t; }
        if (r->right == NULL) { struct Node *t = r->left; free(r); return t; }
        struct Node *s = minNode(r->right);   /* inorder successor */
        r->data = s->data;
        r->right = delete(r->right, s->data);
    }
    return r;
}

void inorder(struct Node *r) {
    if (r == NULL) return;
    inorder(r->left); printf("%d ", r->data); inorder(r->right);
}

