/* walk down from the root remembering the last left/right turn */
void predSucc(struct Node *root, int key, struct Node **pred, struct Node **succ) {
    struct Node *cur = root;
    *pred = *succ = NULL;
    while (cur) {
        if (key < cur->data) { *succ = cur; cur = cur->left; }
        else if (key > cur->data) { *pred = cur; cur = cur->right; }
        else {
            if (cur->left)  { struct Node *t = cur->left;  while (t->right) t = t->right; *pred = t; }
            if (cur->right) { struct Node *t = cur->right; while (t->left)  t = t->left;  *succ = t; }
            return;
        }
    }
}

