    for (int i = 0; i < 7; i++) root = insert(root, vals[i]);
    for (int i = 0; i < 4; i++) {
        predSucc(root, keys[i], &p, &s);
        printf("Key %d: predecessor = ", keys[i]);
        if (p) printf("%d", p->data); else printf("none");
        printf(", successor = ");
        if (s) printf("%d", s->data); else printf("none");
        printf("\n");
    }
    return 0;
}

