/* returns height, or -1 when the subtree is unbalanced (single O(n) pass) */
int check(struct Node *r) {
    if (r == NULL) return 0;
    int hl = check(r->left);
    if (hl < 0) return -1;
    int hr = check(r->right);
    if (hr < 0) return -1;
    if (hl - hr > 1 || hr - hl > 1) return -1;
    return 1 + (hl > hr ? hl : hr);
}

