/* LCA in a BST: first node whose value lies between the two keys */
struct Node *lca(struct Node *r, int a, int b) {
    while (r) {
        if (a < r->data && b < r->data) r = r->left;
        else if (a > r->data && b > r->data) r = r->right;
        else return r;
    }
    return NULL;
}

