/* returns height (in nodes) and updates *diam with the longest path in nodes */
int depth(struct Node *r, int *diam) {
    if (r == NULL) return 0;
    int l = depth(r->left, diam), rt = depth(r->right, diam);
    if (l + rt + 1 > *diam) *diam = l + rt + 1;
    return 1 + (l > rt ? l : rt);
}

