/* inorder visits keys in sorted order; stop when the counter reaches k */
void kth(struct Node *r, int k, int *count, int *ans) {
    if (r == NULL || *count >= k) return;
    kth(r->left, k, count, ans);
    if (++(*count) == k) { *ans = r->data; return; }
    kth(r->right, k, count, ans);
}

