/* Build tree from level-order values; -1 means "no node". */
struct Node *build(const int *a, int n) {
    if (n == 0 || a[0] == -1) return NULL;
    struct Node *q[32], *root = newnode(a[0]);
    int h = 0, t = 0, i = 1;
    q[t++] = root;
    while (h < t && i < n) {
        struct Node *cur = q[h++];
        if (a[i] != -1) q[t++] = cur->left = newnode(a[i]);
        i++;
        if (i < n) {
            if (a[i] != -1) q[t++] = cur->right = newnode(a[i]);
            i++;
        }
    }
    return root;
}

