/* Level-order traversal with a FIFO queue (array of node pointers). */
void level_order(struct Node *root) {
    struct Node *queue[64];
    int front = 0, rear = 0;
    if (root) queue[rear++] = root;
    while (front < rear) {
        struct Node *cur = queue[front++];     /* dequeue */
        printf("%d ", cur->data);
        if (cur->left)  queue[rear++] = cur->left;    /* enqueue children */
        if (cur->right) queue[rear++] = cur->right;
