    else root->right = insert(root->right, v);
    return root;
}

/* Main logic: nodes in a tree = 1 (this node) + nodes in left + nodes in right.
   An empty tree (NULL) contributes 0, which stops the recursion. */
int count_nodes(const struct Node *root) {
    if (root == NULL) return 0;
    return 1 + count_nodes(root->left) + count_nodes(root->right);
}

void destroy(struct Node *r) {
    if (!r) return;
    destroy(r->left); destroy(r->right); free(r);
}

