struct Node *build(const int *a, int n) {      /* level order, -1 = empty */
    if (n == 0 || a[0] == -1) return NULL;
    struct Node *q[32], *root = newnode(a[0]);
    int h = 0, t = 0, i = 1;
    q[t++] = root;
    while (h < t && i < n) {
        struct Node *cur = q[h++];
        if (a[i] != -1) q[t++] = cur->left = newnode(a[i]);
        i++;
        if (i < n) {
            if (a[i] != -1) q[t++] = cur->right = newnode(a[i]);
            i++;
        }
    }
    return root;
}

/* Iterative search: visit nodes with a queue, no recursion. */
int search(struct Node *root, int key) {
    struct Node *q[64];
    int h = 0, t = 0;
    if (root) q[t++] = root;
    while (h < t) {
        struct Node *cur = q[h++];
        if (cur->data == key) return 1;
        if (cur->left)  q[t++] = cur->left;
        if (cur->right) q[t++] = cur->right;
    }
    return 0;
}

void destroy(struct Node *r) {
    if (!r) return;
    destroy(r->left); destroy(r->right); free(r);
}

