struct Node { int data; struct Node *left, *right; };

/* A structure that wraps the tree: root pointer plus node count. */
struct Bst { struct Node *root; int size; };

void bst_insert(struct Bst *t, int v) {
    struct Node **link = &t->root;
    while (*link) link = v < (*link)->data ? &(*link)->left : &(*link)->right;
    *link = calloc(1, sizeof **link);
    if (!*link) exit(1);
    (*link)->data = v;
    t->size++;
}

/* Minimum = leftmost node, maximum = rightmost node. Returns 0 if empty. */
int bst_min_max(const struct Bst *t, int *mn, int *mx) {
    if (!t->root) return 0;
    const struct Node *p = t->root;
    while (p->left) p = p->left;
    *mn = p->data;
    p = t->root;
    while (p->right) p = p->right;
    *mx = p->data;
    return 1;
}

void destroy(struct Node *r) {
    if (!r) return;
    destroy(r->left); destroy(r->right); free(r);
}

int main(void) {
    struct Bst t = {NULL, 0};
    int mn, mx;
    if (!bst_min_max(&t, &mn, &mx)) printf("Empty tree: no minimum or maximum.\n");
    int vals[] = {40, 20, 60, 10, 30, 50, 70, 5};
    for (int i = 0; i < 8; i++) bst_insert(&t, vals[i]);
    if (bst_min_max(&t, &mn, &mx))
        printf("Tree with %d nodes: minimum = %d, maximum = %d\n", t.size, mn, mx);
    destroy(t.root);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct Node { int key; struct Node *left, *right; };

static struct Node *newNode(int key)
{
    struct Node *n = malloc(sizeof *n);
    if (n == NULL) exit(1);
    n->key = key; n->left = n->right = NULL;
    return n;
}

static struct Node *insert(struct Node *root, int key)
{
    if (root == NULL) return newNode(key);
    if (key < root->key) root->left = insert(root->left, key);
    else if (key > root->key) root->right = insert(root->right, key);
    return root;
}

static struct Node *minNode(struct Node *n)
{
    while (n->left != NULL) n = n->left;   /* leftmost = smallest */
    return n;
}

/* Delete key: 0 children, 1 child, or 2 children (use inorder successor) */
static struct Node *deleteKey(struct Node *root, int key)
{
    if (root == NULL) return NULL;
    if (key < root->key) root->left = deleteKey(root->left, key);
    else if (key > root->key) root->right = deleteKey(root->right, key);
    else {
        if (root->left == NULL) { struct Node *r = root->right; free(root); return r; }
        if (root->right == NULL) { struct Node *l = root->left; free(root); return l; }
        struct Node *s = minNode(root->right);
        root->key = s->key;
        root->right = deleteKey(root->right, s->key);
    }
    return root;
}

static void inorder(const struct Node *n)
{
    if (n == NULL) return;
    inorder(n->left); printf("%d ", n->key); inorder(n->right);
}

static void freeTree(struct Node *n)
{
    if (n == NULL) return;
    freeTree(n->left); freeTree(n->right); free(n);
}

int main(void)
{
    int values[] = {50, 30, 70, 20, 40, 60, 80};
    int toDelete[] = {20, 30, 50, 99};   /* leaf, one child, two children, missing */
    struct Node *root = NULL;
    for (size_t i = 0; i < sizeof values / sizeof values[0]; i++)
        root = insert(root, values[i]);
    printf("Initial tree (inorder): "); inorder(root); printf("\n");
    for (size_t i = 0; i < sizeof toDelete / sizeof toDelete[0]; i++) {
        root = deleteKey(root, toDelete[i]);
        printf("After deleting %2d     : ", toDelete[i]); inorder(root); printf("\n");
    }
    freeTree(root);
    return 0;
}

#include <stdio.h>
