struct Node { int key; struct Node *left, *right; };

static struct Node *insert(struct Node *root, int key)
{
    if (root == NULL) {
        struct Node *n = malloc(sizeof *n);
        if (n == NULL) exit(1);
        n->key = key; n->left = n->right = NULL;
        return n;
    }
    if (key < root->key) root->left = insert(root->left, key);
    else root->right = insert(root->right, key);
    return root;
}

/* Walk down from the root, remembering the last node where we went right (pred)
   or left (succ). */
static void predSucc(const struct Node *root, int key, int *pred, int *succ, int *hasP, int *hasS)
{
    *hasP = *hasS = 0;
    while (root != NULL) {
        if (key < root->key) { *succ = root->key; *hasS = 1; root = root->left; }
        else if (key > root->key) { *pred = root->key; *hasP = 1; root = root->right; }
        else {
            const struct Node *t = root->left;       /* max of left subtree */
            if (t) { while (t->right) t = t->right; *pred = t->key; *hasP = 1; }
            t = root->right;                         /* min of right subtree */
            if (t) { while (t->left) t = t->left; *succ = t->key; *hasS = 1; }
            return;
        }
    }
}

static void freeTree(struct Node *n)
{
    if (n == NULL) return;
    freeTree(n->left); freeTree(n->right); free(n);
}

int main(void)
{
    int vals[] = {20, 8, 22, 4, 12, 10, 14};
    int keys[] = {8, 10, 14, 4, 22};
    struct Node *root = NULL;
    for (size_t i = 0; i < sizeof vals / sizeof vals[0]; i++) root = insert(root, vals[i]);

    printf("+-----+-------------+-------------+\n");
    printf("| Key | Predecessor | Successor   |\n");
    printf("+-----+-------------+-------------+\n");
    for (size_t i = 0; i < sizeof keys / sizeof keys[0]; i++) {
        int p = 0, s = 0, hp, hs;
        predSucc(root, keys[i], &p, &s, &hp, &hs);
        char pb[16] = "none", sb[16] = "none";
        if (hp) snprintf(pb, sizeof pb, "%d", p);
        if (hs) snprintf(sb, sizeof sb, "%d", s);
        printf("| %3d | %-11s | %-11s |\n", keys[i], pb, sb);
    }
    printf("+-----+-------------+-------------+\n");
    freeTree(root);
    return 0;
}

#include <stdio.h>

#define MAXN 31
#define EMPTY -1

/* Tree stored level by level in an array: children of i are 2i+1 and 2i+2.
   The value -1 means "no node here". */
static int isBST(const int a[], int n, int i, int lo, int hi)
{
    if (i >= n || a[i] == EMPTY) return 1;      /* empty subtree is fine */
    if (a[i] <= lo || a[i] >= hi) return 0;     /* value outside allowed range */
    return isBST(a, n, 2 * i + 1, lo, a[i]) &&
           isBST(a, n, 2 * i + 2, a[i], hi);
}

