{
    int n, a[MAXN];
    printf("Enter number of slots (1-%d): ", MAXN);
    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN) {
        printf("Invalid size\n");
        return 0;
    }
    printf("Enter %d values (-1 for empty): ", n);
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1 || a[i] < EMPTY) {
            printf("Invalid value at position %d\n", i);
            return 0;
        }
    }
    if (a[0] == EMPTY) printf("Tree is empty (an empty tree is a BST)\n");
    else printf("Is BST? %s\n", isBST(a, n, 0, -2, 1000000) ? "YES" : "NO");
    return 0;
}

