static struct Node *make(int v, struct Node *l, struct Node *r)
{
    struct Node *n = malloc(sizeof *n);
    if (n == NULL) exit(1);
    n->val = v; n->left = l; n->right = r;
    return n;
}

/* Mirror in place by swapping children at every node.
   Time:  O(n) - each node is visited exactly once.
   Space: O(h) - recursion depth equals tree height h
          (O(log n) balanced, O(n) for a skewed tree). No extra nodes are made. */
static void mirror(struct Node *n)
{
    if (n == NULL) return;
    struct Node *tmp = n->left;
    n->left = n->right;
    n->right = tmp;
    mirror(n->left);
    mirror(n->right);
}

static void preorder(const struct Node *n)
{
    if (n == NULL) return;
    printf("%d ", n->val);
    preorder(n->left); preorder(n->right);
}

static void freeTree(struct Node *n)
{
    if (n == NULL) return;
    freeTree(n->left); freeTree(n->right); free(n);
}

int main(void)
{
    struct Node *root = make(1, make(2, make(4, NULL, NULL), make(5, NULL, NULL)),
                                make(3, NULL, make(6, NULL, NULL)));
    printf("Preorder before mirror: "); preorder(root); printf("\n");
    mirror(root);
    printf("Preorder after mirror : "); preorder(root); printf("\n");
    freeTree(root);
    return 0;
}

#include <stdio.h>
