struct Node { int val; struct Node *left, *right; };

static struct Node *make(int v, struct Node *l, struct Node *r)
{
    struct Node *n = malloc(sizeof *n);
    if (n == NULL) exit(1);
    n->val = v; n->left = l; n->right = r;
    return n;
}

static int identical(const struct Node *a, const struct Node *b)
{
    if (a == NULL && b == NULL) return 1;     /* both empty */
    if (a == NULL || b == NULL) return 0;     /* shapes differ */
    return a->val == b->val && identical(a->left, b->left) && identical(a->right, b->right);
}

static void freeTree(struct Node *n)
{
    if (n == NULL) return;
    freeTree(n->left); freeTree(n->right); free(n);
}

/* build a left-leaning chain of the given depth (maximum-size style test) */
static struct Node *chain(int depth)
{
    struct Node *root = NULL;
    for (int i = 1; i <= depth; i++) root = make(i, root, NULL);
    return root;
}

static void report(const char *name, const struct Node *a, const struct Node *b)
{
    printf("%-22s: %s\n", name, identical(a, b) ? "identical" : "different");
}

int main(void)
{
    /* Normal: same tree twice, then a tree with one changed value */
    struct Node *t1 = make(1, make(2, NULL, NULL), make(3, NULL, NULL));
    struct Node *t2 = make(1, make(2, NULL, NULL), make(3, NULL, NULL));
    struct Node *t3 = make(1, make(2, NULL, NULL), make(9, NULL, NULL));
    report("Normal (same)", t1, t2);
    report("Normal (value differs)", t1, t3);

    /* Minimum: empty trees, and empty vs one node */
    struct Node *one = make(5, NULL, NULL);
    report("Minimum (both empty)", NULL, NULL);
    report("Minimum (empty vs one)", NULL, one);

    /* Maximum: two deep chains of 1000 nodes */
    struct Node *c1 = chain(1000), *c2 = chain(1000);
    report("Maximum (1000 deep)", c1, c2);

    freeTree(t1); freeTree(t2); freeTree(t3); freeTree(one);
    freeTree(c1); freeTree(c2);
    return 0;
}

