struct Node { int val; struct Node *left, *right; };

static struct Node *make(int v, struct Node *l, struct Node *r)
{
    struct Node *n = malloc(sizeof *n);
    if (n == NULL) exit(1);
    n->val = v; n->left = l; n->right = r;
    return n;
}

/* Returns the height, or -1 if the subtree is NOT balanced.
   No globals are needed: the answer travels in the return value. */
static int checkHeight(const struct Node *n)
{
    if (n == NULL) return 0;
    int lh = checkHeight(n->left);
    if (lh < 0) return -1;
    int rh = checkHeight(n->right);
    if (rh < 0) return -1;
    int diff = lh > rh ? lh - rh : rh - lh;
    if (diff > 1) return -1;
    return 1 + (lh > rh ? lh : rh);
}

static void freeTree(struct Node *n)
{
    if (n == NULL) return;
    freeTree(n->left); freeTree(n->right); free(n);
}

int main(void)
