#include <stdio.h>
#include <stdlib.h>

struct Node { int key; struct Node *left, *right; };

static struct Node *insert(struct Node *root, int key)
{
    if (root == NULL) {
        struct Node *n = malloc(sizeof *n);
        if (n == NULL) exit(1);
        n->key = key; n->left = n->right = NULL;
        return n;
    }
    if (key < root->key) root->left = insert(root->left, key);
    else root->right = insert(root->right, key);
    return root;
}

static int contains(const struct Node *n, int key)
{
    while (n != NULL) {
        if (key == n->key) return 1;
        n = key < n->key ? n->left : n->right;
    }
    return 0;
}

/* Returns 1 and stores the LCA in *out, or 0 on failure (empty tree/missing key) */
static int lca(const struct Node *root, int a, int b, int *out)
{
    if (root == NULL || !contains(root, a) || !contains(root, b)) return 0;
    while (root != NULL) {
        if (a < root->key && b < root->key) root = root->left;
        else if (a > root->key && b > root->key) root = root->right;
        else { *out = root->key; return 1; }   /* paths split here */
    }
    return 0;
}

static void freeTree(struct Node *n)
{
    if (n == NULL) return;
    freeTree(n->left); freeTree(n->right); free(n);
}

int main(void)
{
    int vals[] = {20, 8, 22, 4, 12, 10, 14};
    int q[][2] = {{10, 14}, {14, 8}, {4, 22}, {10, 99}};
    struct Node *root = NULL;
    for (size_t i = 0; i < sizeof vals / sizeof vals[0]; i++) root = insert(root, vals[i]);

    for (size_t i = 0; i < sizeof q / sizeof q[0]; i++) {
        int ans;
        if (lca(root, q[i][0], q[i][1], &ans))
            printf("LCA(%d, %d) = %d\n", q[i][0], q[i][1], ans);
        else
            printf("LCA(%d, %d): failed - a key is not in the tree\n", q[i][0], q[i][1]);
    }
    int ans;
    printf("Empty tree: %s\n", lca(NULL, 1, 2, &ans) ? "found" : "failed safely");
    freeTree(root);
    return 0;
}

