/* Height = number of nodes on the longest root-to-leaf path (empty tree = 0).
   Time:  O(n) - every node is visited once.
   Space: O(h) - recursion stack of depth h (the height itself). */
static int height(const struct Node *n)
{
    if (n == NULL) return 0;
    int lh = height(n->left);
    int rh = height(n->right);
    return 1 + (lh > rh ? lh : rh);
}

static void freeTree(struct Node *n)
{
    if (n == NULL) return;
    freeTree(n->left); freeTree(n->right); free(n);
}

