struct Node { int val; struct Node *left, *right; };

static struct Node *build(const int a[], int n, int i)
{
    if (i >= n || a[i] == -1) return NULL;
    struct Node *node = malloc(sizeof *node);
    if (node == NULL) exit(1);
    node->val = a[i];
    node->left = build(a, n, 2 * i + 1);
    node->right = build(a, n, 2 * i + 2);
    return node;
}

/* Plain binary tree: no ordering, so we must look in both subtrees */
static int search(const struct Node *n, int target, int depth)
{
    if (n == NULL) return -1;
    if (n->val == target) return depth;
    int d = search(n->left, target, depth + 1);
    if (d >= 0) return d;
    return search(n->right, target, depth + 1);
}

static void freeTree(struct Node *n)
{
    if (n == NULL) return;
    freeTree(n->left); freeTree(n->right); free(n);
}

