struct Node { int key; struct Node *left, *right; };

static struct Node *insert(struct Node *root, int key)
{
    if (root == NULL) {
        struct Node *n = malloc(sizeof *n);
        if (n == NULL) exit(1);
        n->key = key; n->left = n->right = NULL;
        return n;
    }
    if (key < root->key) root->left = insert(root->left, key);
    else if (key > root->key) root->right = insert(root->right, key);
    return root;
}

/* Main logic: BST property lets us discard half the tree at every step.
   Smaller keys are in the left subtree, larger keys in the right subtree. */
static const struct Node *searchBST(const struct Node *n, int key, int *steps)
{
    while (n != NULL) {
        (*steps)++;
        if (key == n->key) return n;                 /* found */
        n = (key < n->key) ? n->left : n->right;     /* go left or right */
    }
    return NULL;                                     /* fell off the tree */
}

static void freeTree(struct Node *n)
{
    if (n == NULL) return;
    freeTree(n->left); freeTree(n->right); free(n);
}

int main(void)
{
