    for (size_t i = 0; i < sizeof keys / sizeof keys[0]; i++) {
        int steps = 0;
        const struct Node *r = searchBST(root, keys[i], &steps);
        printf("Key %d: %s (%d comparisons)\n", keys[i], r ? "found" : "not found", steps);
    }
    freeTree(root);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct Node { int key; struct Node *left, *right; };

static struct Node *insert(struct Node *root, int key)
{
    struct Node *n = malloc(sizeof *n);
    if (n == NULL) exit(1);
    n->key = key; n->left = n->right = NULL;
    if (root == NULL) return n;
    struct Node *cur = root;
    for (;;) {                                   /* iterative insert */
        if (key < cur->key) { if (!cur->left) { cur->left = n; break; } cur = cur->left; }
        else { if (!cur->right) { cur->right = n; break; } cur = cur->right; }
    }
    return root;
}

/* Iterative delete: walk down keeping the parent, then splice the node out */
static struct Node *deleteKey(struct Node *root, int key, int *ok)
{
    struct Node *parent = NULL, *cur = root;
    *ok = 0;
    while (cur != NULL && cur->key != key) {
        parent = cur;
        cur = key < cur->key ? cur->left : cur->right;
    }
    if (cur == NULL) return root;
    *ok = 1;
    if (cur->left && cur->right) {               /* two children: copy successor */
        struct Node *sp = cur, *s = cur->right;
        while (s->left) { sp = s; s = s->left; }
        cur->key = s->key;
        parent = sp; cur = s;                    /* now remove the successor */
    }
    struct Node *child = cur->left ? cur->left : cur->right;
    if (parent == NULL) root = child;
    else if (parent->left == cur) parent->left = child;
    else parent->right = child;
    free(cur);
    return root;
}

static void inorder(const struct Node *n)
{
    if (n == NULL) return;
    inorder(n->left); printf("%d ", n->key); inorder(n->right);
}

static void freeTree(struct Node *n)
{
    if (n == NULL) return;
    freeTree(n->left); freeTree(n->right); free(n);
}

int main(void)
{
    int vals[] = {8, 3, 10, 1, 6, 14, 4, 7, 13};
    int dels[] = {1, 14, 3, 8, 42};
    struct Node *root = NULL;
    for (size_t i = 0; i < sizeof vals / sizeof vals[0]; i++) root = insert(root, vals[i]);
    printf("Start       : "); inorder(root); printf("\n");
    for (size_t i = 0; i < sizeof dels / sizeof dels[0]; i++) {
        int ok;
        root = deleteKey(root, dels[i], &ok);
        printf("Delete %2d %s: ", dels[i], ok ? "ok  " : "miss"); inorder(root); printf("\n");
    }
    freeTree(root);
    return 0;
}

