struct Node { int val; struct Node *left, *right; };

static struct Node *build(const int a[], int n, int i)
{
    if (i >= n || a[i] == -1) return NULL;
    struct Node *node = malloc(sizeof *node);
    if (node == NULL) exit(1);
    node->val = a[i];
    node->left = build(a, n, 2 * i + 1);
    node->right = build(a, n, 2 * i + 2);
    return node;
}

/* Every node must lie strictly between lo and hi inherited from its ancestors */
static int isBST(const struct Node *n, long lo, long hi)
{
    if (n == NULL) return 1;
    if (n->val <= lo || n->val >= hi) return 0;
    return isBST(n->left, lo, n->val) && isBST(n->right, n->val, hi);
}

static void freeTree(struct Node *n)
{
    if (n == NULL) return;
    freeTree(n->left); freeTree(n->right); free(n);
}

