/* returns 1 if a cycle is found; parent avoids the edge we came from */
int hasCycle(int u, int parent)
{
    int v;
    seen[u] = 1;
    for (v = 0; v < V; v++)
    {
        if (!adj[u][v]) continue;
        if (!seen[v]) { if (hasCycle(v, u)) return 1; }
        else if (v != parent) return 1;      /* visited, not parent: back edge */
    }
    return 0;
}

