    int e[][3] = {{0,1,6},{0,2,7},{1,2,8},{1,3,5},{1,4,-4},{2,3,-3},{2,4,9},{3,1,-2},{4,3,7},{4,0,2}};
    int m = sizeof(e) / sizeof(e[0]);
    int dist[V], i, pass, changed;
    for (i = 0; i < V; i++) dist[i] = INF;
    dist[0] = 0;
    for (pass = 1; pass < V; pass++)       /* V-1 rounds of relaxing every edge */
    {
        changed = 0;
        for (i = 0; i < m; i++)
            if (dist[e[i][0]] != INF && dist[e[i][0]] + e[i][2] < dist[e[i][1]])
            {
                dist[e[i][1]] = dist[e[i][0]] + e[i][2];
                changed = 1;
            }
        if (!changed) break;
    }
    for (i = 0; i < m; i++)                /* one more pass detects negative cycles */
        if (dist[e[i][0]] != INF && dist[e[i][0]] + e[i][2] < dist[e[i][1]])
        {
            printf("Negative cycle detected.\n");
            return 0;
        }
    printf("Bellman-Ford distances from vertex 0:\n");
    for (i = 0; i < V; i++) printf("  dist[%d] = %d\n", i, dist[i]);
    return 0;
}

