    for (k = 0; k < V; k++)
    {
        int u = -1, v;
        for (i = 0; i < V; i++)            /* cheapest vertex not yet in the tree */
            if (!inTree[i] && (u < 0 || key[i] < key[u])) u = i;
        inTree[u] = 1;
        total += key[u];
        for (v = 0; v < V; v++)
            if (w[u][v] && !inTree[v] && w[u][v] < key[v]) { key[v] = w[u][v]; parent[v] = u; }
    }
    printf("Prim's MST edges:\n");
    for (i = 1; i < V; i++) printf("  %d - %d (weight %d)\n", parent[i], i, w[parent[i]][i]);
    printf("Total weight = %d\n", total);
