#define V 6

struct Edge { int u, v, w; };

int parent[V];

int find(int x)
{
    while (parent[x] != x) x = parent[x] = parent[parent[x]];   /* path halving */
    return x;
}

int cmp(const void *a, const void *b)
{
    return ((const struct Edge *)a)->w - ((const struct Edge *)b)->w;
}

int main(void)
{
    struct Edge e[] = {{0,1,4},{0,2,4},{1,2,2},{2,3,3},{2,5,2},{2,4,4},{3,4,3},{5,4,3}};
    int m = sizeof(e) / sizeof(e[0]), i, total = 0, used = 0;
    for (i = 0; i < V; i++) parent[i] = i;
    qsort(e, m, sizeof(e[0]), cmp);        /* sort edges by weight */
    printf("Kruskal's MST edges:\n");
    for (i = 0; i < m && used < V - 1; i++)
    {
        int a = find(e[i].u), b = find(e[i].v);
        if (a != b)                        /* different sets: no cycle */
        {
            parent[a] = b;
            printf("  %d - %d (weight %d)\n", e[i].u, e[i].v, e[i].w);
            total += e[i].w;
            used++;
        }
    }
    printf("Total weight = %d\n", total);
    return 0;
}

