#define V 6

int isBipartite(int adj[V][V])
{
    int color[V], queue[V], head, tail, s, u, v;
    for (s = 0; s < V; s++) color[s] = -1;
    for (s = 0; s < V; s++)
    {
        if (color[s] != -1) continue;
        head = tail = 0;
        queue[tail++] = s; color[s] = 0;
        while (head < tail)
        {
            u = queue[head++];
            for (v = 0; v < V; v++)
            {
                if (!adj[u][v]) continue;
                if (color[v] == -1) { color[v] = 1 - color[u]; queue[tail++] = v; }
                else if (color[v] == color[u]) return 0;   /* same colour on both ends */
            }
        }
    }
    return 1;
}

