#define V 4

int stronglyConnected(int g[V][V])
{
    int r[V][V], i, j, k;
    for (i = 0; i < V; i++) for (j = 0; j < V; j++) r[i][j] = g[i][j] || i == j;
    for (k = 0; k < V; k++)                /* Warshall transitive closure */
        for (i = 0; i < V; i++)
            for (j = 0; j < V; j++)
                if (r[i][k] && r[k][j]) r[i][j] = 1;
    for (i = 0; i < V; i++) for (j = 0; j < V; j++) if (!r[i][j]) return 0;
    return 1;
}

