char grid[R][C + 1] = {"110001", "110001", "001100", "000010", "100011"};

void flood(int r, int c)
{
    if (r < 0 || r >= R || c < 0 || c >= C || grid[r][c] != '1') return;
    grid[r][c] = '0';                      /* mark visited */
    flood(r + 1, c); flood(r - 1, c); flood(r, c + 1); flood(r, c - 1);
}

