/* Adjacency list built by a separate function add_edge() */
typedef struct Node { int v; struct Node *next; } Node;

static void add_edge(Node *adj[], int u, int v) {
    Node *a = malloc(sizeof *a), *b = malloc(sizeof *b);
    if (!a || !b) { free(a); free(b); return; }
    a->v = v; a->next = adj[u]; adj[u] = a;
    b->v = u; b->next = adj[v]; adj[v] = b;
}

