    if (scanf("%d %d", &n, &m) != 2 || n < 1 || n > MAXV || m < 0) { printf("Invalid input\n"); return 1; }
    for (int i = 0; i < m; i++) {
        int u, v;
        if (scanf("%d %d", &u, &v) != 2 || u < 0 || u >= n || v < 0 || v >= n) { printf("Invalid edge\n"); return 1; }
        adj[u][v] = adj[v][u] = 1;
    }
    /* Main logic: each time we find an unvisited vertex, a new component starts;
       the DFS from it marks the whole component. */
    for (int i = 0; i < n; i++) {
        if (!seen[i]) {
            count++;
            printf("Component %d starts at vertex %d\n", count, i);
            visit(i);
        }
    }
    printf("Number of connected components = %d\n", count);
    return 0;
}

