#define MAXV 10
static int adj[MAXV][MAXV], n;

static int path_exists(int s, int t) {
    int seen[MAXV] = {0}, q[MAXV], h = 0, tl = 0;
    if (s < 0 || s >= n || t < 0 || t >= n) return -1;   /* invalid vertex */
    if (s == t) return 1;                                /* trivial path */
    seen[s] = 1; q[tl++] = s;
    while (h < tl) {
        int u = q[h++];
        for (int v = 0; v < n; v++)
            if (adj[u][v] && !seen[v]) {
                if (v == t) return 1;
                seen[v] = 1; q[tl++] = v;
            }
    }
    return 0;
}

