/* DFS: a visited neighbour that is not the parent means a cycle */
static int has_cycle(int u, int parent, int seen[]) {
    seen[u] = 1;
    for (int v = 0; v < n; v++) {
        if (!adj[u][v]) continue;
        if (!seen[v]) { if (has_cycle(v, u, seen)) return 1; }
        else if (v != parent) return 1;
    }
    return 0;
}

