#include <stdio.h>
#define N 6
/* Kahn's algorithm: repeatedly remove vertices of in-degree 0 */
int main(void) {
    int adj[N][N] = {{0}}, indeg[N] = {0}, order[N], cnt = 0;
    int e[][2] = {{5,2},{5,0},{4,0},{4,1},{2,3},{3,1}};
    for (int i = 0; i < 6; i++) { adj[e[i][0]][e[i][1]] = 1; indeg[e[i][1]]++; }
    int done[N] = {0};
    for (int round = 0; round < N; round++) {
        int pick = -1;
        for (int v = 0; v < N; v++)
            if (!done[v] && indeg[v] == 0) { pick = v; break; }
        if (pick < 0) break;                      /* cycle */
        done[pick] = 1;
        order[cnt++] = pick;
        for (int v = 0; v < N; v++)
            if (adj[pick][v]) indeg[v]--;
    }
    if (cnt < N) { printf("Graph has a cycle, no topological order\n"); return 0; }
    printf("Topological order:");
    for (int i = 0; i < N; i++) printf(" %d", order[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>
#define N 7
/* BFS shortest paths (in edges); pointers to the distance and parent arrays */
static void bfs(int adj[][N], int s, int *dist, int *parent) {
    int q[N], h = 0, t = 0;
    for (int *p = dist; p < dist + N; p++) *p = -1;
    for (int *p = parent; p < parent + N; p++) *p = -1;
    *(dist + s) = 0;
    q[t++] = s;
    while (h < t) {
        int u = q[h++];
        for (int v = 0; v < N; v++)
            if (adj[u][v] && *(dist + v) < 0) {
                *(dist + v) = *(dist + u) + 1;
                *(parent + v) = u;
                q[t++] = v;
            }
    }
}

static void print_path(const int *parent, int v) {
    if (v < 0) return;
    print_path(parent, *(parent + v));
    printf("%d ", v);
}

