        if (dist[u] == INF) break;
        done[u] = 1;
        for (int v = 0; v < N; v++)
            if (w[u][v] && !done[v] && dist[u] + w[u][v] < dist[v]) {
                dist[v] = dist[u] + w[u][v];
                prev[v] = u;
