#include <stdio.h>
#define V 5
#define E 8
#define INF 1000000
typedef struct { int from, to, w; } Edge;

int main(void) {
    Edge edges[E] = {{0,1,6},{0,3,7},{1,2,5},{1,3,8},{1,4,-4},{2,1,-2},{3,2,-3},{3,4,9}};
    int dist[V];
    for (int i = 0; i < V; i++) dist[i] = INF;
    dist[0] = 0;
    for (int pass = 1; pass < V; pass++) {          /* V-1 relaxation passes */
        int changed = 0;
        for (int j = 0; j < E; j++) {
            Edge *e = &edges[j];
            if (dist[e->from] != INF && dist[e->from] + e->w < dist[e->to]) {
                dist[e->to] = dist[e->from] + e->w;
                changed = 1;
            }
        }
        if (!changed) break;
    }
    int neg = 0;                                     /* one more pass: negative cycle? */
    for (int j = 0; j < E; j++)
        if (dist[edges[j].from] != INF && dist[edges[j].from] + edges[j].w < dist[edges[j].to]) neg = 1;
    if (neg) { printf("Negative cycle detected\n"); return 0; }
    for (int i = 0; i < V; i++) printf("dist[0 -> %d] = %d\n", i, dist[i]);
    return 0;
}

#include <stdio.h>
#define MAXV 6
#define INF 1000000
/* Prim's MST for several graphs (records) in one run */
static int prim(int n, int w[][MAXV]) {
    int in[MAXV] = {0}, key[MAXV], total = 0;
    for (int i = 0; i < n; i++) key[i] = INF;
    key[0] = 0;
    for (int k = 0; k < n; k++) {
        int u = -1;
        for (int i = 0; i < n; i++)
            if (!in[i] && (u < 0 || key[i] < key[u])) u = i;
        if (key[u] == INF) return -1;               /* disconnected */
        in[u] = 1; total += key[u];
        for (int v = 0; v < n; v++)
            if (w[u][v] && !in[v] && w[u][v] < key[v]) key[v] = w[u][v];
    }
    return total;
}

