        {{0,1,1},{1,2,1},{0,2,5},{-1,0,0}},
        {{0,1,4},{2,3,3},{-1,0,0}}};
    int sizes[3] = {5, 3, 4};
    for (int g = 0; g < 3; g++) {
        int w[MAXV][MAXV] = {{0}};
        for (int i = 0; edges[g][i][0] >= 0; i++)
            w[edges[g][i][0]][edges[g][i][1]] = w[edges[g][i][1]][edges[g][i][0]] = edges[g][i][2];
        int t = prim(sizes[g], w);
        if (t < 0) printf("Graph %d: not connected, no MST\n", g + 1);
        else printf("Graph %d: MST weight = %d\n", g + 1, t);
    }
    return 0;
}

