typedef struct { int u, v, w; } Edge;
static int parent[8];

static int find(int x) { while (parent[x] != x) x = parent[x] = parent[parent[x]]; return x; }
static int cmp(const void *a, const void *b) { return ((const Edge *)a)->w - ((const Edge *)b)->w; }

