#include <stdio.h>
#define MAXV 10
static int adj[MAXV][MAXV], n;

static int bipartite(void) {
    int color[MAXV], q[MAXV];
    for (int i = 0; i < n; i++) color[i] = -1;
    for (int s = 0; s < n; s++) {
        if (color[s] != -1) continue;
        int h = 0, t = 0;
        color[s] = 0; q[t++] = s;
        while (h < t) {
            int u = q[h++];
            for (int v = 0; v < n; v++) {
                if (!adj[u][v]) continue;
                if (color[v] == -1) { color[v] = 1 - color[u]; q[t++] = v; }
                else if (color[v] == color[u]) return 0;
            }
        }
    }
    return 1;
}

