        if (scanf("%d %d", &u, &v) != 2) { printf("Error: edge %d unreadable\n", i + 1); return 1; }
        if (u < 0 || u >= n || v < 0 || v >= n) { printf("Error: edge %d has vertex out of range\n", i + 1); return 1; }
        if (u == v) { printf("Error: self loop on %d makes graph non-bipartite\n", u); return 1; }
        adj[u][v] = adj[v][u] = 1;
    }
    printf("Input accepted. The graph %s bipartite.\n", bipartite() ? "is" : "is NOT");
    return 0;
}

