#define MAXV 6

static void reach(int n, int g[][MAXV], int u, int seen[]) {
    seen[u] = 1;
    for (int v = 0; v < n; v++) if (g[u][v] && !seen[v]) reach(n, g, v, seen);
}

/* Strongly connected iff vertex 0 reaches all, and all reach 0 (reverse graph) */
static int strongly_connected(int n, int g[][MAXV]) {
    int rev[MAXV][MAXV] = {{0}}, a[MAXV] = {0}, b[MAXV] = {0};
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) rev[j][i] = g[i][j];
    reach(n, g, 0, a);
    reach(n, rev, 0, b);
    for (int i = 0; i < n; i++) if (!a[i] || !b[i]) return 0;
    return 1;
}

