typedef struct Node { int v; struct Node *next; } Node;

/* Matrix: O(V^2) memory, edge test O(1). List: O(V+E) memory, edge test O(deg). */
static int has_edge_list(Node *adj[], int u, int v) {
    for (Node *p = adj[u]; p; p = p->next) if (p->v == v) return 1;
    return 0;
}

