#include <stdio.h>
/* Cycle detection with union-find (disjoint sets).
   Time: O(E * alpha(V)) ~ O(E); space: O(V) for the parent array.
   An edge whose ends are already in the same set closes a cycle. */
static int parent[10];
static int find(int x) { return parent[x] == x ? x : (parent[x] = find(parent[x])); }

static int has_cycle(int n, int m, int e[][2]) {
    for (int i = 0; i < n; i++) parent[i] = i;
    for (int i = 0; i < m; i++) {
        int a = find(e[i][0]), b = find(e[i][1]);
        if (a == b) { printf("  edge %d-%d closes a cycle\n", e[i][0], e[i][1]); return 1; }
        parent[a] = b;
    }
    return 0;
}

int main(void) {
    int tree[][2] = {{0,1},{1,2},{1,3},{3,4}};
    int cyc[][2] = {{0,1},{1,2},{2,3},{3,4},{4,1}};
    printf("Graph 1 (tree):\n");
    printf("  result: %s\n", has_cycle(5, 4, tree) ? "cycle" : "no cycle");
    printf("Graph 2:\n");
    printf("  result: %s\n", has_cycle(5, 5, cyc) ? "cycle" : "no cycle");
    return 0;
}

#include <stdio.h>
#define MAXV 10
static int n, adj[MAXV][MAXV], state[MAXV], order[MAXV], pos;

/* DFS-based topological sort: vertices are placed in reverse finishing order */
static int visit(int u) {
    state[u] = 1;
    for (int v = 0; v < n; v++) {
        if (!adj[u][v]) continue;
        if (state[v] == 1) return 0;
        if (state[v] == 0 && !visit(v)) return 0;
    }
    state[u] = 2;
    order[--pos] = u;
    return 1;
}

int main(void) {
    int m;
    printf("Enter number of tasks and dependencies: ");
    if (scanf("%d %d", &n, &m) != 2 || n < 1 || n > MAXV || m < 0) { printf("Invalid input\n"); return 1; }
    for (int i = 0; i < m; i++) {
        int a, b;
        printf("Dependency %d (a must come before b): ", i + 1);
        if (scanf("%d %d", &a, &b) != 2 || a < 0 || a >= n || b < 0 || b >= n) { printf("Invalid\n"); return 1; }
        adj[a][b] = 1;
    }
    pos = n;
    for (int i = 0; i < n; i++)
        if (state[i] == 0 && !visit(i)) { printf("\nCycle found: no topological order\n"); return 0; }
    printf("\nTopological order:");
    for (int i = 0; i < n; i++) printf(" %d", order[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>
#define V 5
#define INF 99999
int main(void) {
    /* cost[i][j] = weight of directed edge i->j, 0 means no edge */
    int cost[V][V] = {
        {0, 10, 3, 0, 0},
        {0, 0, 1, 2, 0},
        {0, 4, 0, 8, 2},
        {0, 0, 0, 0, 7},
        {0, 0, 0, 9, 0}};
    int dist[V], done[V];
    for (int i = 0; i < V; i++) { dist[i] = INF; done[i] = 0; }
    dist[0] = 0;
    for (int step = 0; step < V; step++) {
        /* 1. pick the unfinished vertex with smallest tentative distance */
        int u = -1;
        for (int i = 0; i < V; i++)
            if (!done[i] && (u == -1 || dist[i] < dist[u])) u = i;
        done[u] = 1;
        /* 2. relax every edge leaving u: maybe going through u is cheaper */
        for (int v = 0; v < V; v++)
            if (cost[u][v] > 0 && dist[u] + cost[u][v] < dist[v])
                dist[v] = dist[u] + cost[u][v];
    }
    for (int i = 0; i < V; i++) printf("Shortest distance 0 -> %d = %d\n", i, dist[i]);
    return 0;
}

