            for (int v = 0; v < N; v++)
                if (!in[v] && w[u][v] && w[u][v] < best) { best = w[u][v]; bu = u; bv = v; }
        }
        in[bv] = 1;
        total += best;
        printf("  %d - %d (weight %d)\n", bu, bv, best);
    }
    printf("Total MST weight: %d\n", total);
    return 0;
}

#include <stdio.h>
#define MAXV 8
/* BFS 2-colouring applied to several graphs, one record per graph */
typedef struct { const char *name; int n, m; int e[10][2]; } Rec;

static int is_bipartite(const Rec *r) {
    int g[MAXV][MAXV] = {{0}}, col[MAXV], q[MAXV];
    for (int i = 0; i < r->m; i++) g[r->e[i][0]][r->e[i][1]] = g[r->e[i][1]][r->e[i][0]] = 1;
    for (int i = 0; i < r->n; i++) col[i] = -1;
    for (int s = 0; s < r->n; s++) {
        if (col[s] != -1) continue;
        int h = 0, t = 0;
        col[s] = 0; q[t++] = s;
        while (h < t) {
            int u = q[h++];
            for (int v = 0; v < r->n; v++) {
                if (!g[u][v]) continue;
                if (col[v] < 0) { col[v] = 1 - col[u]; q[t++] = v; }
                else if (col[v] == col[u]) return 0;
            }
        }
    }
    return 1;
}

int main(void) {
    Rec recs[] = {
        {"square",   4, 4, {{0,1},{1,2},{2,3},{3,0}}},
        {"triangle", 3, 3, {{0,1},{1,2},{2,0}}},
        {"tree",     5, 4, {{0,1},{0,2},{1,3},{1,4}}},
        {"pentagon", 5, 5, {{0,1},{1,2},{2,3},{3,4},{4,0}}},
        {"two parts",6, 4, {{0,1},{2,3},{3,4},{4,2}}}
    };
    for (int i = 0; i < 5; i++)
        printf("%-10s : %s\n", recs[i].name, is_bipartite(&recs[i]) ? "bipartite" : "not bipartite");
    return 0;
}

