    int start = 0, bs = 0, be = 0;
    for (int i = 1; i < n; i++)
    {
        if (cur < 0) { cur = a[i]; start = i; }   /* restart if running sum hurts */
        else cur += a[i];
        if (cur > best) { best = cur; bs = start; be = i; }
    }
    printf("Maximum subarray sum = %d\n", best);
    printf("Subarray (index %d to %d):", bs, be);
