}

#include <stdio.h>
#include <stdlib.h>

struct item { int val, idx; };

static int cmp(const void *a, const void *b)
{
    const struct item *x = a, *y = b;
    return (x->val > y->val) - (x->val < y->val);
}

int main(void)
{
    int a[] = {8, 3, 11, 7, 2, 15};
    int n = 6, target = 18;
    struct item it[6];
    for (int i = 0; i < n; i++) { it[i].val = a[i]; it[i].idx = i; }
    qsort(it, n, sizeof it[0], cmp);        /* O(N log N) */
    int lo = 0, hi = n - 1, found = 0;
    while (lo < hi)                         /* two pointers, O(N) */
    {
        int s = it[lo].val + it[hi].val;
        if (s == target)
        {
            printf("%d + %d = %d (indices %d and %d)\n", it[lo].val, it[hi].val,
                   target, it[lo].idx, it[hi].idx);
            found = 1;
            break;
        }
        if (s < target) lo++; else hi--;
    }
    if (!found) printf("No pair adds up to %d\n", target);
    return 0;
}

