#include <stdio.h>
#include <string.h>

int main(void)
{
    const char *a = "photograph", *b = "tomography";
    int n = (int)strlen(a), m = (int)strlen(b);
    int dp[20][20] = {{0}};
    int best = 0, end = 0;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            if (a[i-1] == b[j-1])
            {
                dp[i][j] = dp[i-1][j-1] + 1;   /* extend the matching run */
                if (dp[i][j] > best) { best = dp[i][j]; end = i; }
            }
    printf("A = %s, B = %s\n", a, b);
    printf("Longest common substring: \"%.*s\" (length %d)\n", best, a + end - best, best);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void)
{
    const char *a = "AGGTAB", *b = "GXTXAYB";
    int n = (int)strlen(a), m = (int)strlen(b);
    int dp[20][20] = {{0}};
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            if (a[i-1] == b[j-1]) dp[i][j] = dp[i-1][j-1] + 1;
            else dp[i][j] = dp[i-1][j] > dp[i][j-1] ? dp[i-1][j] : dp[i][j-1];
    char lcs[20];
    int k = dp[n][m];
    lcs[k] = '\0';
    int i = n, j = m;
    while (i > 0 && j > 0)                  /* walk back to rebuild the string */
    {
        if (a[i-1] == b[j-1]) { lcs[--k] = a[i-1]; i--; j--; }
        else if (dp[i-1][j] >= dp[i][j-1]) i--;
        else j--;
    }
    printf("A = %s, B = %s\n", a, b);
    printf("LCS length = %d, LCS = %s\n", dp[n][m], lcs);
    return 0;
}

#include <stdio.h>
#include <string.h>

static int min3(int a, int b, int c)
{
    int m = a < b ? a : b;
    return m < c ? m : c;
}

int main(void)
{
    const char *s = "kitten", *t = "sitting";
    int n = (int)strlen(s), m = (int)strlen(t);
    int d[20][20];
    for (int i = 0; i <= n; i++) d[i][0] = i;   /* delete all */
    for (int j = 0; j <= m; j++) d[0][j] = j;   /* insert all */
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
        {
            int cost = (s[i-1] == t[j-1]) ? 0 : 1;
            d[i][j] = min3(d[i-1][j] + 1, d[i][j-1] + 1, d[i-1][j-1] + cost);
        }
    printf("Edit distance between \"%s\" and \"%s\" = %d\n", s, t, d[n][m]);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int coins[] = {1, 5, 6, 9};
    int nc = 4, amount = 11;
    int dp[50];
    dp[0] = 0;
    for (int a = 1; a <= amount; a++)
    {
        dp[a] = amount + 1;                 /* "infinity" */
        for (int c = 0; c < nc; c++)
            if (coins[c] <= a && dp[a - coins[c]] + 1 < dp[a])
                dp[a] = dp[a - coins[c]] + 1;
    }
    printf("Coins: 1 5 6 9, amount = %d\n", amount);
    if (dp[amount] > amount) printf("Not possible\n");
    else printf("Minimum coins = %d\n", dp[amount]);
    return 0;
}

