#include <stdio.h>

int main(void)
{
    int a[] = {2, 3, 1, 1, 4, 2, 1};
    int n = sizeof a / sizeof a[0];
    int jumps = 0, curEnd = 0, farthest = 0;
    for (int i = 0; i < n - 1; i++)
    {
        if (i + a[i] > farthest) farthest = i + a[i];
        if (i == curEnd)                    /* must jump now */
        {
            jumps++;
            curEnd = farthest;
            if (curEnd >= n - 1) break;
        }
    }
    printf("Minimum jumps to reach the end = %d\n", jumps);
    return 0;
}

