#include <stdio.h>

static int count = 0;

static void swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }

static void permute(int *a, int k, int n)
{
    if (k == n)
    {
        printf("%2d:", ++count);
        for (int i = 0; i < n; i++) printf(" %d", a[i]);
        printf("\n");
        return;
    }
    for (int i = k; i < n; i++)
    {
        swap(&a[k], &a[i]);
        permute(a, k + 1, n);
        swap(&a[k], &a[i]);                 /* backtrack */
    }
}

int main(void)
{
    int a[] = {1, 2, 3, 4};
    printf("All permutations of {1,2,3,4}:\n");
    permute(a, 0, 4);
    return 0;
}

