}

static const struct node *walk(const struct node *p, const char *s)
{
    for (; *s && p; s++) p = p->next[*s - 'a'];
    return p;
}

static void freetrie(struct node *p)
{
    if (!p) return;
    for (int i = 0; i < 26; i++) freetrie(p->next[i]);
    free(p);
}

