struct item { int val, idx; };

static int cmp(const void *a, const void *b)
{
    const struct item *x = a, *y = b;
    return (x->val > y->val) - (x->val < y->val);
}

/* Returns 1 and fills *i, *j with original indices if a pair sums to target. */
static int find_pair(const int *a, int n, int target, int *i, int *j)
{
    struct item it[50];
    if (n > 50) return 0;
    for (int k = 0; k < n; k++) { it[k].val = a[k]; it[k].idx = k; }
    qsort(it, n, sizeof it[0], cmp);
    int lo = 0, hi = n - 1;
    while (lo < hi)
    {
        int s = it[lo].val + it[hi].val;
        if (s == target) { *i = it[lo].idx; *j = it[hi].idx; return 1; }
        if (s < target) lo++; else hi--;
    }
    return 0;
}

