int main(void)
{
    const char *a = "ABCBDAB", *b = "BDCABA";
    int n = (int)strlen(a), m = (int)strlen(b);
    int dp[20][20] = {{0}};
    /* dp[i][j] = LCS length of first i chars of a and first j chars of b */
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
        {
            if (a[i-1] == b[j-1])
                dp[i][j] = dp[i-1][j-1] + 1;           /* match: extend */
            else if (dp[i-1][j] > dp[i][j-1])
                dp[i][j] = dp[i-1][j];                 /* skip a char of a */
            else
                dp[i][j] = dp[i][j-1];                 /* skip a char of b */
        }
    char out[20];
    int k = dp[n][m], i = n, j = m;
    out[k] = '\0';
    while (i > 0 && j > 0)                             /* backtrack through table */
    {
        if (a[i-1] == b[j-1]) { out[--k] = a[i-1]; i--; j--; }
        else if (dp[i-1][j] > dp[i][j-1]) i--;
        else j--;
    }
    printf("A = %s\nB = %s\nLCS length = %d\nOne LCS = %s\n", a, b, dp[n][m], out);
    return 0;
}

