static int edit(const char *s, const char *t)
{
    int n = (int)strlen(s), m = (int)strlen(t);
    int d[30][30];
    if (n == 0) return m;                   /* boundary: empty source */
    if (m == 0) return n;                   /* boundary: empty target */
    if (n > 28 || m > 28) return -1;        /* boundary: too long for table */
    for (int i = 0; i <= n; i++) d[i][0] = i;
    for (int j = 0; j <= m; j++) d[0][j] = j;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
        {
            int best = d[i-1][j-1] + (s[i-1] != t[j-1]);
            if (d[i-1][j] + 1 < best) best = d[i-1][j] + 1;
            if (d[i][j-1] + 1 < best) best = d[i][j-1] + 1;
            d[i][j] = best;
        }
    return d[n][m];
}

