static int lis(const int *a, int n, int *out)
{
    int len[20], prev[20], best = 0, bi = 0;
    for (const int *p = a; p < a + n; p++)
    {
        int i = (int)(p - a);
        len[i] = 1; prev[i] = -1;
        for (const int *q = a; q < p; q++)
        {
            int j = (int)(q - a);
            if (*q < *p && len[j] + 1 > len[i]) { len[i] = len[j] + 1; prev[i] = j; }
        }
        if (len[i] > best) { best = len[i]; bi = i; }
    }
    int *w = out + best;
    for (int i = bi; i != -1; i = prev[i]) *--w = a[i];
    return best;
}

