#include <stdio.h>

struct problem
{
    int nums[10];
    int n;
    int target;
    int possible[10][60];       /* DP table */
};

static int solve(struct problem *p)
{
    for (int i = 0; i <= p->n; i++) p->possible[i][0] = 1;
    for (int s = 1; s <= p->target; s++) p->possible[0][s] = 0;
    for (int i = 1; i <= p->n; i++)
        for (int s = 1; s <= p->target; s++)
        {
            p->possible[i][s] = p->possible[i-1][s];
            if (s >= p->nums[i-1] && p->possible[i-1][s - p->nums[i-1]])
                p->possible[i][s] = 1;
        }
    return p->possible[p->n][p->target];
}

