{
    struct problem p = {{7, 3, 2, 5, 8}, 5, 14, {{0}}};
    if (solve(&p))
    {
        printf("Subset with sum %d:", p.target);
        int s = p.target;
        for (int i = p.n; i > 0 && s > 0; i--)
            if (!p.possible[i-1][s]) { printf(" %d", p.nums[i-1]); s -= p.nums[i-1]; }
        printf("\n");
    }
    else printf("No subset with sum %d\n", p.target);
    return 0;
}

