struct rec { int n, cap; int wt[6], val[6]; };

static int knap(const struct rec *r)
{
    int dp[60] = {0};
    for (int i = 0; i < r->n; i++)
        for (int w = r->cap; w >= r->wt[i]; w--)    /* 1-D table, go downwards */
            if (dp[w - r->wt[i]] + r->val[i] > dp[w])
                dp[w] = dp[w - r->wt[i]] + r->val[i];
    return dp[r->cap];
}

