 */
static int g[9][9] = {
    {0,0,0,2,6,0,7,0,1}, {6,8,0,0,7,0,0,9,0}, {1,9,0,0,0,4,5,0,0},
    {8,2,0,1,0,0,0,4,0}, {0,0,4,6,0,2,9,0,0}, {0,5,0,0,0,3,0,2,8},
    {0,0,9,3,0,0,0,7,4}, {0,4,0,0,5,0,0,3,6}, {7,0,3,0,1,8,0,0,0}
};
static long tries = 0;

static int ok(int r, int c, int v)
{
    for (int i = 0; i < 9; i++)
        if (g[r][i] == v || g[i][c] == v) return 0;
    for (int i = r / 3 * 3; i < r / 3 * 3 + 3; i++)
        for (int j = c / 3 * 3; j < c / 3 * 3 + 3; j++)
            if (g[i][j] == v) return 0;
    return 1;
}

static int solve(void)
{
    for (int r = 0; r < 9; r++)
        for (int c = 0; c < 9; c++)
            if (g[r][c] == 0)
            {
                for (int v = 1; v <= 9; v++)
                    if (ok(r, c, v))
                    {
                        tries++;
                        g[r][c] = v;
                        if (solve()) return 1;
                        g[r][c] = 0;
                    }
                return 0;
            }
    return 1;
}

int main(void)
{
    if (!solve()) { printf("No solution\n"); return 0; }
    for (int r = 0; r < 9; r++)
    {
        for (int c = 0; c < 9; c++) printf("%d%s", g[r][c], c % 3 == 2 ? "  " : " ");
        printf("\n");
        if (r % 3 == 2) printf("\n");
    }
    printf("Digit placements tried: %ld\n", tries);
    return 0;
}

