#include <stdio.h>

static double median(const int *a, int n, const int *b, int m)
{
    int total = n + m, i = 0, j = 0, prev = 0, cur = 0;
    for (int k = 0; k <= total / 2; k++)    /* walk only to the middle */
    {
        prev = cur;
        if (i < n && (j >= m || a[i] <= b[j])) cur = a[i++];
        else cur = b[j++];
    }
    return total % 2 ? cur : (prev + cur) / 2.0;
}

