#include <stdio.h>
#include <stdlib.h>

struct node { struct node *next[26]; int end; };

/* Returns 1 on success, 0 on bad input or allocation failure. */
static int insert(struct node *root, const char *w)
{
    if (!root || !w || !*w) return 0;
    for (const char *p = w; *p; p++)
        if (*p < 'a' || *p > 'z') return 0;     /* reject non-lowercase */
    for (; *w; w++)
    {
        int c = *w - 'a';
        if (!root->next[c])
        {
            root->next[c] = calloc(1, sizeof(struct node));
            if (!root->next[c]) return 0;
        }
        root = root->next[c];
    }
    root->end = 1;
    return 1;
}

/* Returns 2 = whole word, 1 = prefix only, 0 = absent, -1 = invalid query. */
static int search(const struct node *p, const char *s)
{
    if (!p || !s || !*s) return -1;
    for (; *s; s++)
    {
        if (*s < 'a' || *s > 'z') return -1;
        p = p->next[*s - 'a'];
        if (!p) return 0;
    }
    return p->end ? 2 : 1;
}

static void freetrie(struct node *p)
{
    if (!p) return;
    for (int i = 0; i < 26; i++) freetrie(p->next[i]);
    free(p);
}

int main(void)
{
    struct node *root = calloc(1, sizeof *root);
    if (!root) { printf("Out of memory\n"); return 1; }
    const char *add[] = {"tree", "trie", "Tree", "", "try", "a1"};
    for (int i = 0; i < 6; i++)
        printf("insert \"%s\": %s\n", add[i], insert(root, add[i]) ? "ok" : "rejected");
    const char *q[] = {"tree", "tr", "tray", "", "T"};
    const char *msg[] = {"invalid query", "not found", "prefix only", "word found"};
    for (int i = 0; i < 5; i++)
        printf("search \"%s\": %s\n", q[i], msg[search(root, q[i]) + 1]);
    printf("search NULL: %s\n", msg[search(root, NULL) + 1]);
    freetrie(root);
    return 0;
}

#include <stdio.h>

/*
 * Time cost : O(amount * numCoins) - every amount from 1..amount tries each coin once.
 * Space cost: O(amount) - one table dp[] holding the best coin count per amount.
 * (A plain recursive solution would be exponential without this table.)
 */
int main(void)
{
    int coins[] = {2, 3, 7};
    int nc = 3;
    int amounts[] = {12, 13, 1, 0};
    for (int t = 0; t < 4; t++)
    {
        int amount = amounts[t];
        int dp[50];
        dp[0] = 0;
        for (int a = 1; a <= amount; a++)
        {
            dp[a] = amount + 1;
            for (int c = 0; c < nc; c++)
                if (coins[c] <= a && dp[a - coins[c]] + 1 < dp[a])
                    dp[a] = dp[a - coins[c]] + 1;
        }
        if (dp[amount] > amount) printf("amount %2d: impossible\n", amount);
        else printf("amount %2d: %d coin(s)\n", amount, dp[amount]);
    }
    return 0;
}

