static void sort(int a[], int n, int asc)
{
    for (int i = 0; i < n - 1; i++)
        for (int j = 0; j < n - 1 - i; j++)
            if (asc ? a[j] > a[j + 1] : a[j] < a[j + 1]) {
                int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;
            }
}

static void run(int argc, char *argv[])
{
    int data[] = {42, 7, 19, 3, 25};
    int n = 5;
    if (argc != 2) { printf("Usage: %s asc|desc\n", argv[0]); return; }
    if (strcmp(argv[1], "asc") == 0) sort(data, n, 1);
    else if (strcmp(argv[1], "desc") == 0) sort(data, n, 0);
