/* Conventional exit codes: 0 = success, non-zero = a specific failure */
enum { EXIT_OK = 0, EXIT_BAD_ARGS = 1, EXIT_NOT_FOUND = 2, EXIT_RANGE = 3 };

static int process(int value)
{
    if (value < 0) return EXIT_BAD_ARGS;
    if (value > 100) return EXIT_RANGE;
    if (value == 13) return EXIT_NOT_FOUND;
    return EXIT_OK;
}

