/* Returns 0 on success, non-zero error code otherwise */
static int copy_file(const char *src, const char *dst)
{
    FILE *in = fopen(src, "rb");
    if (!in) { printf("Error: cannot open source '%s': %s\n", src, strerror(errno)); return 2; }
    FILE *out = fopen(dst, "wb");
    if (!out) { printf("Error: cannot create '%s'\n", dst); fclose(in); return 3; }
    char buf[64];
    size_t n, total = 0;
    while ((n = fread(buf, 1, sizeof buf, in)) > 0) {
        if (fwrite(buf, 1, n, out) != n) { printf("Error: write failed\n"); fclose(in); fclose(out); return 4; }
        total += n;
    }
    fclose(in); fclose(out);
    printf("Copied %zu bytes: %s -> %s\n", total, src, dst);
    return 0;
}

