/* Parses a whole string as a double; returns 1 if valid */
static int parse(const char *s, double *out)
{
    char *end;
    errno = 0;
    double v = strtod(s, &end);
    if (end == s || *end != '\0' || errno != 0) return 0;
    *out = v;
    return 1;
}

