/* Counts whole-word matches in a line, so "cat" does not match "concatenate" */
static int count_word(const char *line, const char *word)
{
    size_t wl = strlen(word);
    int count = 0;
    for (const char *p = line; (p = strstr(p, word)) != NULL; p++) {
        int left_ok = (p == line) || !isalnum((unsigned char)p[-1]);
        int right_ok = !isalnum((unsigned char)p[wl]);
        if (left_ok && right_ok) count++;
    }
    return count;
}

