/* ===== utility.c : definitions ===== */
void swapInts(int *a, int *b)
{
    int t = *a; *a = *b; *b = t;     /* pointers let us change the caller's variables */
}

int maxOf(const int *arr, int n)
{
    const int *best = arr;
    for (const int *p = arr + 1; p < arr + n; p++)
        if (*p > *best) best = p;
    return *best;
}

