/* ---- mymath.c ---- */
long factorial(int n)
{
    long f = 1;
    for (int i = 2; i <= n; i++) f *= i;
    return f;
}

int gcd(int a, int b)
{
    while (b != 0) { int t = a % b; a = b; b = t; }
    return a;
}

int isPrime(int n)
{
    if (n < 2) return 0;
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) return 0;
    return 1;
}

