static void sortArray(int a[], int n, int descending)
{
    for (int i = 0; i < n - 1; i++)
        for (int j = 0; j < n - 1 - i; j++) {
            int swap = descending ? a[j] < a[j + 1] : a[j] > a[j + 1];
            if (swap) { int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t; }
        }
}

static void show(const char *label, const int a[], int n)
{
    printf("%s:", label);
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n");
}

/* Returns 0 for ascending, 1 for descending, -1 for an unknown choice */
static int parseChoice(const char *s)
{
    if (strcmp(s, "asc") == 0) return 0;
    if (strcmp(s, "desc") == 0) return 1;
    return -1;
}

int main(int argc, char *argv[])
{
    int data[] = {42, 7, 19, 3, 25};
    const char *choice = "desc";
    if (argc > 1) choice = argv[1];
    else printf("No arguments given: using built-in default choice '%s'\n", choice);

    int mode = parseChoice(choice);
    if (mode < 0) {
        printf("Unknown choice '%s' (use asc or desc)\n", choice);
        return 0;
    }
    show("Before", data, 5);
    sortArray(data, 5, mode);
    show("After ", data, 5);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

/* Reads ints from the file one by one and keeps a running total and maximum.
   Time:  O(n) - each number is read exactly once.
   Space: O(1) - only a few variables, the numbers are never stored. */
static int summarise(const char *path, int *count, long *sum, int *max)
{
    FILE *fp = fopen(path, "r");
    if (fp == NULL) return 0;
    int v;
    *count = 0; *sum = 0; *max = 0;
    while (fscanf(fp, "%d", &v) == 1) {
        if (*count == 0 || v > *max) *max = v;
        *sum += v;
        (*count)++;
    }
    fclose(fp);
    return 1;
}

int main(int argc, char *argv[])
{
    const char *path = "nums_demo_1492.txt";
    int created = 0;
    if (argc > 1) path = argv[1];
    else {
        printf("No arguments given: using built-in default file %s\n", path);
        FILE *out = fopen(path, "w");
        if (out == NULL) return 0;
        fputs("12 7 45\n3 19\n", out);
        fclose(out);
        created = 1;
    }
    int count, max;
    long sum;
    if (!summarise(path, &count, &sum, &max)) printf("Cannot open '%s'\n", path);
    else if (count == 0) printf("No numbers found in '%s'\n", path);
    else {
        printf("Numbers read: %d\n", count);
        printf("Sum         : %ld\n", sum);
        printf("Maximum     : %d\n", max);
        printf("Average     : %.2f\n", (double)sum / count);
    }
    if (created) remove(path);
    return 0;
}

