/* Exit codes with a meaning */
enum { EXIT_OK = 0, EXIT_NEGATIVE = 2, EXIT_TOO_BIG = 3, EXIT_ZERO = 4 };

static int classify(long v)
{
    if (v < 0) return EXIT_NEGATIVE;
