        printf("%-13s value=%-11ld -> status %d\n", names[i], tests[i], classify(tests[i]));

    if (argc > 1) {                       /* real use: exit status reflects the argument */
        long v = strtol(argv[1], NULL, 10);
        printf("Argument %ld -> exiting with status %d\n", v, classify(v));
        return classify(v);
