/* Evaluate a single operation.  Time O(1), space O(1): one operation on two numbers,
   no loops, no memory allocation. Returns 0 on error. */
static int calculate(double a, char op, double b, double *result)
{
    switch (op) {
    case '+': *result = a + b; return 1;
    case '-': *result = a - b; return 1;
    case 'x': case '*': *result = a * b; return 1;
    case '/':
        if (b == 0) { printf("Error: division by zero\n"); return 0; }
        *result = a / b; return 1;
    default:
        printf("Error: unknown operator '%c' (use + - x /)\n", op);
        return 0;
    }
}

