/* ---- powlib.c ---- */
long power(int base, int exp)
{
    long r = 1;
    for (int i = 0; i < exp; i++) r *= base;
    return r;
}

long sumToN(int n)
{
    long s = 0;
    for (int i = 1; i <= n; i++) s += i;
    return s;
}

int digitSum(long n)
{
    int s = 0;
    while (n > 0) { s += (int)(n % 10); n /= 10; }
    return s;
}

