#include <stdio.h>

void xor_swap(int *p, int *q)
{
    *p ^= *q;
    *q ^= *p;
    *p ^= *q;
}

int main(void)
{
    int a = 25, b = 70;
    printf("Before: a=%d b=%d\n", a, b);
    xor_swap(&a, &b);
    printf("After : a=%d b=%d\n", a, b);

    /* Limitation 1: same variable passed twice becomes zero */
    int c = 42;
    xor_swap(&c, &c);
    printf("Swapping c with itself gives c=%d (value lost!)\n", c);

    printf("Limitations:\n");
    printf(" - fails if both pointers refer to the same object\n");
    printf(" - works only for integer types, not float or structs\n");
    printf(" - no faster than a temp variable on modern compilers\n");
    printf(" - harder to read and understand\n");
    return 0;
}

