/* swap through pointers using XOR; guard against aliasing */
void swap_xor(int *a, int *b)
{
    if (a == b)
    {
        printf("  (same address - skipping swap, XOR would zero it)\n");
        return;
    }
    *a ^= *b;
    *b ^= *a;
    *a ^= *b;
}

int main(void)
{
    int x = 12, y = 34;
    printf("Before: x=%d y=%d\n", x, y);
    swap_xor(&x, &y);
    printf("After : x=%d y=%d\n", x, y);
    printf("Swapping x with itself:\n");
    swap_xor(&x, &x);
    printf("x=%d\n", x);
    printf("Limitations: only integers, fails on aliased pointers,\n");
    printf("not faster than a temporary, and less readable.\n");
    return 0;
}

