#include <stdio.h>

struct RotJob
{
    unsigned int value;
    int width;
    int k;
};

unsigned int rotl(struct RotJob j)
{
    unsigned int mask = (j.width == 32) ? 0xFFFFFFFFu : ((1u << j.width) - 1u);
    int k = j.k % j.width;
    unsigned int v = j.value & mask;
    if (k == 0)
        return v;
    return ((v << k) | (v >> (j.width - k))) & mask;
}

int main(void)
{
    struct RotJob job = {0x96u, 8, 3};      /* 10010110 */
    printf("value=0x%X width=%d k=%d\n", job.value, job.width, job.k);
    printf("rotated left = 0x%X\n", rotl(job));
    return 0;
}

