/* Cost: unpacking is O(1) time (a shift and a mask per value)
   and O(1) extra space (only a few unsigned ints). The packed
   form itself saves space: 3 small fields fit in one 32-bit int. */
void unpack(unsigned int p, unsigned int *day, unsigned int *month, unsigned int *year)
{
    *day = p & 0x1Fu;               /* 5 bits */
    *month = (p >> 5) & 0xFu;       /* 4 bits */
    *year = (p >> 9) & 0x7Fu;       /* 7 bits, offset from 2000 */
}

int main(void)
{
    unsigned int packed = (25u << 9) | (12u << 5) | 17u;
    unsigned int d, m, y;
    unpack(packed, &d, &m, &y);
    printf("Packed value: %u\n", packed);
    printf("Date: %02u/%02u/%u\n", d, m, 2000 + y);
    return 0;
}

