#include <stdio.h>

unsigned int reverse_bits(unsigned int n, int width)
{
    unsigned int result = 0;
    int i;
    for (i = 0; i < width; i++)
    {
        /* Main logic: shift result left to make room, then copy the
           lowest bit of n into it; n moves right to expose the next bit. */
        result = (result << 1) | (n & 1u);
        n >>= 1;
    }
    return result;
}

int main(void)
{
    unsigned int n = 0x2Cu;         /* 00101100 */
    printf("n = %u\n", n);
    printf("reversed in 8 bits  = %u\n", reverse_bits(n, 8));
    printf("reversed in 6 bits  = %u\n", reverse_bits(n, 6));
    printf("reversed in 16 bits = %u\n", reverse_bits(n, 16));
    return 0;
}

