/* exponentiation by squaring: O(log n) multiplications */
long long power(long long x, int n)
{
    long long result = 1;
    while (n > 0)
    {
        if (n & 1) result *= x;      /* odd bit: multiply in */
        x *= x;                      /* square the base */
        n >>= 1;
    }
    return result;
}

