double a, b, c, d;
double f(double x) { return ((a * x + b) * x + c) * x + d; }

int main(void)
{
    printf("Enter a b c d of ax^3+bx^2+cx+d: ");
    scanf("%lf %lf %lf %lf", &a, &b, &c, &d);
    printf("Bisection method on [-10, 10], scanning for sign changes\n");
    int found = 0;
    for (int i = 0; i < 80; i++)
    {
        double lo = -10 + i * 0.25, hi = lo + 0.25;
        double flo = f(lo), fhi = f(hi);
        if (flo == 0) { printf("Root: %.6f\n", lo); found++; continue; }
        if (flo * fhi < 0)
        {
            for (int k = 0; k < 60; k++)       /* halve the interval */
            {
                double mid = (lo + hi) / 2;
                if (f(lo) * f(mid) <= 0) hi = mid; else lo = mid;
            }
            printf("Root: %.6f\n", (lo + hi) / 2);
            found++;
        }
    }
    printf("%d real root(s) found.\n", found);
    return 0;
}

