}

#include <stdio.h>
#include <math.h>

/* dy/dx = x + y */
double dydx(double x, double y) { return x + y; }

/* Euler's method: y(n+1) = y(n) + h * f(x(n), y(n)) */
double euler(double x0, double y0, double xend, double h)
{
    double x = x0, y = y0;
    int steps = (int)((xend - x0) / h + 0.5);
    for (int i = 0; i < steps; i++)
    {
        y += h * dydx(x, y);
        x += h;
        printf("x = %.2f  y = %.5f  exact = %.5f\n", x, y, 2 * exp(x) - x - 1);
    }
    return y;
}

int main(void)
{
    printf("Solving dy/dx = x + y, y(0) = 1 with h = 0.1\n");
    double y = euler(0, 1, 1.0, 0.1);
    printf("Euler y(1) = %.5f, exact y(1) = %.5f\n", y, 2 * exp(1.0) - 2);
    return 0;
}

