#include <stdio.h>
/* Slab rates: first 100 units 3.00, next 100 units 5.00, rest 7.50 */
static double bill(int units) {
    double amt = 0;
    if (units > 200) { amt += (units - 200) * 7.5; units = 200; }
    if (units > 100) { amt += (units - 100) * 5.0; units = 100; }
    amt += units * 3.0;
    return amt;
}
