#include <stdio.h>
#include <string.h>
#define MAX 10
struct Contact { char name[20]; char phone[15]; };
static struct Contact book[MAX];
static int n = 0;
static int find(const char *name) {
    for (int i = 0; i < n; i++) if (strcmp(book[i].name, name) == 0) return i;
    return -1;
}
int main(void) {
    int ch;
    char name[20], phone[15];
    do {
        printf("\n1.Add 2.Search 3.Update 4.Delete 5.List 6.Exit\nChoice: ");
        if (scanf("%d", &ch) != 1) break;
        if (ch >= 1 && ch <= 4) { printf("Name: "); scanf("%19s", name); }
        if (ch == 1 || ch == 3) { printf("Phone: "); scanf("%14s", phone); }
        int k = (ch >= 1 && ch <= 4) ? find(name) : -1;
        if (ch == 1) {
            if (k >= 0) printf("Already exists.\n");
            else if (n == MAX) printf("Book full.\n");
            else { strcpy(book[n].name, name); strcpy(book[n].phone, phone); n++; printf("Added.\n"); }
        } else if (ch == 2) {
            if (k >= 0) printf("%s: %s\n", book[k].name, book[k].phone); else printf("Not found.\n");
        } else if (ch == 3) {
            if (k >= 0) { strcpy(book[k].phone, phone); printf("Updated.\n"); } else printf("Not found.\n");
        } else if (ch == 4) {
            if (k >= 0) { book[k] = book[--n]; printf("Deleted.\n"); } else printf("Not found.\n");
        } else if (ch == 5) {
            for (int i = 0; i < n; i++) printf("%-10s %s\n", book[i].name, book[i].phone);
        }
    } while (ch != 6);
    return 0;
}

