#include <stdio.h>
static char b[3][3];
static void show(void) {
    for (int i = 0; i < 3; i++) {
        printf(" %c | %c | %c\n", b[i][0], b[i][1], b[i][2]);
        if (i < 2) printf("---+---+---\n");
    }
}
static int win(char c) {
    for (int i = 0; i < 3; i++) {
        if (b[i][0] == c && b[i][1] == c && b[i][2] == c) return 1;
        if (b[0][i] == c && b[1][i] == c && b[2][i] == c) return 1;
    }
    return (b[0][0] == c && b[1][1] == c && b[2][2] == c) ||
           (b[0][2] == c && b[1][1] == c && b[2][0] == c);
}
int main(void) {
    for (int i = 0; i < 9; i++) b[i / 3][i % 3] = ' ';
    char turn = 'X';
    for (int moves = 0; moves < 9; moves++) {
        int r, c;
        show();
        printf("Player %c, enter row and column (1-3): ", turn);
        if (scanf("%d %d", &r, &c) != 2) return 1;
        r--; c--;
        if (r < 0 || r > 2 || c < 0 || c > 2 || b[r][c] != ' ') {
            printf("Invalid move, try again.\n"); moves--; continue;
        }
        b[r][c] = turn;
        if (win(turn)) { show(); printf("Player %c wins!\n", turn); return 0; }
        turn = turn == 'X' ? 'O' : 'X';
    }
    show();
    printf("It's a draw.\n");
    return 0;
}

#include <stdio.h>
static int leap(int y) { return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0; }
int main(void) {
    int month, year;
    const char *names[] = {"January", "February", "March", "April", "May", "June", "July",
                           "August", "September", "October", "November", "December"};
    int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    printf("Enter month and year: ");
    if (scanf("%d %d", &month, &year) != 2 || month < 1 || month > 12 || year < 1) {
        printf("Invalid input.\n"); return 1;
    }
    int d = days[month - 1] + (month == 2 && leap(year));
    /* Zeller-like day of week for the 1st (0 = Sunday), using Sakamoto's method */
    int t[] = {0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4};
    int y = year - (month < 3);
    int start = (y + y / 4 - y / 100 + y / 400 + t[month - 1] + 1) % 7;
    printf("\n   %s %d\n", names[month - 1], year);
    printf("Su Mo Tu We Th Fr Sa\n");
    for (int i = 0; i < start; i++) printf("   ");
    for (int day = 1; day <= d; day++) {
        printf("%2d ", day);
        if ((start + day) % 7 == 0) printf("\n");
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <time.h>
/* Stopwatch-style: elapsed time between two fixed timestamps (deterministic) plus a real clock() call */
int main(void) {
    struct tm start = {0}, stop = {0};
    start.tm_year = 124; start.tm_mon = 0; start.tm_mday = 1;
    start.tm_hour = 9; start.tm_min = 15; start.tm_sec = 30; start.tm_isdst = -1;
    stop = start;
    stop.tm_hour = 11; stop.tm_min = 47; stop.tm_sec = 5;
    double secs = difftime(mktime(&stop), mktime(&start));
    int total = (int)secs;
    printf("Start  : 09:15:30\nStop   : 11:47:05\n");
    printf("Elapsed: %d s = %02d:%02d:%02d\n", total, total / 3600, (total % 3600) / 60, total % 60);
    clock_t c0 = clock();
    clock_t c1 = clock();
    printf("clock() is %s\n", c1 >= c0 ? "monotonic" : "not monotonic");
    return 0;
}

#include <stdio.h>
#include <time.h>
/* Digital clock: a loop that advances a fixed starting time using gmtime/mktime-free arithmetic */
int main(void) {
    time_t t = 86400L * 365 + 23 * 3600 + 59 * 60 + 57;   /* 1971-01-01 23:59:57 UTC */
    for (int i = 0; i < 6; i++, t++) {
        struct tm *tm = gmtime(&t);
        char buf[40];
        strftime(buf, sizeof buf, "%Y-%m-%d %H:%M:%S", tm);
        printf("[%s]\n", buf);
    }
    return 0;
}

