/* Compute net salary from basic pay; HRA 20%, DA 10%, tax 10% of gross */
double netSalary(double basic, double *gross, double *tax)
{
    double hra = 0.20 * basic;
    double da = 0.10 * basic;
    *gross = basic + hra + da;
    *tax = 0.10 * (*gross);
    return *gross - *tax;
}

