/* Slabs: first 100 units Rs5, next 100 units Rs7, above 200 units Rs10 */
double bill(int units)
{
    double amt = 0;
    if (units <= 100) amt = units * 5.0;
    else if (units <= 200) amt = 100 * 5.0 + (units - 100) * 7.0;
    else amt = 100 * 5.0 + 100 * 7.0 + (units - 200) * 10.0;
    return amt;
}

