#include <stdio.h>
#include <string.h>

#define MAX 10

struct Contact { char name[20]; char phone[15]; };

struct Contact book[MAX];
int count = 0;

int find(const char *name)
{
    int i;
    for (i = 0; i < count; i++)
        if (strcmp(book[i].name, name) == 0) return i;
    return -1;
}

int main(void)
{
    int choice, i, idx;
    char name[20], phone[15];

    while (1) {
        printf("\n1.Add 2.Search 3.Update 4.Delete 5.List 6.Exit: ");
        if (scanf("%d", &choice) != 1 || choice == 6) break;
        if (choice == 1) {
            if (count == MAX) { printf("Book full\n"); continue; }
            scanf("%19s %14s", book[count].name, book[count].phone);
            count++;
            printf("Added.\n");
        } else if (choice == 2) {
            scanf("%19s", name);
            idx = find(name);
            if (idx < 0) printf("Not found\n"); else printf("%s : %s\n", book[idx].name, book[idx].phone);
        } else if (choice == 3) {
            scanf("%19s %14s", name, phone);
            idx = find(name);
            if (idx < 0) printf("Not found\n"); else { strcpy(book[idx].phone, phone); printf("Updated.\n"); }
        } else if (choice == 4) {
            scanf("%19s", name);
            idx = find(name);
            if (idx < 0) printf("Not found\n");
            else {
                for (i = idx; i < count - 1; i++) book[i] = book[i + 1];  /* shift left */
                count--;
                printf("Deleted.\n");
            }
        } else if (choice == 5) {
            for (i = 0; i < count; i++) printf("%d. %s - %s\n", i + 1, book[i].name, book[i].phone);
        } else printf("Invalid choice\n");
    }
    printf("Bye\n");
    return 0;
}

