/* comparison: key first, element second; return <0, 0, >0 */
static int cmp(const void *key, const void *elem)
{
    int k = *(const int *)key, e = *(const int *)elem;
    return (k > e) - (k < e);
}

int main(void)
{
    int sorted[] = {5, 10, 15, 20, 25, 30};       /* bsearch needs sorted data */
    int n = (int)(sizeof sorted / sizeof sorted[0]);
    int keys[] = {5, 25, 12};
    for (int i = 0; i < 3; i++)
    {
        /* bsearch repeatedly halves the range and calls cmp */
        int *p = bsearch(&keys[i], sorted, (size_t)n, sizeof sorted[0], cmp);
        if (p) printf("Key %d found at index %d\n", keys[i], (int)(p - sorted));
        else   printf("Key %d not found\n", keys[i]);
    }
    return 0;
}

