#define SIZE 5

/* Returns 1 and stores value if idx is inside the array, else 0. */
static int get_item(const int a[], int n, int idx, int *out) {
    if (idx < 0 || idx >= n) return 0;
    *out = a[idx];
    return 1;
}

/* Sum of a[from..to], range is clamped to the valid bounds. */
static int range_sum(const int a[], int n, int from, int to) {
    if (from < 0) from = 0;
    if (to > n - 1) to = n - 1;
    int s = 0;
    for (int i = from; i <= to; i++) s += a[i];
    return s;
}

int main(void) {
    int a[SIZE] = {10, 20, 30, 40, 50};
    int tests[] = {0, 4, 5, -1, 2};
    for (int i = 0; i < 5; i++) {
        int v;
        if (get_item(a, SIZE, tests[i], &v)) printf("a[%d] = %d\n", tests[i], v);
        else printf("index %d rejected (valid 0..%d)\n", tests[i], SIZE - 1);
    }
    printf("range_sum(-3, 2) = %d\n", range_sum(a, SIZE, -3, 2));
    printf("range_sum(3, 99) = %d\n", range_sum(a, SIZE, 3, 99));
    return 0;
}

