/* Calculator returning 0 on error (division by zero), 1 on success. */
static int calc(long long a, char op, long long b, long long *r) {
    switch (op) {
    case '+': *r = a + b; return 1;
    case '-': *r = a - b; return 1;
    case '*': *r = a * b; return 1;
    case '/': if (b == 0) return 0; *r = a / b; return 1;
    }
    return 0;
}

int main(void) {
    struct { long long a; char op; long long b; } t[] = {
        {0, '+', 0}, {7, '*', 0}, {7, '/', 0}, {-8, '+', 3}, {-8, '*', -3},
        {-9, '/', 2}, {2000000000LL, '+', 2000000000LL}, {100000LL, '*', 100000LL}
    };
    int n = (int)(sizeof t / sizeof t[0]);
    for (int i = 0; i < n; i++) {
        long long r;
        printf("%lld %c %lld = ", t[i].a, t[i].op, t[i].b);
        if (calc(t[i].a, t[i].op, t[i].b, &r)) printf("%lld\n", r);
        else printf("ERROR (division by zero)\n");
    }
    return 0;
}

