#include <stdio.h>

/* Kadane's algorithm: maximum sum of a contiguous sub-array in O(n).
 * Idea: best_ending_here is the best sum of a run that ends at the current
 * element. A negative running sum can only hurt a later run, so we drop it
 * and start fresh at the current element. */
static int max_subarray(const int a[], int n) {
    int best_ending_here = a[0], best_overall = a[0];
    for (int i = 1; i < n; i++) {
        /* extend previous run, or start a new run at a[i] */
        best_ending_here = (best_ending_here > 0) ? best_ending_here + a[i] : a[i];
        if (best_ending_here > best_overall) best_overall = best_ending_here;
    }
    return best_overall;
}

int main(void) {
    int a[] = {-2, 1, -3, 4, -1, 2, 1, -5, 4};
    printf("Maximum sub-array sum = %d\n", max_subarray(a, 9));   /* 4,-1,2,1 = 6 */
    int b[] = {-3, -1, -2};
    printf("All negative array    = %d\n", max_subarray(b, 3));
    return 0;
}

