/* Returns 1 on success; refuses to divide when the count is zero. */
static int average(const int a[], int n, double *avg) {
    if (n <= 0) return 0;               /* guard against division by zero */
    int s = 0;
    for (int i = 0; i < n; i++) s += a[i];
    *avg = (double)s / n;
    return 1;
}

int main(void) {
    int a[] = {4, 8, 6};
    double r;
    if (average(a, 3, &r)) printf("Average of 3 values = %.2f\n", r);
    if (average(a, 0, &r)) printf("Average = %.2f\n", r);
    else printf("Average of 0 values: refused, would divide by zero\n");
    int divisors[] = {5, 0, -2};
    for (int i = 0; i < 3; i++) {
        if (divisors[i] == 0) printf("100 / %d skipped (zero divisor)\n", divisors[i]);
        else printf("100 / %d = %d\n", divisors[i], 100 / divisors[i]);
    }
    return 0;
}

