#include <stdio.h>
#include <stdlib.h>

static int allocs = 0, frees = 0;

static int *xmalloc_ints(size_t n) {
    int *p = malloc(n * sizeof *p);
    if (p) allocs++;
    return p;
}

static void xfree(int *p) {
    if (p) { free(p); frees++; }
}

/* Builds a squares table; every early exit frees what was allocated. */
static int build(int n) {
    int *a = xmalloc_ints((size_t)n);
    if (!a) return -1;
    int *b = xmalloc_ints((size_t)n);
    if (!b) { xfree(a); return -1; }    /* avoid leaking a */
    int s = 0;
    for (int i = 0; i < n; i++) { a[i] = i * i; b[i] = a[i] + 1; s += b[i]; }
    xfree(a);
    xfree(b);
    return s;
}

int main(void) {
    printf("build(5) = %d\n", build(5));
    printf("build(3) = %d\n", build(3));
    printf("allocations = %d, frees = %d -> %s\n", allocs, frees,
           allocs == frees ? "no leaks" : "LEAK");
    return 0;
}

