/* Invariant: during the loop the array prefix a[0..i-1] is always sorted. */
static void insertion_sort(int a[], int n) {
    for (int i = 1; i < n; i++) {
        int key = a[i], j = i - 1;
        while (j >= 0 && a[j] > key) { a[j + 1] = a[j]; j--; }
        a[j + 1] = key;
        for (int k = 1; k <= i; k++) assert(a[k - 1] <= a[k]);   /* invariant check */
    }
}

int main(void) {
    int a[] = {5, 2, 9, 1, 7, 3};
    insertion_sort(a, 6);
    for (int i = 0; i < 6; i++) printf("%d ", a[i]);
    printf("\nAll invariant assertions passed.\n");
    return 0;
}

#include <stdio.h>
#include <assert.h>

/* int_sqrt: floor of the square root.
 * Precondition : n >= 0
 * Postcondition: r*r <= n < (r+1)*(r+1) */
static int int_sqrt(int n) {
    assert(n >= 0);
    int r = 0;
    while ((long)(r + 1) * (r + 1) <= n) r++;
    assert((long)r * r <= n && n < (long)(r + 1) * (r + 1));
    return r;
}

int main(void) {
    int tests[] = {0, 1, 15, 16, 99, 100};
    for (int i = 0; i < 6; i++)
        printf("int_sqrt(%d) = %d\n", tests[i], int_sqrt(tests[i]));
    return 0;
}

