static int my_strlen(const char *s) {
    int n = 0;
    while (s[n] != '\0') n++;
    return n;
}

static int failures = 0;
static void check(const char *s, int expected) {
    int got = my_strlen(s);
    printf("my_strlen(\"%s\") = %d, expected %d -> %s\n", s, got, expected,
           got == expected ? "ok" : "FAIL");
    if (got != expected) failures++;
}

int main(void) {
    check("", 0);
    check("a", 1);
    check("hello", 5);
    check("two words", 9);
    check("tab\there", 7);
    printf("%d failure(s)\n", failures);
    return 0;
}

#include <stdio.h>

static void bubble(int a[], int n) {
    for (int i = 0; i + 1 < n; i++)
        for (int j = 0; j + 1 < n - i; j++)
            if (a[j] > a[j + 1]) { int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t; }
}

static void run(const char *name, int a[], int n) {
    printf("%-10s before:", name);
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    bubble(a, n);
    printf("  after:");
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n");
}

int main(void) {
    int empty[1] = {0};
    int one[] = {42};
    int dup[] = {4, 2, 4, 1, 2, 2};
    run("empty", empty, 0);
    run("single", one, 1);
    run("duplicates", dup, 6);
    return 0;
}

#include <stdio.h>

static int bsearch_idx(const int a[], int n, int key) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == key) return mid;
        if (a[mid] < key) lo = mid + 1; else hi = mid - 1;
    }
    return -1;
}

int main(void) {
    int a[] = {2, 5, 8, 12, 16, 23, 38};
    int keys[] = {16, 2, 38, 1, 40, 9};
    for (int i = 0; i < 6; i++) {
        int r = bsearch_idx(a, 7, keys[i]);
        if (r >= 0) printf("key %2d found at index %d\n", keys[i], r);
        else printf("key %2d absent -> returned %d\n", keys[i], r);
    }
    printf("Empty array search for 5 -> %d\n", bsearch_idx(a, 0, 5));
    return 0;
}

