/* Returns number of lines, or -1 if the file cannot be opened. */
static int count_lines(const char *name) {
    FILE *f = fopen(name, "r");
    if (!f) return -1;
    int lines = 0, c;
    while ((c = fgetc(f)) != EOF) if (c == '\n') lines++;
    fclose(f);
    return lines;
}

int main(void) {
    const char *name = "t1724.txt";
    remove(name);                        /* make sure it does not exist */
    int r = count_lines(name);
    if (r < 0) printf("Test 1: missing file handled -> error reported\n");
    else printf("Test 1 FAILED\n");

    FILE *f = fopen(name, "w");
    if (!f) { printf("cannot create sample file\n"); return 1; }
    fputs("one\ntwo\nthree\n", f);
    fclose(f);
    printf("Test 2: existing file has %d lines\n", count_lines(name));
    remove(name);
    return 0;
}

