#define MAX 20

/* input: reads count and values; returns count or -1 on error */
static int read_values(int a[], int max) {
    int n;
    printf("How many numbers (1-%d)? ", max);
    if (scanf("%d", &n) != 1 || n < 1 || n > max) return -1;
    for (int i = 0; i < n; i++) {
        printf("Enter number %d: ", i + 1);
        if (scanf("%d", &a[i]) != 1) return -1;
    }
    return n;
}

/* processing: computes sum and average */
static double process(const int a[], int n, int *sum) {
    *sum = 0;
    for (int i = 0; i < n; i++) *sum += a[i];
    return (double)*sum / n;
}

/* output: prints the results */
static void show(int n, int sum, double avg) {
    printf("Count   : %d\nSum     : %d\nAverage : %.2f\n", n, sum, avg);
}

int main(void) {
    int a[MAX], sum;
    int n = read_values(a, MAX);
    if (n < 0) { printf("Invalid input\n"); return 0; }
    double avg = process(a, n, &sum);
    show(n, sum, avg);
    return 0;
}

#include <stdio.h>

#define SIZE 5

/* Safe read: returns 1 on success, 0 if index is out of range. */
static int get_at(const int a[], int n, int idx, int *out) {
    if (idx < 0 || idx >= n) return 0;
    *out = a[idx];
    return 1;
}

/* Safe write with the same boundary check. */
static int set_at(int a[], int n, int idx, int value) {
    if (idx < 0 || idx >= n) return 0;
    a[idx] = value;
    return 1;
}

int main(void) {
    int a[SIZE] = {10, 20, 30, 40, 50};
    int tests[] = {0, 4, 5, -1, 2};
    int count = (int)(sizeof tests / sizeof tests[0]);
    for (int i = 0; i < count; i++) {
        int v;
        if (get_at(a, SIZE, tests[i], &v))
            printf("a[%d] = %d\n", tests[i], v);
        else
            printf("a[%d] -> index out of bounds, access refused\n", tests[i]);
    }
    printf("set_at(a,5,2,99) -> %s\n", set_at(a, SIZE, 2, 99) ? "ok" : "refused");
    printf("set_at(a,5,7,99) -> %s\n", set_at(a, SIZE, 7, 99) ? "ok" : "refused");
    printf("a[2] is now %d\n", a[2]);
    return 0;
}

#include <stdio.h>
#include <math.h>

/* Calculator: returns 0 on success and stores result, nonzero on error. */
static int calc(double x, char op, double y, double *r) {
    switch (op) {
    case '+': *r = x + y; return 0;
    case '-': *r = x - y; return 0;
    case '*': *r = x * y; return 0;
    case '/':
        if (y == 0.0) return 1;       /* division by zero */
        *r = x / y; return 0;
    default: return 2;                /* unknown operator */
    }
}

int main(void) {
    double x, y, r;
    char op;
    printf("Enter expressions like: 12 + 5 (end of input stops)\n");
    while (1) {
        printf("> ");
        int got = scanf("%lf %c %lf", &x, &op, &y);
        if (got == EOF) break;
        if (got != 3) { printf("\nError: expected 'number operator number'\n"); break; }
        int e = calc(x, op, y, &r);
        if (e == 1) printf("\nError: division by zero\n");
        else if (e == 2) printf("\nError: unknown operator '%c'\n", op);
        else if (!isfinite(r)) printf("\nError: result overflow\n");
        else printf("\n%g %c %g = %g\n", x, op, y, r);
    }
    printf("\nBye\n");
    return 0;
}

#include <stdio.h>

/* Returns 1 if n is prime. Trial division up to sqrt(n). */
static int is_prime(int n) {
    if (n < 2) return 0;
    for (int d = 2; d * d <= n; d++)
        if (n % d == 0) return 0;
    return 1;
}

int main(void) {
    /* test cases: input and expected result */
    struct { int n; int expected; } tests[] = {
        {-5, 0}, {0, 0}, {1, 0}, {2, 1}, {3, 1}, {4, 0},
        {17, 1}, {49, 0}, {97, 1}, {100, 0}
    };
    int count = (int)(sizeof tests / sizeof tests[0]), pass = 0;
    for (int i = 0; i < count; i++) {
        int got = is_prime(tests[i].n);
        int ok = (got == tests[i].expected);
        pass += ok;
        printf("is_prime(%3d) = %d expected %d  %s\n",
               tests[i].n, got, tests[i].expected, ok ? "PASS" : "FAIL");
    }
    printf("%d of %d tests passed\n", pass, count);
    return 0;
}

