/* A year is leap if divisible by 4, except century years,
   which must also be divisible by 400. */
static int is_leap(int y) {
    return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
}

int main(void) {
    int years[]    = {1900, 2000, 2004, 2023, 2024, 2100, 1600, 1};
    int expected[] = {0,    1,    1,    0,    1,    0,    1,    0};
    int n = (int)(sizeof years / sizeof years[0]);
    for (int i = 0; i < n; i++) {
        int r = is_leap(years[i]);
        printf("Year %4d: %-8s expected %-8s %s\n", years[i],
               r ? "leap" : "not leap", expected[i] ? "leap" : "not leap",
               r == expected[i] ? "OK" : "MISMATCH");
    }
    return 0;
}

