#include <string.h>

/* Palindrome check ignoring case and non-alphanumeric characters.
   Empty and single-character strings are palindromes. */
static int is_palindrome(const char *s) {
    int i = 0, j = (int)strlen(s) - 1;
    while (i < j) {
        while (i < j && !isalnum((unsigned char)s[i])) i++;
        while (i < j && !isalnum((unsigned char)s[j])) j--;
        if (tolower((unsigned char)s[i]) != tolower((unsigned char)s[j])) return 0;
        i++; j--;
    }
    return 1;
}

int main(void) {
    const char *tests[] = {
        "", "a", "ab", "aa", "madam", "Madam", "A man, a plan, a canal: Panama",
        "hello", "  ", "12321", "12345"
    };
    int n = (int)(sizeof tests / sizeof tests[0]);
    for (int i = 0; i < n; i++)
        printf("\"%s\" -> %s\n", tests[i], is_palindrome(tests[i]) ? "palindrome" : "not palindrome");
    return 0;
}

#include <stdio.h>

/* Reusable helper: reads a prompted number (replaces repeated scanf code). */
static int ask(const char *prompt, double *v) {
    printf("%s", prompt);
    return scanf("%lf", v) == 1;
}

/* Reusable helper: prints a labelled result. */
static void report(const char *label, double value) {
    printf("%s = %.2f\n", label, value);
}

int main(void) {
    int choice;
    do {
        printf("\n1. Rectangle area\n2. Triangle area\n3. Circle area\n0. Exit\nChoice: ");
        if (scanf("%d", &choice) != 1) break;
        double a, b;
        switch (choice) {
        case 1:
            if (ask("Length: ", &a) && ask("Width: ", &b)) report("Area", a * b);
            break;
        case 2:
            if (ask("Base: ", &a) && ask("Height: ", &b)) report("Area", 0.5 * a * b);
            break;
        case 3:
            if (ask("Radius: ", &a)) report("Area", 3.14159 * a * a);
            break;
        case 0: printf("Goodbye\n"); break;
        default: printf("Invalid choice\n");
        }
    } while (choice != 0);
    return 0;
}

