#include <stdio.h>

/* Euclid's algorithm (non-obvious part):
   gcd(a, b) == gcd(b, a mod b). Each step shrinks b, so it
   ends when b becomes 0; the remaining a is the answer. */
static int gcd(int a, int b) {
    while (b != 0) {
        int r = a % b;   /* remainder is always smaller than b */
        a = b;
        b = r;
    }
    return a;
}

int main(void) {
    int pairs[][2] = {{48, 18}, {17, 5}, {100, 75}, {0, 9}, {270, 192}};
    int n = (int)(sizeof pairs / sizeof pairs[0]);
    for (int i = 0; i < n; i++)
        printf("gcd(%d, %d) = %d\n", pairs[i][0], pairs[i][1], gcd(pairs[i][0], pairs[i][1]));
    return 0;
}

#include <stdio.h>

/* Fixed version: all warnings corrected.
   Typical warnings fixed here: unused parameter, sign compare,
   format mismatch, missing return. */
static void swap(int *p, int *q) {
    int t = *p;
    *p = *q;
    *q = t;
}

static long sum_array(const int *p, size_t n) {
    long s = 0;
    for (size_t i = 0; i < n; i++)    /* size_t vs size_t: no sign-compare warning */
        s += *(p + i);
    return s;
}

int main(void) {
    int a = 3, b = 8;
    int arr[] = {1, 2, 3, 4, 5};
    size_t n = sizeof arr / sizeof arr[0];
    swap(&a, &b);
    printf("after swap: a=%d b=%d\n", a, b);
    printf("sum of %zu elements = %ld\n", n, sum_array(arr, n));   /* %zu matches size_t */
    return 0;
}

#include <stdio.h>

/* Safe average: refuses to divide when count is zero. */
static int safe_average(const int a[], int n, double *avg) {
    if (n <= 0) return 0;
    long s = 0;
    for (int i = 0; i < n; i++) s += a[i];
    *avg = (double)s / n;
    return 1;
}

int main(void) {
    int num[]  = {10, 20, 30, 40};
    int den[]  = {2, 0, 5, 0};
    int empty[1] = {0};
    double avg;

    /* element-wise division with a zero check on every divisor */
    for (int i = 0; i < 4; i++) {
        if (den[i] == 0) printf("%d / %d : skipped (division by zero)\n", num[i], den[i]);
        else printf("%d / %d = %.2f\n", num[i], den[i], (double)num[i] / den[i]);
    }
    if (safe_average(num, 4, &avg)) printf("Average of 4 values = %.2f\n", avg);
    if (!safe_average(empty, 0, &avg)) printf("Average of 0 values: refused (would divide by zero)\n");
    return 0;
}

#include <stdio.h>
#include <stddef.h>

#define CAP 4

/* A fixed buffer that tracks its length, so every access can be checked. */
struct Buffer {
    int data[CAP];
    size_t len;
};

static int push(struct Buffer *b, int v) {
    if (b->len >= CAP) return 0;       /* would overflow */
    b->data[b->len++] = v;
    return 1;
}

static int at(const struct Buffer *b, size_t i, int *out) {
    if (i >= b->len) return 0;         /* would read out of bounds */
    *out = b->data[i];
    return 1;
}

int main(void) {
    struct Buffer buf = { {0}, 0 };
    for (int v = 10; v <= 60; v += 10)
        printf("push(%d): %s\n", v, push(&buf, v) ? "stored" : "rejected, buffer full");
    for (size_t i = 0; i < 6; i++) {
        int v;
        if (at(&buf, i, &v)) printf("buf[%zu] = %d\n", i, v);
        else printf("buf[%zu]: out of bounds\n", i);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Record { int id; char *name; };

static int allocs = 0, frees = 0;   /* counters for leak checking */

static struct Record *make(int id, const char *name) {
    struct Record *r = malloc(sizeof *r);
    if (!r) return NULL;
    r->name = malloc(strlen(name) + 1);
    if (!r->name) { free(r); return NULL; }
    strcpy(r->name, name);
    r->id = id;
    allocs += 2;
    return r;
}

static void destroy(struct Record *r) {
    if (!r) return;
    free(r->name); frees++;      /* free the inner block first */
    free(r);       frees++;
}

int main(void) {
    const char *names[] = {"Asha", "Ravi", "Meena", "John"};
    struct Record *recs[4];
    for (int i = 0; i < 4; i++) {
        recs[i] = make(i + 1, names[i]);
        if (!recs[i]) { printf("allocation failed\n"); return 1; }
        printf("Record %d: %s\n", recs[i]->id, recs[i]->name);
    }
    for (int i = 0; i < 4; i++) destroy(recs[i]);
    printf("allocations=%d frees=%d -> %s\n", allocs, frees,
           allocs == frees ? "no leak" : "LEAK");
    return 0;
}

