struct Check { double a, b; char op; double expected; };

/* Returns 0 if the operands are invalid for the operation. */
static int valid(double b, char op) { return !(op == '/' && b == 0.0); }

static double compute(double a, double b, char op) {
    switch (op) {
    case '+': return a + b;
    case '-': return a - b;
    case '*': return a * b;
    default:  return a / b;
    }
}

int main(void) {
