    };
    int n = (int)(sizeof t / sizeof t[0]);
    for (int i = 0; i < n; i++) {
        if (!valid(t[i].b, t[i].op)) {      /* check before processing */
            printf("Test %d: %g %c %g -> INVALID INPUT, skipped\n", i + 1, t[i].a, t[i].op, t[i].b);
            continue;
        }
        double actual = compute(t[i].a, t[i].b, t[i].op);
        printf("Test %d: %g %c %g expected %g actual %g -> %s\n", i + 1, t[i].a, t[i].op,
               t[i].b, t[i].expected, actual, actual == t[i].expected ? "PASS" : "FAIL");
    }
