#include <stdio.h>

/* Reads integers until EOF or bad input. Returns how many were read. */
static int read_all(int a[], int max, int *hit_eof) {
    int n = 0, v, r;
    *hit_eof = 0;
    while (n < max && (r = scanf("%d", &v)) != EOF) {
        if (r != 1) break;               /* non-numeric input */
        a[n++] = v;
    }
    if (n < max && r == EOF) *hit_eof = 1;
    return n;
}

static long total(const int a[], int n) {
    long s = 0;
    for (int i = 0; i < n; i++) s += a[i];
    return s;
}

int main(void) {
    int a[50], eof;
    printf("Enter integers (Ctrl+D / end of input to stop): ");
    int n = read_all(a, 50, &eof);
    printf("\nRead %d value(s), EOF %s\n", n, eof ? "reached" : "not reached");
    printf("Sum = %ld\n", total(a, n));
    return 0;
}

#include <stdio.h>
#include <assert.h>

/* Binary search. Invariant: if key exists, it lies in a[lo..hi].
   Time O(log n), extra space O(1). The sortedness check below is
   O(n) and is only for the demonstration (disabled by -DNDEBUG). */
static int bsearch_idx(const int a[], int n, int key) {
    for (int i = 1; i < n; i++) assert(a[i - 1] <= a[i]);   /* precondition */
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        assert(lo >= 0 && hi < n);        /* invariant: window inside array */
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == key) return mid;
        if (a[mid] < key) lo = mid + 1; else hi = mid - 1;
    }
    return -1;
}

int main(void) {
    int a[] = {2, 5, 8, 12, 16, 23, 38, 56};
    int n = (int)(sizeof a / sizeof a[0]);
    int keys[] = {23, 2, 56, 7};
    for (int i = 0; i < 4; i++) {
        int r = bsearch_idx(a, n, keys[i]);
        if (r >= 0) printf("%d found at index %d\n", keys[i], r);
        else printf("%d not found\n", keys[i]);
    }
    return 0;
}

#include <stdio.h>
#include <limits.h>
#include <assert.h>

/* clamp_add: adds a and b, saturating at INT_MIN/INT_MAX.
   Precondition : none (any ints allowed).
   Postcondition: INT_MIN <= result <= INT_MAX and, when no overflow
                  would occur, result == a + b. */
static int clamp_add(int a, int b) {
    if (b > 0 && a > INT_MAX - b) return INT_MAX;
    if (b < 0 && a < INT_MIN - b) return INT_MIN;
    return a + b;
}

static void test(int a, int b, int expected, const char *label) {
    int r = clamp_add(a, b);
    assert(r >= INT_MIN && r <= INT_MAX);
    printf("%-8s clamp_add(%d, %d) = %d  %s\n", label, a, b, r, r == expected ? "PASS" : "FAIL");
}

int main(void) {
    test(2, 3, 5, "normal");
    test(-4, 9, 5, "normal");
    test(INT_MIN, 0, INT_MIN, "minimum");
    test(INT_MIN, -1, INT_MIN, "minimum");
    test(INT_MAX, 0, INT_MAX, "maximum");
    test(INT_MAX, 1, INT_MAX, "maximum");
    return 0;
}

