/* Small functions replace one long function; no globals are used. */
static void fill(int a[], int n) {
    for (int i = 0; i < n; i++) a[i] = (i * 7 + 3) % 10;   /* 3 0 7 4 1 8 */
}

static int find_max(const int a[], int n) {
    int m = a[0];
    for (int i = 1; i < n; i++) if (a[i] > m) m = a[i];
    return m;
}

