/* Mini-project: Stock checker
 * Input   : lines "item quantity price" (parsed from a built-in text list).
 * Output  : per-item value and the total stock value.
 * Limits  : at most 10 items, names up to 15 chars, quantity 0..10000.
 * Failures: bad lines are reported and skipped; no crash on bad data.
 */
#include <stdio.h>

#define MAXITEMS 10

struct Item { char name[16]; int qty; double price; };

static int parse(const char *line, struct Item *it) {
    char extra;
    if (sscanf(line, "%15s %d %lf %c", it->name, &it->qty, &it->price, &extra) != 3) return 0;
    return it->qty >= 0 && it->qty <= 10000 && it->price >= 0;
}

int main(void) {
    const char *lines[] = {
        "pen 100 2.5", "book 20 45.0", "bad line", "ruler -3 1.0", "bag 5 300", "eraser 50 abc"
    };
    struct Item items[MAXITEMS];
    int n = 0, count = (int)(sizeof lines / sizeof lines[0]);
    double total = 0;
    for (int i = 0; i < count && n < MAXITEMS; i++) {
        if (!parse(lines[i], &items[n])) {
            printf("Line %d rejected: \"%s\"\n", i + 1, lines[i]);
            continue;
        }
        double v = items[n].qty * items[n].price;
        printf("%-8s qty=%4d price=%7.2f value=%8.2f\n", items[n].name, items[n].qty, items[n].price, v);
        total += v;
        n++;
    }
    printf("Accepted %d items, total value = %.2f\n", n, total);
    return 0;
}

