#include <stdio.h>

/* Kadane's algorithm: the best subarray ending at index i is either
   a[i] alone or a[i] added to the best subarray ending at i-1.
   We keep the running best and restart when the running sum drops
   below the current element. O(n) time, O(1) space. */
static int max_subarray(const int a[], int n) {
    int cur = a[0], best = a[0];
    for (int i = 1; i < n; i++) {
        cur = (cur + a[i] > a[i]) ? cur + a[i] : a[i];   /* extend or restart */
        if (cur > best) best = cur;
    }
    return best;
}

int main(void) {
    int a[30], n;
    printf("How many elements (1-30)? ");
    if (scanf("%d", &n) != 1 || n < 1 || n > 30) { printf("Invalid size\n"); return 0; }
    printf("Enter %d integers: ", n);
    for (int i = 0; i < n; i++)
        if (scanf("%d", &a[i]) != 1) { printf("Invalid number\n"); return 0; }
    printf("Maximum subarray sum = %d\n", max_subarray(a, n));
    return 0;
}

