/* Returns the percentage part/whole*100; sets *ok to 0 when whole is 0. */
static double percent(double part, double whole, int *ok) {
    if (whole == 0.0) { *ok = 0; return 0.0; }   /* guard: avoid dividing by zero */
    *ok = 1;
    return part * 100.0 / whole;
}

