        if (ok) printf("%g of %g = %.1f%%\n", parts[i], wholes[i], p);
        else    printf("%g of %g : cannot compute, total is zero\n", parts[i], wholes[i]);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int live = 0;                          /* blocks currently allocated */
    for (int round = 1; round <= 4; round++) {
        int n = round * 3;
        int *buf = malloc((size_t)n * sizeof *buf);   /* one block per round */
        if (buf == NULL) { printf("malloc failed\n"); return 1; }
        live++;
        int sum = 0;
        for (int i = 0; i < n; i++) { buf[i] = i + 1; sum += buf[i]; }
        printf("Round %d: %2d ints allocated, sum = %d\n", round, n, sum);
        free(buf);                         /* freed inside the loop, so no leak */
        live--;
    }
    printf("Blocks still allocated: %d\n", live);
    return 0;
}

