/* Swap any two objects of the given size, one byte at a time */
void swapBytes(void *a, void *b, size_t size)
{
    unsigned char *p = a, *q = b, t;
    size_t i;
    for (i = 0; i < size; i++) { t = p[i]; p[i] = q[i]; q[i] = t; }
}

