void bubble(int a[], int n, int (*outOfOrder)(int, int))
{
    int i, j, t;
    for (i = 0; i < n - 1; i++)
        for (j = 0; j < n - 1 - i; j++)
            if (outOfOrder(a[j], a[j + 1])) { t = a[j]; a[j] = a[j + 1]; a[j + 1] = t; }
}

