/* Find the min and max of any array using a comparator */
void minMax(const void *base, int n, size_t size,
            int (*cmp)(const void *, const void *),
            const void **min, const void **max)
{
    const char *p = base;
    int i;
    *min = *max = p;
    for (i = 1; i < n; i++) {
        const void *cur = p + i * size;
        if (cmp(cur, *min) < 0) *min = cur;
        if (cmp(cur, *max) > 0) *max = cur;
    }
}

int cmpInt(const void *a, const void *b) { return (*(const int *)a > *(const int *)b) - (*(const int *)a < *(const int *)b); }
int cmpDouble(const void *a, const void *b) { return (*(const double *)a > *(const double *)b) - (*(const double *)a < *(const double *)b); }
int cmpStr(const void *a, const void *b) { return strcmp(*(const char *const *)a, *(const char *const *)b); }

