/*
 * Generic swap: works for any type.
 * We receive two void pointers (type unknown) and the size in bytes,
 * then exchange the bytes one at a time through unsigned char pointers.
 */
void swap(void *a, void *b, size_t size)
{
    unsigned char *p = a;     /* view the memory as plain bytes */
    unsigned char *q = b;
    unsigned char tmp;
    size_t i;

    for (i = 0; i < size; i++) {
        tmp = p[i];           /* save byte of a */
        p[i] = q[i];          /* copy byte of b into a */
        q[i] = tmp;           /* put saved byte into b */
    }
}

