static void pr_char(const void *p)   { printf("'%c'", *(const char *)p); }

/* Generic print: element size tells us how far to step; pr prints one element. */
static void print_array(const void *base, size_t n, size_t size, void (*pr)(const void *))
{
    if (base == NULL || size == 0 || pr == NULL) {
        printf("[invalid array]\n");
        return;
    }
    if (n == 0) {
        printf("[] (empty)\n");
        return;
    }
    const char *b = base;
    printf("[");
    for (size_t i = 0; i < n; i++) {
        if (i > 0) printf(", ");
        pr(b + i * size);
    }
    printf("]\n");
}

