    printf("single int:  "); print_array(one, 1, sizeof one[0], pr_int);
    printf("doubles (3): "); print_array(d, 3, sizeof d[0], pr_double);
    printf("chars (3):   "); print_array(s, 3, sizeof s[0], pr_char);
    printf("n = 0:       "); print_array(a, 0, sizeof a[0], pr_int);
    printf("NULL array:  "); print_array(NULL, 3, sizeof(int), pr_int);
