#include <stdio.h>

typedef void (*callback)(int idx, int val, void *ctx);

/* Calls cb once for every element of the array. */
static void for_each(const int *a, int n, callback cb, void *ctx)
{
    for (int i = 0; i < n; i++) cb(i, a[i], ctx);
}

static void add_to_sum(int idx, int val, void *ctx)
{
    int *sum = ctx;
    *sum += val;
    printf("  step %d: a[%d] = %2d, running sum = %d\n", idx + 1, idx, val, *sum);
}

struct MaxState { int max; int at; };

static void track_max(int idx, int val, void *ctx)
{
    struct MaxState *m = ctx;
    if (idx == 0 || val > m->max) { m->max = val; m->at = idx; }
    printf("  step %d: value %2d, max so far = %d (index %d)\n", idx + 1, val, m->max, m->at);
}

int main(void)
{
    int data[] = {4, 9, -2, 7, 3};
    int n = (int)(sizeof data / sizeof data[0]);
    int sum = 0;
    struct MaxState ms = {0, 0};

    printf("Callback 1: running sum\n");
    for_each(data, n, add_to_sum, &sum);
    printf("Total = %d\n\n", sum);

    printf("Callback 2: track maximum\n");
    for_each(data, n, track_max, &ms);
    printf("Maximum = %d at index %d\n", ms.max, ms.at);
    return 0;
}

