typedef int (*cmp_fn)(const void *, const void *);

/* Generic linear search: returns index of first match or -1. Works for any type. */
static int find_index(const void *key, const void *base, size_t n, size_t size, cmp_fn cmp)
{
    const char *p = base;
    for (size_t i = 0; i < n; i++)
        if (cmp(key, p + i * size) == 0) return (int)i;
    return -1;
}

static int cmp_int(const void *a, const void *b)
{
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}

static int cmp_double(const void *a, const void *b)
{
    double x = *(const double *)a, y = *(const double *)b;
    return (x > y) - (x < y);
}

int main(void)
{
