    int keys[] = {30, 7, 99};
    double dk[] = {3.75, 4.5};

    for (int i = 0; i < 3; i++) {
        int idx = find_index(&keys[i], nums, 6, sizeof nums[0], cmp_int);
        if (idx >= 0) printf("int %d found at index %d\n", keys[i], idx);
        else printf("int %d not found\n", keys[i]);
    }
    for (int i = 0; i < 2; i++) {
        int idx = find_index(&dk[i], vals, 4, sizeof vals[0], cmp_double);
        if (idx >= 0) printf("double %.2f found at index %d\n", dk[i], idx);
        else printf("double %.2f not found\n", dk[i]);
    }
    return 0;
}

