/* Each comparison returns nonzero when a and b are in the WRONG order. */
static int wrong_asc(int a, int b)  { return a > b; }
static int wrong_desc(int a, int b) { return a < b; }

struct Order {
    const char *label;
    int (*wrong)(int, int);       /* function pointer chosen per order */
};

static void sort_ints(int *a, int n, int (*wrong)(int, int))
{
    for (int i = 0; i < n - 1; i++)
        for (int j = 0; j < n - 1 - i; j++)
            if (wrong(a[j], a[j + 1])) {
                int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;
            }
}

int main(void)
{
    const int original[] = {42, 7, 19, 7, -3, 25};
    struct Order orders[] = {
        {"ascending", wrong_asc},
        {"descending", wrong_desc},
    };

    for (int k = 0; k < 2; k++) {
        int work[6];
        memcpy(work, original, sizeof work);
        sort_ints(work, 6, orders[k].wrong);
        printf("%-10s:", orders[k].label);
        for (int i = 0; i < 6; i++) printf(" %d", work[i]);
        printf("\n");
    }
    return 0;
}

