typedef void (*handler_fn)(const struct Event *, int *total);

static void on_start(const struct Event *e, int *total) { (void)e; *total = 0; printf("  system started, total reset\n"); }
static void on_data(const struct Event *e, int *total)  { *total += e->payload; printf("  data %d received, total = %d\n", e->payload, *total); }
static void on_error(const struct Event *e, int *total) { (void)total; printf("  ERROR code %d\n", e->payload); }
