{
    struct Entry table[EV_COUNT] = {
        {"START", on_start}, {"DATA", on_data}, {"ERROR", on_error}, {"STOP", on_stop}
    };
    struct Event queue[] = {
        {EV_START, 0}, {EV_DATA, 10}, {EV_DATA, 25}, {EV_ERROR, 404},
        {9, 0}, {EV_DATA, 5}, {-1, 0}, {EV_STOP, 0}
    };
