typedef void (*plugin_fn)(const char *);

static void p_upper(const char *s)
{
    for (; *s; s++) putchar(toupper((unsigned char)*s));
    putchar('\n');
}

static void p_rev(const char *s)
{
    for (size_t i = strlen(s); i > 0; i--) putchar(s[i - 1]);
    putchar('\n');
}

static void p_count(const char *s)
{
    int v = 0, c = 0;
    for (; *s; s++) {
        if (strchr("aeiouAEIOU", *s)) v++;
        else c++;
    }
    printf("%d vowels, %d consonants\n", v, c);
}

static void p_palin(const char *s)
{
    size_t i = 0, j = strlen(s);
    int ok = 1;
    while (j > 1 && i < j - 1) {
        if (tolower((unsigned char)s[i]) != tolower((unsigned char)s[j - 1])) { ok = 0; break; }
        i++; j--;
    }
    printf("%s\n", ok ? "palindrome" : "not a palindrome");
}

struct Plugin { const char *name; plugin_fn run; };

static const struct Plugin registry[] = {
    {"upper", p_upper}, {"rev", p_rev}, {"count", p_count}, {"palin", p_palin}
};

static const struct Plugin *find_plugin(const char *name)
{
    for (size_t i = 0; i < sizeof registry / sizeof registry[0]; i++)
        if (strcmp(registry[i].name, name) == 0) return &registry[i];
    return NULL;
}

static int letters_only(const char *s)
{
    if (*s == '\0') return 0;
    for (; *s; s++) if (!isalpha((unsigned char)*s)) return 0;
    return 1;
}

int main(void)
{
    char cmd[16], arg[64];
    while (printf("plugin> "), scanf("%15s %63s", cmd, arg) == 2) {
        const struct Plugin *p = find_plugin(cmd);
        printf("[%s %s] ", cmd, arg);
        if (p == NULL) { printf("error: unknown plugin\n"); continue; }
        if (!letters_only(arg)) { printf("error: argument must be letters only\n"); continue; }
        p->run(arg);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

typedef double (*arith_fn)(double, double);

static double f_add(double a, double b) { return a + b; }
static double f_sub(double a, double b) { return a - b; }
static double f_mul(double a, double b) { return a * b; }
static double f_div(double a, double b) { return a / b; }

static arith_fn lookup(char op)
{
    switch (op) {
    case '+': return f_add;
    case '-': return f_sub;
    case '*': return f_mul;
    case '/': return f_div;
    default:  return NULL;
    }
}

static void show_menu(void)
{
    printf("Operators: + (add)  - (subtract)  * (multiply)  / (divide)\n");
    printf("Enter: number operator number\n");
}

/* Returns 0 on success, -1 for unknown operator, -2 for division by zero. */
static int calculate(double a, char op, double b, double *result)
{
    arith_fn fn = lookup(op);
    if (fn == NULL) return -1;
    if (op == '/' && b == 0.0) return -2;
    *result = fn(a, b);
    return 0;
}

int main(void)
{
    double a, b, r;
    char op;

    show_menu();
    while (scanf("%lf %c %lf", &a, &op, &b) == 3) {
        int st = calculate(a, op, b, &r);
        if (st == 0) printf("%.2f %c %.2f = %.2f\n", a, op, b, r);
        else if (st == -1) printf("%.2f %c %.2f -> unknown operator '%c'\n", a, op, b, op);
        else printf("%.2f %c %.2f -> division by zero\n", a, op, b);
    }
    return 0;
}

#include <stdio.h>

/*
 * transform: applies f to every element in place.
 *   Time  : O(n) calls to f.
 *   Space : O(1) extra - the array is modified in place.
 * reduce: folds all elements into one value with f.
 *   Time  : O(n);  Space: O(1).
 */
static void transform(int *a, int n, int (*f)(int))
{
    for (int i = 0; i < n; i++) a[i] = f(a[i]);
}

static int reduce(const int *a, int n, int init, int (*f)(int, int))
{
    int acc = init;
    for (int i = 0; i < n; i++) acc = f(acc, a[i]);
    return acc;
}

