/* Safe comparator: subtraction could overflow for INT_MIN/INT_MAX. */
static int cmp_int(const void *a, const void *b)
{
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}

static void run_case(const char *title, int *a, size_t n)
{
    printf("%s\n  before:", title);
    for (size_t i = 0; i < n; i++) printf(" %d", a[i]);
    qsort(a, n, sizeof a[0], cmp_int);
    printf("\n  after: ");
    for (size_t i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n");
}

int main(void)
{
    int normal[]  = {34, -5, 12, 0, 99, 12};
    int extremes[] = {INT_MAX, 0, INT_MIN, -1, 1};
    int single[]  = {7};
    int equal[]   = {3, 3, 3, 3};
    int sorted[]  = {1, 2, 3, 4};

    run_case("Normal values", normal, 6);
    run_case("Minimum and maximum int", extremes, 5);
    run_case("Single element", single, 1);
    run_case("All equal", equal, 4);
    run_case("Already sorted", sorted, 4);
    run_case("Empty array", sorted, 0);
    return 0;
}

