struct Emp { char name[12]; int age; double salary; };
enum Field { BY_NAME, BY_AGE, BY_SALARY };

static int cmp_name(const void *a, const void *b)
{
    return strcmp(((const struct Emp *)a)->name, ((const struct Emp *)b)->name);
}
static int cmp_age(const void *a, const void *b)
{
    int x = ((const struct Emp *)a)->age, y = ((const struct Emp *)b)->age;
    return (x > y) - (x < y);
}
static int cmp_salary(const void *a, const void *b)
{
    double x = ((const struct Emp *)a)->salary, y = ((const struct Emp *)b)->salary;
    return (x > y) - (x < y);
}

/* The selected field picks the comparator - no global variable needed. */
static void sort_by(struct Emp *e, size_t n, enum Field f)
{
    int (*const cmps[])(const void *, const void *) = {cmp_name, cmp_age, cmp_salary};
    qsort(e, n, sizeof e[0], cmps[f]);
}

