#include <stdio.h>
#include <stddef.h>

/* Swaps size bytes between a and b. Returns 0 on success, -1 on bad arguments. */
static int generic_swap(void *a, void *b, size_t size)
{
    if (a == NULL || b == NULL || size == 0) return -1;
    if (a == b) return 0;                 /* nothing to do */
    unsigned char *p = a, *q = b;
    for (size_t i = 0; i < size; i++) {
        unsigned char t = p[i];
        p[i] = q[i];
        q[i] = t;
    }
    return 0;
}

struct Point { int x, y; };

int main(void)
{
    int a = 10, b = 20;
    double d1 = 1.5, d2 = -2.75;
    struct Point p = {1, 2}, q = {30, 40};
    char s1[8] = "left", s2[8] = "right";

    printf("int:    "); generic_swap(&a, &b, sizeof a);
    printf("a=%d b=%d\n", a, b);
    printf("double: "); generic_swap(&d1, &d2, sizeof d1);
    printf("d1=%.2f d2=%.2f\n", d1, d2);
    printf("struct: "); generic_swap(&p, &q, sizeof p);
    printf("p=(%d,%d) q=(%d,%d)\n", p.x, p.y, q.x, q.y);
    printf("string: "); generic_swap(s1, s2, sizeof s1);
    printf("s1=%s s2=%s\n", s1, s2);

    printf("Failure cases:\n");
    printf("  NULL pointer -> %d\n", generic_swap(NULL, &b, sizeof b));
    printf("  size 0       -> %d\n", generic_swap(&a, &b, 0));
    printf("  same object  -> %d (a still %d)\n", generic_swap(&a, &a, sizeof a), a);
    return 0;
}

#include <stdio.h>
#include <stddef.h>

/* Prints n elements of the given element size; type tag chooses the format. */
static void print_generic(const void *base, size_t n, size_t size, char type)
{
    const char *p = base;
    printf("[");
    for (size_t i = 0; i < n; i++) {
        const void *e = p + i * size;
        if (i) printf(", ");
        if (type == 'i')      printf("%d", *(const int *)e);
        else if (type == 'd') printf("%.2f", *(const double *)e);
        else                  printf("'%c'", *(const char *)e);
    }
    printf("] (%zu elements x %zu bytes = %zu bytes)\n", n, size, n * size);
}

int main(void)
{
    int ia[10];
    double da[10];
    char ca[10];
    char type;
    int n;

    printf("Enter: type(i/d/c) count then the values, repeat; EOF to stop\n");
    while (scanf(" %c %d", &type, &n) == 2) {
        if (n < 1 || n > 10) { printf("Invalid count %d (1-10)\n", n); break; }
        int ok = 1;
        for (int i = 0; i < n && ok; i++) {
            if (type == 'i')      ok = scanf("%d", &ia[i]) == 1;
            else if (type == 'd') ok = scanf("%lf", &da[i]) == 1;
            else if (type == 'c') ok = scanf(" %c", &ca[i]) == 1;
            else { printf("Unknown type '%c'\n", type); ok = 0; }
        }
        if (!ok) break;
        if (type == 'i')      print_generic(ia, (size_t)n, sizeof ia[0], 'i');
        else if (type == 'd') print_generic(da, (size_t)n, sizeof da[0], 'd');
        else                  print_generic(ca, (size_t)n, sizeof ca[0], 'c');
    }
    return 0;
}

#include <stdio.h>

#define CAP 4

struct Stack { int data[CAP]; int top; };
typedef int (*handler)(struct Stack *, int);

static int h_push(struct Stack *s, int v)
{
    if (s->top == CAP) { printf("push %d: stack full\n", v); return -1; }
    s->data[s->top++] = v;
    printf("pushed %d\n", v);
    return 0;
}
static int h_pop(struct Stack *s, int v)
{
    (void)v;
    if (s->top == 0) { printf("pop: stack empty\n"); return -1; }
    printf("popped %d\n", s->data[--s->top]);
    return 0;
}
static int h_peek(struct Stack *s, int v)
{
    (void)v;
    if (s->top == 0) { printf("peek: stack empty\n"); return -1; }
    printf("top is %d\n", s->data[s->top - 1]);
    return 0;
}
static int h_size(struct Stack *s, int v)
{
    (void)v;
    printf("size = %d\n", s->top);
    return 0;
}

/* Separate function: validates the choice and calls through the table. */
static int dispatch(struct Stack *s, int choice, int arg)
{
    static const handler table[] = {h_push, h_pop, h_peek, h_size};
    int n = (int)(sizeof table / sizeof table[0]);
    if (choice < 1 || choice > n) { printf("invalid option %d\n", choice); return -1; }
    return table[choice - 1](s, arg);
}

int main(void)
{
    struct Stack st = {{0}, 0};
    int choice, arg;

    printf("Options: 1 push v, 2 pop, 3 peek, 4 size, 0 quit (each followed by a number)\n");
    while (scanf("%d %d", &choice, &arg) == 2 && choice != 0)
        dispatch(&st, choice, arg);
    printf("done, %d item(s) left\n", st.top);
    return 0;
}

#include <stdio.h>

typedef void (*callback)(int value, int *acc);

static void for_each(const int *a, int n, callback cb, int *acc)
{
    for (int i = 0; i < n; i++) cb(a[i], acc);
}

static void show_square(int v, int *acc)
{
    printf("  %d squared = %d\n", v, v * v);
    *acc += v * v;
}

static void flush_line(void)
{
    int c;
    while ((c = getchar()) != '\n' && c != EOF) { }
}

/* Reads an integer in [lo, hi]; repeats on error. Returns 0 at end of input. */
static int read_int(const char *prompt, int lo, int hi, int *out)
{
    for (;;) {
        printf("%s", prompt);
        int r = scanf("%d", out);
        if (r == EOF) return 0;
        if (r != 1) { printf("Error: not a number, try again\n"); flush_line(); continue; }
        if (*out < lo || *out > hi) { printf("Error: %d is outside %d..%d\n", *out, lo, hi); continue; }
        return 1;
    }
}

int main(void)
{
    int a[8], n, total = 0;

    if (!read_int("How many values (1-8)? ", 1, 8, &n)) return 1;
    for (int i = 0; i < n; i++) {
        char prompt[32];
        snprintf(prompt, sizeof prompt, "Value %d (-100..100): ", i + 1);
        if (!read_int(prompt, -100, 100, &a[i])) return 1;
    }
    printf("Callback applied to each element:\n");
    for_each(a, n, show_square, &total);
    printf("Sum of squares = %d\n", total);
    return 0;
}

#include <stdio.h>

static int is_prime(int n)
{
    if (n < 2) return 0;
    for (int d = 2; d * d <= n; d++)
        if (n % d == 0) return 0;
    return 1;
}

static int digit_sum(int n)
{
    int s = 0;
    for (; n > 0; n /= 10) s += n % 10;
    return s;
}

int main(void)
{
    int (*fp)(int);                     /* pointer to function returning int */
    int samples[] = {7, 10, 29};

    for (int i = 0; i < 3; i++) {
        printf("Sample %d: n = %d\n", i + 1, samples[i]);
        fp = is_prime;
        printf("  is_prime  -> %d\n", fp(samples[i]));
        fp = digit_sum;
        printf("  digit_sum -> %d\n", fp(samples[i]));
    }
    return 0;
}

