#include <stdio.h>
#include <string.h>
#include <stddef.h>

typedef int (*cmp_fn)(const void *, const void *);

/* Returns a pointer to the first matching element, or NULL. */
static const void *search(const void *key, const void *base, size_t n, size_t size, cmp_fn cmp)
{
    if (key == NULL || base == NULL || size == 0) return NULL;   /* boundary: bad input */
    const char *p = base;
    for (size_t i = 0; i < n; i++)                               /* n == 0 -> loop skipped */
        if (cmp(key, p + i * size) == 0) return p + i * size;
    return NULL;
}

static int cmp_int(const void *a, const void *b)
{
    return *(const int *)a - *(const int *)b;
}
static int cmp_str(const void *a, const void *b)
{
    return strcmp(*(const char *const *)a, *(const char *const *)b);
}

int main(void)
{
    int a[] = {4, 8, 15, 16, 23, 42};
    int k;
    const int *r;

    k = 4;  r = search(&k, a, 6, sizeof a[0], cmp_int);
    printf("first element 4:  %s\n", r ? "found" : "missing");
    if (r) printf("  index = %d\n", (int)(r - a));
    k = 42; r = search(&k, a, 6, sizeof a[0], cmp_int);
    printf("last element 42:  %s\n", r ? "found" : "missing");
    if (r) printf("  index = %d\n", (int)(r - a));
    k = 5;  r = search(&k, a, 6, sizeof a[0], cmp_int);
    printf("absent value 5:   %s\n", r ? "found" : "missing");
    k = 4;  r = search(&k, a, 0, sizeof a[0], cmp_int);
    printf("empty array:      %s\n", r ? "found" : "missing");
    r = search(NULL, a, 6, sizeof a[0], cmp_int);
    printf("NULL key:         %s\n", r ? "found" : "missing");
    k = 8;  r = search(&k, a, 1, sizeof a[0], cmp_int);
    printf("only first checked (n=1) for 8: %s\n", r ? "found" : "missing");

    const char *words[] = {"red", "green", "blue"};
    const char *w = "blue";
    const char *const *s = search(&w, words, 3, sizeof words[0], cmp_str);
    printf("string \"blue\":    %s\n", s ? "found" : "missing");
    if (s) printf("  index = %d\n", (int)(s - words));
    return 0;
}

#include <stdio.h>
#include <string.h>

typedef int (*order_fn)(int, int);     /* returns nonzero if the pair must be swapped */

static int asc(int a, int b)  { return a > b; }
static int desc(int a, int b) { return a < b; }

static void sort(int *a, int n, order_fn out_of_order)
{
    for (int i = 1; i < n; i++) {          /* insertion sort */
        int key = a[i], j = i - 1;
        while (j >= 0 && out_of_order(a[j], key)) { a[j + 1] = a[j]; j--; }
        a[j + 1] = key;
    }
}

static void show(const int *a, int n)
{
    for (int i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");
}

int main(void)
{
    const int original[] = {31, 4, 59, 26, 5, 35};
    int work[6];
    int choice;

    memcpy(work, original, sizeof work);
    printf("Menu: 1) ascending  2) descending  3) reset  0) quit\n");
    for (;;) {
        printf("Option: ");
        if (scanf("%d", &choice) != 1 || choice == 0) break;
        switch (choice) {
        case 1: sort(work, 6, asc);  printf("Ascending:  "); show(work, 6); break;
        case 2: sort(work, 6, desc); printf("Descending: "); show(work, 6); break;
        case 3: memcpy(work, original, sizeof work); printf("Reset:      "); show(work, 6); break;
        default: printf("Unknown option %d\n", choice);
        }
    }
    printf("Goodbye\n");
    return 0;
}

