typedef int (*plugin_fn)(const int *, int);

static int p_sum(const int *a, int n) { int s = 0; for (const int *p = a; p < a + n; p++) s += *p; return s; }
static int p_max(const int *a, int n) { int m = *a; for (const int *p = a + 1; p < a + n; p++) if (*p > m) m = *p; return m; }
static int p_min(const int *a, int n) { int m = *a; for (const int *p = a + 1; p < a + n; p++) if (*p < m) m = *p; return m; }
static int p_evens(const int *a, int n) { int c = 0; for (const int *p = a; p < a + n; p++) if (*p % 2 == 0) c++; return c; }

struct Plugin { const char *name; plugin_fn fn; };

static const struct Plugin *find(const struct Plugin *begin, const struct Plugin *end, const char *name)
{
    for (const struct Plugin *p = begin; p < end; p++)
        if (strcmp(p->name, name) == 0) return p;
    return NULL;
}

int main(void)
{
    static const struct Plugin plugins[] = {
        {"sum", p_sum}, {"max", p_max}, {"min", p_min}, {"evens", p_evens}
    };
    const struct Plugin *end = plugins + sizeof plugins / sizeof plugins[0];
    int data[] = {8, -3, 15, 6, 22, 9};
    const char *requests[] = {"sum", "max", "min", "evens", "median"};

    for (int i = 0; i < 5; i++) {
        const struct Plugin *p = find(plugins, end, requests[i]);
        if (p) printf("%-7s -> %d\n", requests[i], p->fn(data, 6));
        else   printf("%-7s -> plugin not registered\n", requests[i]);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#define BUCKETS 5

typedef struct Node { int key, val; struct Node *next; } Node;
static Node *table[BUCKETS];

static int hash(int k) { return ((k % BUCKETS) + BUCKETS) % BUCKETS; }

static void put(int k, int v)
{
    Node *n = table[hash(k)];
    for (; n; n = n->next)
        if (n->key == k) { n->val = v; return; }   /* update existing key */
    n = malloc(sizeof *n);
    if (!n) exit(1);
    n->key = k; n->val = v;
    n->next = table[hash(k)];                      /* insert at chain head */
    table[hash(k)] = n;
}

static Node *get(int k)
{
    for (Node *n = table[hash(k)]; n; n = n->next)
        if (n->key == k) return n;
    return NULL;
}

int main(void)
{
    int keys[] = {10, 15, 20, 7, 12, 25, 10};
    for (int i = 0; i < 7; i++) put(keys[i], keys[i] * 2);
    for (int b = 0; b < BUCKETS; b++) {
        printf("Bucket %d:", b);
        for (Node *n = table[b]; n; n = n->next) printf(" [%d->%d]", n->key, n->val);
        printf("\n");
    }
    Node *f = get(15);
    printf("Search 15: %s", f ? "found value " : "not found");
    if (f) printf("%d", f->val);
    printf("\nSearch 99: %s\n", get(99) ? "found" : "not found");
    for (int b = 0; b < BUCKETS; b++)
        while (table[b]) { Node *t = table[b]; table[b] = t->next; free(t); }
    return 0;
}

#include <stdio.h>
#define SIZE 7
#define EMPTY -1

static int keys[SIZE];

/* linear probing: try slot h, h+1, h+2 ... (wrap around) */
static int insert(int k)
{
    int h = k % SIZE;
    for (int i = 0; i < SIZE; i++) {
        int idx = (h + i) % SIZE;
        if (keys[idx] == EMPTY) { keys[idx] = k; return idx; }
    }
    return -1;                                   /* table full */
}

static int search(int k)
{
    int h = k % SIZE;
    for (int i = 0; i < SIZE; i++) {
        int idx = (h + i) % SIZE;
        if (keys[idx] == EMPTY) return -1;       /* hit an empty slot: absent */
        if (keys[idx] == k) return idx;
    }
    return -1;
}

int main(void)
{
    int data[] = {50, 700, 76, 85, 92, 73, 101, 5};
    for (int i = 0; i < SIZE; i++) keys[i] = EMPTY;
    for (int i = 0; i < 8; i++) {
        int pos = insert(data[i]);
        if (pos >= 0) printf("Insert %3d -> slot %d\n", data[i], pos);
        else printf("Insert %3d -> table full\n", data[i]);
    }
    printf("Table:");
    for (int i = 0; i < SIZE; i++) printf(" %d", keys[i]);
    printf("\nSearch 92 -> slot %d\n", search(92));
    printf("Search 11 -> slot %d\n", search(11));
    return 0;
}

#include <stdio.h>
#define CAP 3

typedef struct { int key, val; } Entry;
static Entry cache[CAP];   /* index 0 = most recently used */
static int used = 0;

static void touch(int pos)           /* move entry at pos to the front */
{
    Entry e = cache[pos];
    for (int i = pos; i > 0; i--) cache[i] = cache[i - 1];
    cache[0] = e;
}

static int get(int key)
{
    for (int i = 0; i < used; i++)
        if (cache[i].key == key) { touch(i); return cache[0].val; }
    return -1;
}

static void put(int key, int val)
{
    for (int i = 0; i < used; i++)
        if (cache[i].key == key) { cache[i].val = val; touch(i); return; }
    if (used < CAP) used++;                      /* else last entry is evicted */
    else printf("  evict key %d\n", cache[CAP - 1].key);
    for (int i = used - 1; i > 0; i--) cache[i] = cache[i - 1];
    cache[0].key = key; cache[0].val = val;
}

static void show(void)
{
    printf("  cache (MRU->LRU):");
    for (int i = 0; i < used; i++) printf(" %d:%d", cache[i].key, cache[i].val);
    printf("\n");
}

int main(void)
{
    put(1, 100); put(2, 200); put(3, 300); show();
    printf("get(1) = %d\n", get(1)); show();
    printf("put(4,400)\n"); put(4, 400); show();
    printf("get(2) = %d (evicted)\n", get(2));
    return 0;
}

#include <stdio.h>
#define MAX 20

static int heap[MAX], n = 0;

static void swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }

static void push(int x)
{
    int i = n++;
    heap[i] = x;
    while (i > 0 && heap[(i - 1) / 2] > heap[i]) {   /* sift up */
        swap(&heap[(i - 1) / 2], &heap[i]);
        i = (i - 1) / 2;
    }
}

static int pop(void)
{
    int top = heap[0], i = 0;
    heap[0] = heap[--n];
    for (;;) {                                        /* sift down */
        int l = 2 * i + 1, r = l + 1, s = i;
        if (l < n && heap[l] < heap[s]) s = l;
        if (r < n && heap[r] < heap[s]) s = r;
        if (s == i) break;
        swap(&heap[i], &heap[s]);
        i = s;
    }
    return top;
}

int main(void)
{
    int a[] = {42, 17, 8, 23, 4, 15, 99, 1};
    for (int i = 0; i < 8; i++) push(a[i]);
    printf("Heap array :");
    for (int i = 0; i < n; i++) printf(" %d", heap[i]);
    printf("\nPopped in order:");
    while (n > 0) printf(" %d", pop());
    printf("\n");
    return 0;
}

#include <stdio.h>
#define MAX 20

typedef struct { int data[MAX]; int size; } MaxHeap;

static void insert(MaxHeap *h, int x)
{
    int i = h->size++;
    h->data[i] = x;
    while (i > 0 && h->data[(i - 1) / 2] < h->data[i]) {
        int p = (i - 1) / 2, t = h->data[p];
        h->data[p] = h->data[i]; h->data[i] = t;
        i = p;
    }
}

static int extract_max(MaxHeap *h)
{
    int top = h->data[0], i = 0;
    h->data[0] = h->data[--h->size];
    while (1) {
        int l = 2 * i + 1, r = l + 1, big = i;
        if (l < h->size && h->data[l] > h->data[big]) big = l;
        if (r < h->size && h->data[r] > h->data[big]) big = r;
        if (big == i) break;
        int t = h->data[i]; h->data[i] = h->data[big]; h->data[big] = t;
        i = big;
    }
    return top;
}

int main(void)
{
    MaxHeap h = { {0}, 0 };
    int v[] = {12, 55, 7, 31, 64, 20};
    for (int i = 0; i < 6; i++) {
        insert(&h, v[i]);
        printf("After inserting %2d, root (max) = %d\n", v[i], h.data[0]);
    }
    printf("Extract order:");
    while (h.size) printf(" %d", extract_max(&h));
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <string.h>
#define MAX 10

typedef struct { int pri; char name[16]; } Task;   /* smaller pri = more urgent */
static Task pq[MAX];
static int cnt = 0;

static void enqueue(int pri, const char *name)
{
    if (cnt == MAX) { printf("Queue full\n"); return; }
    int i = cnt++;
    pq[i].pri = pri; strcpy(pq[i].name, name);
    while (i > 0 && pq[(i - 1) / 2].pri > pq[i].pri) {
        Task t = pq[i]; pq[i] = pq[(i - 1) / 2]; pq[(i - 1) / 2] = t;
        i = (i - 1) / 2;
    }
}

static Task dequeue(void)
{
    Task top = pq[0];
    pq[0] = pq[--cnt];
    int i = 0;
    for (;;) {
        int l = 2 * i + 1, r = l + 1, s = i;
        if (l < cnt && pq[l].pri < pq[s].pri) s = l;
        if (r < cnt && pq[r].pri < pq[s].pri) s = r;
        if (s == i) break;
        Task t = pq[i]; pq[i] = pq[s]; pq[s] = t;
        i = s;
    }
    return top;
}

int main(void)
{
    enqueue(3, "Print report"); enqueue(1, "Fix server");
    enqueue(4, "Backup"); enqueue(2, "Reply mail");
    printf("Peek: %s (priority %d)\n", pq[0].name, pq[0].pri);
    while (cnt > 0) {
        Task t = dequeue();
        printf("Serve priority %d : %s\n", t.pri, t.name);
    }
    return 0;
}

#include <stdio.h>
