static int find(int x)
{
    while (parent[x] != x) x = parent[x];
    return x;
}

static void unite(int a, int b)
{
    int ra = find(a), rb = find(b);
    if (ra != rb) parent[rb] = ra;     /* attach one root under the other */
}

int main(void)
{
