    unite(0, 1); unite(2, 3); unite(1, 3); unite(5, 6);
    printf("parent[]:");
    for (int i = 0; i < N; i++) printf(" %d", parent[i]);
    printf("\n");
    printf("0 and 2 same set? %s\n", find(0) == find(2) ? "yes" : "no");
    printf("0 and 5 same set? %s\n", find(0) == find(5) ? "yes" : "no");
