#include <stdio.h>
#include <stdlib.h>

typedef struct Trie { struct Trie *kid[26]; int end; } Trie;

static Trie *newnode(void)
{
    Trie *t = calloc(1, sizeof(Trie));
    if (!t) exit(1);
    return t;
}

static void insert(Trie *root, const char *w)
{
    for (; *w; w++) {
        int c = *w - 'a';
        if (!root->kid[c]) root->kid[c] = newnode();
        root = root->kid[c];
    }
    root->end = 1;                         /* mark end of a word */
}

static int lookup(Trie *root, const char *w)
{
    for (; *w; w++) {
        root = root->kid[*w - 'a'];
        if (!root) return 0;
    }
    return root->end;
}

static void destroy(Trie *t)
{
    if (!t) return;
    for (int i = 0; i < 26; i++) destroy(t->kid[i]);
    free(t);
}

int main(void)
{
    Trie *root = newnode();
    const char *words[] = {"cat", "car", "cart", "dog", "do"};
    const char *q[] = {"car", "ca", "dog", "dot", "cart"};
    for (int i = 0; i < 5; i++) insert(root, words[i]);
    for (int i = 0; i < 5; i++)
        printf("lookup(%-5s) = %s\n", q[i], lookup(root, q[i]) ? "found" : "not found");
    destroy(root);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct T { struct T *k[26]; int end; } T;

static void insert(T *r, const char *w)
{
    for (; *w; w++) {
        if (!r->k[*w - 'a']) { r->k[*w - 'a'] = calloc(1, sizeof(T)); if (!r->k[*w - 'a']) exit(1); }
        r = r->k[*w - 'a'];
    }
    r->end = 1;
}

/* print every word below node, building it in buf */
static void collect(T *n, char *buf, int len)
{
    if (n->end) { buf[len] = 0; printf("  %s\n", buf); }
    for (int i = 0; i < 26; i++)
        if (n->k[i]) { buf[len] = (char)('a' + i); collect(n->k[i], buf, len + 1); }
}

static void freeall(T *n)
{
    for (int i = 0; i < 26; i++) if (n->k[i]) freeall(n->k[i]);
    free(n);
}

int main(void)
{
    T *root = calloc(1, sizeof(T));
    const char *w[] = {"apple", "app", "apt", "bat", "ball", "banana"};
    const char *prefixes[] = {"ap", "ba", "z"};
    char buf[32];
    if (!root) return 1;
    for (int i = 0; i < 6; i++) insert(root, w[i]);
    for (int i = 0; i < 3; i++) {
        T *n = root;
        const char *p = prefixes[i];
        for (const char *c = p; *c && n; c++) n = n->k[*c - 'a'];
        printf("Words with prefix \"%s\":\n", p);
        if (!n) { printf("  (none)\n"); continue; }
        strcpy(buf, p);
        collect(n, buf, (int)strlen(p));
    }
    freeall(root);
    return 0;
}

