#include <stdio.h>

typedef struct { int r, c, v; } T;

/* merge two row-major sorted lists; equal positions are added */
static int add(const T *a, int na, const T *b, int nb, T *out)
{
    int i = 0, j = 0, k = 0;
    while (i < na || j < nb) {
        if (j >= nb || (i < na && (a[i].r < b[j].r || (a[i].r == b[j].r && a[i].c < b[j].c)))) out[k++] = a[i++];
        else if (i >= na || b[j].r < a[i].r || (b[j].r == a[i].r && b[j].c < a[i].c)) out[k++] = b[j++];
        else {
            int s = a[i].v + b[j].v;
            if (s != 0) { out[k] = a[i]; out[k].v = s; k++; }   /* drop zero sums */
            i++; j++;
        }
    }
    return k;
}

int main(void)
{
    T A[] = {{0, 1, 4}, {1, 2, 5}, {2, 0, 9}};
    T B[] = {{0, 1, 6}, {1, 0, 1}, {2, 0, -9}, {2, 2, 8}};
    T C[10];
    int n = add(A, 3, B, 4, C);
    printf("Sum has %d non-zero terms:\n", n);
    for (int i = 0; i < n; i++) printf("(%d,%d) = %d\n", C[i].r, C[i].c, C[i].v);
    return 0;
}

#include <stdio.h>
#define CAP 4
typedef struct { unsigned char data[CAP]; int head, tail, count; } CB;
static int put(CB *b, unsigned char x) {
    if (b->count == CAP) return 0;
    b->data[b->tail] = x; b->tail = (b->tail + 1) % CAP; b->count++;
    return 1;
}
static int get(CB *b, unsigned char *x) {
    if (b->count == 0) return 0;
    *x = b->data[b->head]; b->head = (b->head + 1) % CAP; b->count--;
    return 1;
}
int main(void) {
    CB b = {{0}, 0, 0, 0};
    unsigned char x;
    for (unsigned char v = 0x41; v < 0x46; v++)
        printf("put 0x%02X: %s\n", v, put(&b, v) ? "ok" : "full");
    get(&b, &x); printf("got 0x%02X\n", x);
    get(&b, &x); printf("got 0x%02X\n", x);
    put(&b, 0x50); put(&b, 0x51);              /* wraps around the end of the array */
    printf("count=%d head=%d tail=%d\n", b.count, b.head, b.tail);
    while (get(&b, &x)) printf("drain 0x%02X\n", x);
    return 0;
}

