#define BITS 64
static unsigned char bits[BITS / 8];
static unsigned h1(const char *s) { unsigned h = 5381; while (*s) h = h * 33 + (unsigned char)*s++; return h % BITS; }
static unsigned h2(const char *s) { unsigned h = 0; while (*s) h = h * 31 + (unsigned char)*s++; return h % BITS; }
static void setb(unsigned i) { bits[i / 8] |= (unsigned char)(1u << (i % 8)); }
static int testb(unsigned i) { return (bits[i / 8] >> (i % 8)) & 1; }
static void add(const char *s) { setb(h1(s)); setb(h2(s)); }
static int maybe(const char *s) { return testb(h1(s)) && testb(h2(s)); }
