    for (int i = 0; i < 3; i++) add(in[i]);
    int ones = 0;
    for (int i = 0; i < BITS; i++) ones += testb((unsigned)i);
    printf("bits set: %d of %d\n", ones, BITS);
    for (int i = 0; i < 4; i++) printf("%-7s -> %s\n", q[i], maybe(q[i]) ? "possibly present" : "definitely absent");
