#include <stdlib.h>
typedef struct N { int v; struct N *l, *r; } N;
static N *ins(N *t, int v) {
    if (!t) { t = calloc(1, sizeof *t); t->v = v; return t; }
    if (v < t->v) t->l = ins(t->l, v); else t->r = ins(t->r, v);
    return t;
}
typedef struct { N *st[32]; int top; } It;
static void pushLeft(It *it, N *t) { while (t) { it->st[it->top++] = t; t = t->l; } }
static int hasNext(It *it) { return it->top > 0; }
static int next(It *it) { N *t = it->st[--it->top]; pushLeft(it, t->r); return t->v; }
static void freeT(N *t) { if (t) { freeT(t->l); freeT(t->r); free(t); } }
int main(void) {
    int in[] = {8, 3, 10, 1, 6, 14, 4, 7};
    N *root = NULL;
    for (int i = 0; i < 8; i++) root = ins(root, in[i]);
    It it = {{0}, 0};
    pushLeft(&it, root);
    printf("in-order via iterator:");
    while (hasNext(&it)) printf(" %d", next(&it));
    printf("\n");
    freeT(root);
    return 0;
}

