#include <stdio.h>
#define MAXN 32
typedef struct { int node, dist; } Ent;
static Ent h[MAXN]; static int n = 0;
static void push(int node, int dist) {
    int i = n++; h[i].node = node; h[i].dist = dist;
    while (i > 0 && h[(i-1)/2].dist > h[i].dist) { Ent t = h[i]; h[i] = h[(i-1)/2]; h[(i-1)/2] = t; i = (i-1)/2; }
}
static Ent pop(void) {
    Ent top = h[0]; h[0] = h[--n];
    int i = 0;
    for (;;) {
        int l = 2*i+1, r = l+1, m = i;
        if (l < n && h[l].dist < h[m].dist) m = l;
        if (r < n && h[r].dist < h[m].dist) m = r;
        if (m == i) break;
        Ent t = h[i]; h[i] = h[m]; h[m] = t; i = m;
    }
    return top;
}
int main(void) {
    int w[5][5] = {{0,4,1,0,0},{4,0,2,5,0},{1,2,0,8,0},{0,5,8,0,3},{0,0,0,3,0}};
