        if (e.dist > dist[e.node]) continue;     /* stale entry */
        for (int v = 0; v < 5; v++)
            if (w[e.node][v] && e.dist + w[e.node][v] < dist[v]) { dist[v] = e.dist + w[e.node][v]; push(v, dist[v]); }
    }
    for (int i = 0; i < 5; i++) printf("dist(0 -> %d) = %d\n", i, dist[i]);
    return 0;
}

