#include <stdio.h>
#include <stdlib.h>
typedef struct { int *keys; char *used; int cap, count; } HT;
static void init(HT *t, int cap) { t->keys = calloc((size_t)cap, sizeof(int)); t->used = calloc((size_t)cap, 1); t->cap = cap; t->count = 0; }
static void put(HT *t, int k);
static void resize(HT *t) {
    HT nt; init(&nt, t->cap * 2);
    for (int i = 0; i < t->cap; i++) if (t->used[i]) put(&nt, t->keys[i]);   /* rehash every key */
    free(t->keys); free(t->used);
    *t = nt;
}
static void put(HT *t, int k) {
    if (t->count * 2 >= t->cap) { printf("  load %d/%d -> resize to %d\n", t->count, t->cap, t->cap * 2); resize(t); }
    int i = k % t->cap;
    while (t->used[i]) i = (i + 1) % t->cap;
    t->keys[i] = k; t->used[i] = 1; t->count++;
}
int main(void) {
    HT t; init(&t, 4);
    for (int k = 10; k <= 60; k += 10) { printf("put %d\n", k); put(&t, k); }
    printf("capacity %d, count %d\n", t.cap, t.count);
    for (int i = 0; i < t.cap; i++) if (t.used[i]) printf("[%d]=%d ", i, t.keys[i]);
    printf("\n");
    free(t.keys); free(t.used);
    return 0;
}

#include <stdio.h>
#define SIZE 7
enum { EMPTY, FULL, DELETED };
static int key[SIZE], st[SIZE];
static int find(int k) {
    for (int i = 0; i < SIZE; i++) {
        int idx = (k % SIZE + i) % SIZE;
        if (st[idx] == EMPTY) return -1;                 /* tombstones do NOT stop the search */
        if (st[idx] == FULL && key[idx] == k) return idx;
    }
    return -1;
}
static void insert(int k) {
    for (int i = 0; i < SIZE; i++) {
        int idx = (k % SIZE + i) % SIZE;
        if (st[idx] != FULL) { key[idx] = k; st[idx] = FULL; return; }
    }
}
static int del(int k) { int i = find(k); if (i < 0) return 0; st[i] = DELETED; return 1; }
static void show(void) {
    for (int i = 0; i < SIZE; i++)
        { if (st[i] == FULL) printf("[%d]", key[i]); else if (st[i] == DELETED) printf("[T]"); else printf("[ ]"); }
    printf("\n");
}
int main(void) {
    insert(7); insert(14); insert(21); insert(3);        /* 7,14,21 collide at slot 0 */
    show();
    printf("delete 14: %s\n", del(14) ? "ok" : "no");
    show();
    printf("find 21: slot %d (probe passes the tombstone)\n", find(21));
    printf("delete 99: %s\n", del(99) ? "ok" : "not found");
    insert(28); show();                                  /* reuses the tombstone slot */
    return 0;
}

#include <stdio.h>
static void sift(int *a, int n, int i) {      /* max-heap sift-down */
    for (;;) {
        int l = 2*i+1, r = l+1, m = i;
        if (l < n && a[l] > a[m]) m = l;
        if (r < n && a[r] > a[m]) m = r;
        if (m == i) return;
        int t = a[i]; a[i] = a[m]; a[m] = t; i = m;
    }
}
static void heapsort(int *a, int n) {
    for (int i = n/2 - 1; i >= 0; i--) sift(a, n, i);    /* build heap */
    for (int end = n - 1; end > 0; end--) {
        int t = a[0]; a[0] = a[end]; a[end] = t;         /* move max to the back */
        sift(a, end, 0);
    }
}
static void show(const char *s, int *a, int n) { printf("%s", s); for (int i = 0; i < n; i++) printf(" %d", a[i]); printf("\n"); }
int main(void) {
    int a[] = {29, 3, 17, 8, 41, 12, 5, 23};
    show("before:", a, 8);
    heapsort(a, 8);
    show("after: ", a, 8);
    return 0;
}

