#include <stdio.h>
#include <stdlib.h>
typedef struct Adj { int to; struct Adj *next; } Adj;
typedef struct { int n; Adj **list; } Graph;
static Graph *create(int n) {
    Graph *g = malloc(sizeof *g);
    if (!g) return NULL;
    g->list = calloc((size_t)n, sizeof(Adj *));
    if (!g->list) { free(g); return NULL; }
    g->n = n; return g;
}
static int addEdge(Graph *g, int a, int b) {              /* directed edge a -> b */
    if (a < 0 || a >= g->n || b < 0 || b >= g->n) return 0;
    Adj *x = malloc(sizeof *x);
    if (!x) return 0;
    x->to = b; x->next = g->list[a]; g->list[a] = x;
    return 1;
}
static int destroy(Graph *g) {                             /* frees every node, returns how many */
    int freed = 0;
    for (int i = 0; i < g->n; i++)
        while (g->list[i]) { Adj *t = g->list[i]; g->list[i] = t->next; free(t); freed++; }
    free(g->list); free(g);
    return freed;
}
int main(void) {
    Graph *g = create(4);
    if (!g) return 1;
    addEdge(g, 0, 1); addEdge(g, 0, 2); addEdge(g, 1, 3); addEdge(g, 2, 3);
    printf("edge 9->1 accepted? %d\n", addEdge(g, 9, 1));
    for (int i = 0; i < g->n; i++) { printf("%d ->", i); for (Adj *p = g->list[i]; p; p = p->next) printf(" %d", p->to); printf("\n"); }
    printf("freed %d edge nodes plus the graph\n", destroy(g));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define SIZE 7

struct Node { int key; struct Node *next; };

/* Hash function: map any int (even negative) to 0..SIZE-1 */
static int hash(int key) { return ((key % SIZE) + SIZE) % SIZE; }

static void insert(struct Node *table[], int key)
{
    struct Node *n = malloc(sizeof *n);
    if (n == NULL) return;
    n->key = key;
    n->next = table[hash(key)];      /* add at the head of the chain */
    table[hash(key)] = n;
}

static int search(struct Node *table[], int key)
{
    struct Node *p;
    for (p = table[hash(key)]; p != NULL; p = p->next)
        if (p->key == key) return 1;
    return 0;
}

int main(void)
{
    struct Node *table[SIZE] = {NULL};
    int n, i, key, q;

    printf("How many keys? ");
    if (scanf("%d", &n) != 1) return 0;
    printf("Enter %d keys: ", n);
    for (i = 0; i < n; i++) {
        if (scanf("%d", &key) != 1) break;
        insert(table, key);
    }
    printf("\nHash table (separate chaining):\n");
    for (i = 0; i < SIZE; i++) {
        struct Node *p;
        printf("Bucket %d:", i);
        for (p = table[i]; p != NULL; p = p->next) printf(" -> %d", p->key);
        printf(" -> NULL\n");
    }
    while (scanf("%d", &q) == 1)
        printf("Search %d: %s\n", q, search(table, q) ? "found" : "not found");

    for (i = 0; i < SIZE; i++) {      /* free all chains */
        struct Node *p = table[i];
        while (p != NULL) { struct Node *t = p->next; free(p); p = t; }
    }
    return 0;
}

#include <stdio.h>

#define SIZE 11
#define EMPTY (-1)

/* Insert using linear probing. Returns slot index, or -1 if table is full. */
static int insert_key(int table[], int key)
{
    int i, idx = key % SIZE;
    for (i = 0; i < SIZE; i++) {
        int slot = (idx + i) % SIZE;
        if (table[slot] == EMPTY) { table[slot] = key; return slot; }
    }
    return -1;
}

/* Search using the same probe sequence. Returns slot index or -1. */
static int find_key(const int table[], int key)
{
    int i, idx = key % SIZE;
    for (i = 0; i < SIZE; i++) {
        int slot = (idx + i) % SIZE;
        if (table[slot] == EMPTY) return -1;
        if (table[slot] == key) return slot;
    }
    return -1;
}

static void print_table(const int table[])
{
    int i;
    for (i = 0; i < SIZE; i++) {
        if (table[i] == EMPTY) printf("[%2d] -\n", i);
        else printf("[%2d] %d\n", i, table[i]);
    }
}

int main(void)
{
    int table[SIZE], i;
    int keys[] = {10, 21, 32, 5, 16, 27, 38};
    int look[] = {27, 38, 99};

    for (i = 0; i < SIZE; i++) table[i] = EMPTY;
    for (i = 0; i < 7; i++) {
        int s = insert_key(table, keys[i]);
        printf("Insert %2d -> slot %d\n", keys[i], s);
    }
    printf("\nFinal table:\n");
    print_table(table);
    printf("\n");
    for (i = 0; i < 3; i++) {
        int s = find_key(table, look[i]);
        if (s >= 0) printf("Key %d found at slot %d\n", look[i], s);
        else printf("Key %d not found\n", look[i]);
    }
    return 0;
}

#include <stdio.h>

#define CAP 3

struct Entry { int key, value, used, stamp; };

static struct Entry cache[CAP];
static int clock_tick = 0;

static int find(int key)
{
    int i;
    for (i = 0; i < CAP; i++)
        if (cache[i].used && cache[i].key == key) return i;
    return -1;
}

static void put(int key, int value)
{
    int i = find(key), victim = 0;
    if (i < 0) {
        for (i = 0; i < CAP; i++)             /* free slot? */
            if (!cache[i].used) break;
        if (i == CAP) {                       /* full: evict least recently used */
            for (i = 1; i < CAP; i++)
                if (cache[i].stamp < cache[victim].stamp) victim = i;
            i = victim;
            printf("  evicting key %d\n", cache[i].key);
        }
    }
    cache[i].key = key; cache[i].value = value;
    cache[i].used = 1;  cache[i].stamp = ++clock_tick;
}

int main(void)
{
    char op;
    int a, b, i;

    printf("Commands: P key value | G key\n");
    while (scanf(" %c", &op) == 1) {
        if (op == 'P') {
            if (scanf("%d %d", &a, &b) != 2) { printf("Error: P needs two integers\n"); break; }
            printf("PUT %d=%d\n", a, b);
            put(a, b);
        } else if (op == 'G') {
            if (scanf("%d", &a) != 1) { printf("Error: G needs an integer key\n"); break; }
            i = find(a);
            if (i < 0) printf("GET %d -> miss\n", a);
            else { cache[i].stamp = ++clock_tick; printf("GET %d -> %d\n", a, cache[i].value); }
        } else {
            printf("Error: unknown command '%c'\n", op);
            break;
        }
    }
    printf("Cache now:");
    for (i = 0; i < CAP; i++)
        if (cache[i].used) printf(" (%d,%d)", cache[i].key, cache[i].value);
    printf("\n");
    return 0;
}

#include <stdio.h>

#define MAX 20

static void swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }

static void push(int h[], int *n, int v)
{
    int i = (*n)++;
    h[i] = v;
    while (i > 0 && h[(i - 1) / 2] > h[i]) {     /* sift up */
        swap(&h[(i - 1) / 2], &h[i]);
        i = (i - 1) / 2;
    }
}

static int pop(int h[], int *n)
{
    int top = h[0], i = 0;
    h[0] = h[--(*n)];
    for (;;) {                                   /* sift down */
        int l = 2 * i + 1, r = l + 1, m = i;
        if (l < *n && h[l] < h[m]) m = l;
        if (r < *n && h[r] < h[m]) m = r;
        if (m == i) break;
        swap(&h[i], &h[m]);
        i = m;
    }
    return top;
}

static void run(const int data[], int count, int test)
{
    int heap[MAX], n = 0, i;
    printf("Test %d input :", test);
    for (i = 0; i < count; i++) { printf(" %d", data[i]); push(heap, &n, data[i]); }
    printf("\nHeap array   :");
    for (i = 0; i < n; i++) printf(" %d", heap[i]);
    printf("\nSorted output:");
    while (n > 0) printf(" %d", pop(heap, &n));
    printf("\n\n");
}

int main(void)
{
    int a[] = {5, 3, 8, 1, 9, 2};
    int b[] = {4, 4, 4, 4};
    int c[] = {10, 9, 8, 7, 6, 5, 4};
    run(a, 6, 1);
    run(b, 4, 2);
    run(c, 7, 3);
    return 0;
}

#include <stdio.h>

#define MAX 30

struct MaxHeap { int a[MAX]; int n; };

/* Insert: put the value at the end, then move it UP while it is bigger than its parent. */
static int insert(struct MaxHeap *h, int v)
{
    int i;
    if (h->n == MAX) return 0;
    i = h->n++;
    h->a[i] = v;
    while (i > 0 && h->a[(i - 1) / 2] < h->a[i]) {
        int p = (i - 1) / 2, t = h->a[p];
        h->a[p] = h->a[i]; h->a[i] = t;
        i = p;
    }
    return 1;
}

/* Remove max: move the last item to the root, then push it DOWN to restore order. */
static int remove_max(struct MaxHeap *h)
{
    int top = h->a[0], i = 0;
    h->a[0] = h->a[--h->n];
    for (;;) {
        int l = 2 * i + 1, r = l + 1, m = i, t;
        if (l < h->n && h->a[l] > h->a[m]) m = l;
        if (r < h->n && h->a[r] > h->a[m]) m = r;
        if (m == i) break;
        t = h->a[i]; h->a[i] = h->a[m]; h->a[m] = t;
        i = m;
    }
    return top;
}

int main(void)
{
    struct MaxHeap h = {{0}, 0};
    int n, v, i;
    printf("Number of values: ");
    if (scanf("%d", &n) != 1) return 0;
    for (i = 0; i < n; i++)
        if (scanf("%d", &v) == 1) insert(&h, v);
    printf("Heap array: ");
    for (i = 0; i < h.n; i++) printf("%d ", h.a[i]);
    printf("\nMaximum   : %d\n", h.a[0]);
    printf("Descending: ");
    while (h.n > 0) printf("%d ", remove_max(&h));
    printf("\n");
    return 0;
}

