#define CAP 4

struct Task { int pri; char name[12]; };
struct PQ { struct Task t[CAP]; int n; };

static int pq_push(struct PQ *q, int pri, const char *name)
{
    int i, k;
    if (q->n == CAP) return 0;                 /* boundary: full */
    i = q->n++;
    q->t[i].pri = pri;
    for (k = 0; k < 11 && name[k]; k++) q->t[i].name[k] = name[k];
    q->t[i].name[k] = '\0';
    while (i > 0 && q->t[(i - 1) / 2].pri > q->t[i].pri) {   /* lower number = more urgent */
        struct Task tmp = q->t[i];
        q->t[i] = q->t[(i - 1) / 2];
        q->t[(i - 1) / 2] = tmp;
        i = (i - 1) / 2;
    }
    return 1;
}

static int pq_pop(struct PQ *q, struct Task *out)
{
    int i = 0;
    if (q->n == 0) return 0;                   /* boundary: empty */
    *out = q->t[0];
    q->t[0] = q->t[--q->n];
    for (;;) {
        int l = 2 * i + 1, r = l + 1, m = i;
        if (l < q->n && q->t[l].pri < q->t[m].pri) m = l;
        if (r < q->n && q->t[r].pri < q->t[m].pri) m = r;
        if (m == i) break;
        { struct Task tmp = q->t[i]; q->t[i] = q->t[m]; q->t[m] = tmp; }
        i = m;
    }
    return 1;
}

int main(void)
{
