    struct Task t;

    printf("Pop from empty queue: %s\n", pq_pop(&q, &t) ? "ok" : "queue empty");
    printf("Push C(3): %d\n", pq_push(&q, 3, "write"));
    printf("Single item pop: ");
    if (pq_pop(&q, &t)) printf("%s (priority %d)\n", t.name, t.pri);
    pq_push(&q, 5, "backup");
    pq_push(&q, 1, "alarm");
    pq_push(&q, 4, "log");
    pq_push(&q, 2, "sensor");
    printf("Push into full queue: %s\n", pq_push(&q, 0, "extra") ? "ok" : "rejected (full)");
    printf("Order of service:\n");
    while (pq_pop(&q, &t)) printf("  priority %d : %s\n", t.pri, t.name);
    return 0;
}

#include <stdio.h>

#define N 10

static int parent[N];

static int find(int x)
{
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];   /* path halving */
        x = parent[x];
    }
    return x;
}

static void unite(int a, int b)
{
    int ra = find(a), rb = find(b);
    if (ra != rb) parent[rb] = ra;
}

