#include <stdio.h>
#include <stdlib.h>

struct Trie { struct Trie *child[26]; int end; };

static struct Trie *new_node(void) { return calloc(1, sizeof(struct Trie)); }

static void insert(struct Trie *root, const char *w)
{
    int i;
    for (i = 0; w[i]; i++) {
        int c = w[i] - 'a';
        if (root->child[c] == NULL) root->child[c] = new_node();
        root = root->child[c];
    }
    root->end = 1;
}

static int lookup(const struct Trie *root, const char *w)
{
    int i;
    for (i = 0; w[i] && root; i++) root = root->child[w[i] - 'a'];
    return root != NULL && root->end;
}

static void destroy(struct Trie *t)
{
    int i;
    if (t == NULL) return;
    for (i = 0; i < 26; i++) destroy(t->child[i]);
    free(t);
}

int main(void)
{
    const char *words[] = {"cat", "car", "cart", "dog", "do"};
    const char *tests[] = {"car", "ca", "dog", "dot", "cart", "do"};
    struct Trie *root = new_node();
    int i;

    for (i = 0; i < 5; i++) { insert(root, words[i]); printf("Inserted: %s\n", words[i]); }
    printf("\n");
    for (i = 0; i < 6; i++)
        printf("Lookup %-5s : %s\n", tests[i], lookup(root, tests[i]) ? "FOUND" : "not found");
    destroy(root);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct Trie { struct Trie *next[26]; int end; };

static struct Trie *add_word(struct Trie *root, const char *w)
{
    struct Trie *p = root;
    for (; *w; w++) {
        if (p->next[*w - 'a'] == NULL) p->next[*w - 'a'] = calloc(1, sizeof(struct Trie));
        p = p->next[*w - 'a'];
    }
    p->end = 1;
    return root;
}

/* Depth-first walk that prints every word below this node. */
static int collect(const struct Trie *p, char *buf, int len)
{
    int i, count = 0;
    if (p->end) { buf[len] = '\0'; printf("  %s\n", buf); count++; }
    for (i = 0; i < 26; i++)
        if (p->next[i]) { buf[len] = (char)('a' + i); count += collect(p->next[i], buf, len + 1); }
    return count;
}

static void prefix_search(const struct Trie *root, const char *prefix)
{
    char buf[32];
    const struct Trie *p = root;
    int len = 0, n;
    for (; *prefix; prefix++, len++) {
        p = p->next[*prefix - 'a'];
        if (p == NULL) { printf("No words\n"); return; }
        buf[len] = *prefix;
    }
    n = collect(p, buf, len);
    printf("  (%d word%s)\n", n, n == 1 ? "" : "s");
}

static void destroy(struct Trie *t)
{
    int i;
    if (!t) return;
    for (i = 0; i < 26; i++) destroy(t->next[i]);
    free(t);
}

int main(void)
{
    const char *words[] = {"apple", "app", "apply", "ape", "bat", "bath", "batman"};
    const char *prefixes[] = {"app", "ba", "ap", "z"};
    struct Trie *root = calloc(1, sizeof *root);
    int i;
    for (i = 0; i < 7; i++) add_word(root, words[i]);
    for (i = 0; i < 4; i++) {
        printf("Prefix \"%s\":\n", prefixes[i]);
        prefix_search(root, prefixes[i]);
    }
    destroy(root);
    return 0;
}

