    int dense[R][C] = {
        {0, 0, 3, 0, 0},
        {22, 0, 0, 0, 17},
        {0, 0, 0, 0, 0},
        {0, 5, 0, 0, 1}
    };
    int row[MAXNZ], col[MAXNZ], val[MAXNZ];
    int nz = 0, i, j, k;

    /* Store only the non-zero entries as (row, col, value) triples. */
    for (i = 0; i < R; i++)
        for (j = 0; j < C; j++)
            if (dense[i][j] != 0) { row[nz] = i; col[nz] = j; val[nz] = dense[i][j]; nz++; }

    printf("Sparse matrix %dx%d, %d non-zero of %d\n", R, C, nz, R * C);
    printf("Row Col Value\n");
    for (k = 0; k < nz; k++) printf("%3d %3d %5d\n", row[k], col[k], val[k]);

    /* Look up an element by scanning the list. */
    {
        int qr = 1, qc = 4, found = 0;
        for (k = 0; k < nz; k++)
            if (row[k] == qr && col[k] == qc) { found = val[k]; break; }
        printf("Element (%d,%d) = %d\n", qr, qc, found);
        qr = 2; qc = 2; found = 0;
        for (k = 0; k < nz; k++)
            if (row[k] == qr && col[k] == qc) { found = val[k]; break; }
        printf("Element (%d,%d) = %d\n", qr, qc, found);
    }

    printf("Rebuilt dense matrix:\n");
    for (i = 0; i < R; i++) {
        for (j = 0; j < C; j++) {
            int v = 0;
            for (k = 0; k < nz; k++) if (row[k] == i && col[k] == j) v = val[k];
            printf("%3d ", v);
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

#define MAX 20

struct Term { int r, c, v; };
struct Sparse { struct Term t[MAX]; int n; };

/* Merge two lists sorted by (row, col); equal positions are summed. */
static struct Sparse add_sparse(const struct Sparse *a, const struct Sparse *b)
{
    struct Sparse s = {{{0, 0, 0}}, 0};
    int i = 0, j = 0;
    while (i < a->n || j < b->n) {
        if (j == b->n || (i < a->n && (a->t[i].r < b->t[j].r ||
            (a->t[i].r == b->t[j].r && a->t[i].c < b->t[j].c)))) s.t[s.n++] = a->t[i++];
        else if (i == a->n || b->t[j].r < a->t[i].r ||
            (b->t[j].r == a->t[i].r && b->t[j].c < a->t[i].c)) s.t[s.n++] = b->t[j++];
        else {
            int sum = a->t[i].v + b->t[j].v;
            if (sum != 0) { s.t[s.n] = a->t[i]; s.t[s.n].v = sum; s.n++; }
            i++; j++;
        }
    }
    return s;
}

static void show(const char *name, const struct Sparse *s)
{
    int k;
    printf("%s:", name);
    for (k = 0; k < s->n; k++) printf(" (%d,%d)=%d", s->t[k].r, s->t[k].c, s->t[k].v);
    printf("\n");
}

int main(void)
{
    struct Sparse a = {{{0, 1, 5}, {1, 0, 2}, {2, 2, 7}}, 3};
    struct Sparse b = {{{0, 1, -5}, {1, 1, 4}, {2, 2, 3}, {3, 0, 9}}, 4};
    struct Sparse c = add_sparse(&a, &b);
    show("A  ", &a);
    show("B  ", &b);
    show("A+B", &c);
    printf("Non-zero count of sum: %d\n", c.n);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

#define CAP 16

struct Ring { uint8_t data[CAP]; unsigned head, tail, count; };

static int put(struct Ring *r, uint8_t b)
{
    if (r->count == CAP) return 0;
    r->data[r->head] = b;
    r->head = (r->head + 1) % CAP;
    r->count++;
    return 1;
}

static int get(struct Ring *r, uint8_t *b)
{
    if (r->count == 0) return 0;
    *b = r->data[r->tail];
    r->tail = (r->tail + 1) % CAP;
    r->count--;
    return 1;
}

int main(void)
{
    struct Ring r = {{0}, 0, 0, 0};
    /* Each record: one length byte followed by that many payload bytes. */
    uint8_t rec1[] = {3, 0x10, 0x20, 0x30};
    uint8_t rec2[] = {5, 0xA1, 0xA2, 0xA3, 0xA4, 0xA5};
    uint8_t rec3[] = {2, 0xFF, 0x00};
    uint8_t *recs[] = {rec1, rec2, rec3};
    unsigned i, k;
    uint8_t b, len;

    for (i = 0; i < 3; i++) {
        for (k = 0; k <= recs[i][0]; k++) put(&r, recs[i][k]);
        printf("Wrote record %u, buffer holds %u bytes\n", i + 1, r.count);
    }
    i = 0;
    while (get(&r, &len)) {
        printf("Record %u (len %u):", ++i, (unsigned)len);
        for (k = 0; k < len && get(&r, &b); k++) printf(" %02X", (unsigned)b);
        printf("\n");
    }
    printf("Buffer empty, count = %u\n", r.count);
    return 0;
}

#include <stdio.h>

#define CAP 4

struct RingQueue { int items[CAP]; int front, size; };

static int enqueue(struct RingQueue *q, int v)
{
    if (q->size == CAP) return 0;
    q->items[(q->front + q->size) % CAP] = v;
    q->size++;
    return 1;
}

static int dequeue(struct RingQueue *q, int *v)
{
    if (q->size == 0) return 0;
    *v = q->items[q->front];
    q->front = (q->front + 1) % CAP;
    q->size--;
    return 1;
}

static void show(const struct RingQueue *q)
{
    int i;
    printf("| front=%d size=%d items:", q->front, q->size);
    for (i = 0; i < q->size; i++) printf(" %d", q->items[(q->front + i) % CAP]);
    printf("\n");
}

int main(void)
{
    struct RingQueue q = {{0}, 0, 0};
    int i, v;
    printf("%-14s %-8s\n", "Operation", "Result");
    for (i = 1; i <= 5; i++) {
        printf("%-14s %-8s", "enqueue", enqueue(&q, i * 10) ? "OK" : "FULL");
        show(&q);
    }
    for (i = 0; i < 2; i++) {
        int ok = dequeue(&q, &v);
        printf("dequeue %-6d %-8s", v, ok ? "OK" : "EMPTY");
        show(&q);
    }
    for (i = 6; i <= 7; i++) {
        printf("%-14s %-8s", "enqueue (wrap)", enqueue(&q, i * 10) ? "OK" : "FULL");
        show(&q);
    }
    return 0;
}

#include <stdio.h>
#include <ctype.h>
#include <string.h>
#include <stdint.h>

#define BITS 128

static uint8_t bits[BITS / 8];

static unsigned h1(const char *s) { unsigned h = 5381; while (*s) h = h * 33 + (unsigned char)*s++; return h % BITS; }
static unsigned h2(const char *s) { unsigned h = 0; while (*s) h = h * 31 + (unsigned char)*s++; return (h ^ (h >> 7)) % BITS; }

static void set_bit(unsigned i) { bits[i / 8] |= (uint8_t)(1u << (i % 8)); }
static int get_bit(unsigned i) { return (bits[i / 8] >> (i % 8)) & 1; }

/* Valid input: 1..15 lowercase letters only. */
static int valid(const char *w)
{
    size_t i, n = strlen(w);
    if (n == 0 || n > 15) return 0;
    for (i = 0; i < n; i++) if (!islower((unsigned char)w[i])) return 0;
    return 1;
}

int main(void)
{
    char cmd, w[64];
    int i, ones = 0;

    while (scanf(" %c %63s", &cmd, w) == 2) {
        if ((cmd != 'A' && cmd != 'Q') || !valid(w)) {
            printf("Invalid input: '%c %s' (use A/Q and lowercase word up to 15 letters)\n", cmd, w);
            continue;
        }
        if (cmd == 'A') {
            set_bit(h1(w)); set_bit(h2(w));
            printf("Added %-8s bits %3u and %3u\n", w, h1(w), h2(w));
        } else if (get_bit(h1(w)) && get_bit(h2(w)))
            printf("Query %-8s: possibly present\n", w);
        else
            printf("Query %-8s: definitely absent\n", w);
    }
    for (i = 0; i < BITS; i++) ones += get_bit((unsigned)i);
    printf("Bits set: %d of %d\n", ones, BITS);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct Node { int val; struct Node *left, *right; };

#define STACK_MAX 32

struct Iter { struct Node *stack[STACK_MAX]; int top; };

static struct Node *insert(struct Node *root, int v)
{
    if (root == NULL) {
        struct Node *n = malloc(sizeof *n);
        if (n == NULL) return NULL;
        n->val = v; n->left = n->right = NULL;
        return n;
    }
    if (v < root->val) root->left = insert(root->left, v);
    else root->right = insert(root->right, v);
    return root;
}

/* Push a node and all of its left descendants. */
static void push_left(struct Iter *it, struct Node *n)
{
    while (n != NULL) { it->stack[it->top++] = n; n = n->left; }
}

static void iter_init(struct Iter *it, struct Node *root)
{
    it->top = 0;
    push_left(it, root);
}

static int has_next(const struct Iter *it) { return it->top > 0; }

static int next(struct Iter *it)
{
    struct Node *n = it->stack[--it->top];
    push_left(it, n->right);
    return n->val;
}

static void destroy(struct Node *n)
{
    if (n == NULL) return;
    destroy(n->left); destroy(n->right); free(n);
}

int main(void)
{
    int vals[] = {50, 30, 70, 20, 40, 60, 80, 35};
    struct Node *root = NULL;
    struct Iter it;
    unsigned i;

    for (i = 0; i < sizeof vals / sizeof vals[0]; i++) root = insert(root, vals[i]);
    iter_init(&it, root);
    printf("In-order via iterator:");
    while (has_next(&it)) printf(" %d", next(&it));
    printf("\n");
    destroy(root);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

/* Space: O(V + E) - one list head per vertex plus one node per edge end.
   Time : add edge O(1); checking an edge O(degree); BFS O(V + E). */

struct Adj { int to; struct Adj *next; };
struct Graph { int n; struct Adj **head; };

static struct Graph *make_graph(int n)
{
    struct Graph *g = malloc(sizeof *g);
    g->n = n;
    g->head = calloc((size_t)n, sizeof *g->head);
    return g;
}

static void add_edge(struct Graph *g, int a, int b)
{
    struct Adj *x = malloc(sizeof *x), *y = malloc(sizeof *y);
    x->to = b; x->next = g->head[a]; g->head[a] = x;
    y->to = a; y->next = g->head[b]; g->head[b] = y;
}

static void bfs(const struct Graph *g, int start)
{
    int *queue = malloc((size_t)g->n * sizeof *queue);
    int *seen = calloc((size_t)g->n, sizeof *seen);
    int qh = 0, qt = 0;
    queue[qt++] = start; seen[start] = 1;
    printf("BFS from %d:", start);
    while (qh < qt) {
        int v = queue[qh++];
        const struct Adj *p;
        printf(" %d", v);
        for (p = g->head[v]; p; p = p->next)
            if (!seen[p->to]) { seen[p->to] = 1; queue[qt++] = p->to; }
    }
    printf("\n");
    free(queue); free(seen);
}

int main(void)
{
    struct Graph *g = make_graph(6);
    int e[][2] = {{0, 1}, {0, 2}, {1, 3}, {2, 4}, {3, 5}, {4, 5}};
    int i;
    for (i = 0; i < 6; i++) add_edge(g, e[i][0], e[i][1]);
    for (i = 0; i < g->n; i++) {
        const struct Adj *p;
        printf("Vertex %d:", i);
        for (p = g->head[i]; p; p = p->next) printf(" %d", p->to);
        printf("\n");
    }
    bfs(g, 0);
    for (i = 0; i < g->n; i++) {
        struct Adj *p = g->head[i];
        while (p) { struct Adj *t = p->next; free(p); p = t; }
    }
    free(g->head);
    free(g);
    return 0;
}

#include <stdio.h>

#define MAXV 5
#define MAXE 10

struct Edge { int u, v, w; };
struct Graph { int nv, ne; struct Edge e[MAXE]; };

static int add_edge(struct Graph *g, int u, int v, int w)
{
    if (g->ne == MAXE || u < 0 || v < 0 || u >= g->nv || v >= g->nv) return 0;
    g->e[g->ne].u = u; g->e[g->ne].v = v; g->e[g->ne].w = w;
    g->ne++;
    return 1;
}

static void report(const char *title, const struct Graph *g)
{
    int i, total = 0;
    printf("== %s ==\n", title);
    printf("Vertices: %d, Edges: %d\n", g->nv, g->ne);
    for (i = 0; i < g->ne; i++) {
        printf("  %d - %d (w=%d)\n", g->e[i].u, g->e[i].v, g->e[i].w);
        total += g->e[i].w;
    }
    printf("Total weight: %d\n\n", total);
}

int main(void)
{
    struct Graph g1 = {3, 0, {{0, 0, 0}}};          /* normal */
    struct Graph g2 = {1, 0, {{0, 0, 0}}};          /* minimum: one vertex, no edges */
    struct Graph g3 = {MAXV, 0, {{0, 0, 0}}};       /* maximum: complete graph K5 */
    int i, j, rejected;

    add_edge(&g1, 0, 1, 4); add_edge(&g1, 1, 2, 6); add_edge(&g1, 0, 2, 9);
    report("Normal case", &g1);
    report("Minimum case", &g2);

    for (i = 0; i < MAXV; i++)
        for (j = i + 1; j < MAXV; j++) add_edge(&g3, i, j, i + j + 1);
    rejected = !add_edge(&g3, 0, 1, 1);
    report("Maximum case", &g3);
    printf("Extra edge beyond maximum: %s\n", rejected ? "rejected" : "accepted");
    printf("Edge to vertex 9 in g1: %s\n", add_edge(&g1, 0, 9, 1) ? "accepted" : "rejected");
    return 0;
}

#include <stdio.h>

#define N 6
#define INF 1000000
#define HCAP 64

struct Item { int dist, node; };
struct Heap { struct Item a[HCAP]; int n; };

static void heap_push(struct Heap *h, int dist, int node)
{
    int i = h->n++;
    h->a[i].dist = dist; h->a[i].node = node;
    while (i > 0 && h->a[(i - 1) / 2].dist > h->a[i].dist) {
        struct Item t = h->a[i];
        h->a[i] = h->a[(i - 1) / 2];
        h->a[(i - 1) / 2] = t;
        i = (i - 1) / 2;
    }
}

static struct Item heap_pop(struct Heap *h)
{
    struct Item top = h->a[0];
    int i = 0;
    h->a[0] = h->a[--h->n];
    for (;;) {
        int l = 2 * i + 1, r = l + 1, m = i;
        if (l < h->n && h->a[l].dist < h->a[m].dist) m = l;
        if (r < h->n && h->a[r].dist < h->a[m].dist) m = r;
        if (m == i) break;
        { struct Item t = h->a[i]; h->a[i] = h->a[m]; h->a[m] = t; }
        i = m;
    }
    return top;
}

static void dijkstra(int g[N][N], int src, int dist[N])
{
    struct Heap h = {{{0, 0}}, 0};
    int i;
    for (i = 0; i < N; i++) dist[i] = INF;
    dist[src] = 0;
    heap_push(&h, 0, src);
    while (h.n > 0) {
        struct Item cur = heap_pop(&h);
        if (cur.dist > dist[cur.node]) continue;      /* stale entry */
        for (i = 0; i < N; i++)
            if (g[cur.node][i] > 0 && cur.dist + g[cur.node][i] < dist[i]) {
                dist[i] = cur.dist + g[cur.node][i];
                heap_push(&h, dist[i], i);
            }
    }
}

int main(void)
{
    int g[N][N] = {
        {0, 7, 9, 0, 0, 14},
        {7, 0, 10, 15, 0, 0},
        {9, 10, 0, 11, 0, 2},
        {0, 15, 11, 0, 6, 0},
        {0, 0, 0, 6, 0, 9},
        {14, 0, 2, 0, 9, 0}
    };
    int dist[N], i;
    dijkstra(g, 0, dist);
    printf("Shortest distances from node 0:\n");
    for (i = 0; i < N; i++) printf("  to %d : %d\n", i, dist[i]);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define SIZE 11
#define LEN 40

struct Slot { int used; char word[LEN]; char meaning[LEN]; };

static unsigned hash(const char *s)
{
    unsigned h = 7;
    while (*s) h = h * 31 + (unsigned char)*s++;
    return h % SIZE;
}

/* Returns 1 ok, 0 duplicate, -1 full, -2 text too long. */
static int add(struct Slot t[], const char *w, const char *m)
{
    unsigned i, idx = hash(w);
    if (strlen(w) >= LEN || strlen(m) >= LEN) return -2;
    for (i = 0; i < SIZE; i++) {
        struct Slot *s = &t[(idx + i) % SIZE];
        if (!s->used) { s->used = 1; strcpy(s->word, w); strcpy(s->meaning, m); return 1; }
        if (strcmp(s->word, w) == 0) return 0;
    }
    return -1;
}

static const char *lookup(const struct Slot t[], const char *w)
{
    unsigned i, idx = hash(w);
    for (i = 0; i < SIZE; i++) {
        const struct Slot *s = &t[(idx + i) % SIZE];
        if (!s->used) return NULL;
        if (strcmp(s->word, w) == 0) return s->meaning;
    }
    return NULL;
}

int main(void)
{
    struct Slot dict[SIZE];
    const char *res;
    int r;

    memset(dict, 0, sizeof dict);
    printf("add array -> %d\n", add(dict, "array", "ordered list of items"));
    printf("add pointer -> %d\n", add(dict, "pointer", "variable holding an address"));
    printf("add struct -> %d\n", add(dict, "struct", "group of related fields"));
    r = add(dict, "array", "again");
    printf("add array (duplicate) -> %d %s\n", r, r == 0 ? "[duplicate rejected]" : "");
    r = add(dict, "long", "0123456789012345678901234567890123456789012");
    printf("add too-long meaning -> %d %s\n", r, r == -2 ? "[too long]" : "");

    res = lookup(dict, "pointer");
    printf("pointer : %s\n", res ? res : "(not found)");
    res = lookup(dict, "union");
    printf("union   : %s\n", res ? res : "(not found)");
    return 0;
}

#include <stdio.h>

#define MAXN 100

/* Cost: with union by rank + path compression each find/union is
   O(alpha(n)) amortised (almost constant). Space is O(n): two int arrays. */

static int parent[MAXN], rnk[MAXN];

static int find(int x)
{
    if (parent[x] != x) parent[x] = find(parent[x]);   /* path compression */
    return parent[x];
}

static int unite(int a, int b)
{
    int ra = find(a), rb = find(b);
    if (ra == rb) return 0;
    if (rnk[ra] < rnk[rb]) { int t = ra; ra = rb; rb = t; }
    parent[rb] = ra;
    if (rnk[ra] == rnk[rb]) rnk[ra]++;
    return 1;
}

int main(void)
{
    int n, m, i, a, b, sets;
    printf("Enter n and m: ");
    if (scanf("%d %d", &n, &m) != 2 || n < 1 || n > MAXN) { printf("Bad input\n"); return 0; }
    for (i = 0; i < n; i++) { parent[i] = i; rnk[i] = 0; }
    sets = n;
    for (i = 0; i < m; i++) {
        if (scanf("%d %d", &a, &b) != 2 || a < 0 || a >= n || b < 0 || b >= n) { printf("Bad pair\n"); return 0; }
        if (unite(a, b)) sets--;
        printf("union(%d,%d) -> sets left: %d\n", a, b, sets);
    }
    printf("Representatives:");
    for (i = 0; i < n; i++) printf(" %d", find(i));
    printf("\nTotal disjoint sets: %d\n", sets);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXNODES 200

/* Nodes live in a fixed pool; children are stored as pool indices (0 = none). */
static int child[MAXNODES][26];
static int is_end[MAXNODES];
static int node_count = 1;           /* node 0 is the root */

static int insert(const char *w)
{
    int cur = 0, i;
    for (i = 0; w[i]; i++) {
        int c = w[i] - 'a';
        if (c < 0 || c >= 26) return 0;
        if (child[cur][c] == 0) {
            if (node_count == MAXNODES) return 0;
            child[cur][c] = node_count++;
        }
        cur = child[cur][c];
    }
    is_end[cur] = 1;
    return 1;
}

static int lookup(const char *w)
{
    int cur = 0, i;
    for (i = 0; w[i]; i++) {
        int c = w[i] - 'a';
        if (c < 0 || c >= 26 || child[cur][c] == 0) return 0;
        cur = child[cur][c];
    }
    return is_end[cur];
}

int main(void)
{
    int n, m, i;
    char w[50];

    printf("How many words to insert? ");
    if (scanf("%d", &n) != 1) return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%49s", w) != 1) break;
        printf("insert %-6s: %s\n", w, insert(w) ? "ok" : "rejected");
    }
    printf("How many lookups? ");
    if (scanf("%d", &m) != 1) return 0;
    for (i = 0; i < m; i++) {
        if (scanf("%49s", w) != 1) break;
        printf("lookup %-6s: %s\n", w, lookup(w) ? "found" : "missing");
    }
    printf("Trie uses %d nodes\n", node_count);
    return 0;
}

#include <stdio.h>

#define MAXNZ 50

int main(void)
{
    int rows, cols, k, i, j;
    int r[MAXNZ], c[MAXNZ], v[MAXNZ];
    int rowsum[20] = {0};

    /* Input: rows cols nz, then nz lines of "row col value". */
    printf("Enter rows, cols, non-zero count: ");
    if (scanf("%d %d %d", &rows, &cols, &k) != 3 || rows > 20 || k > MAXNZ) {
        printf("Invalid input\n");
