    }
    for (i = 0; i < k; i++) {
        if (scanf("%d %d %d", &r[i], &c[i], &v[i]) != 3) { printf("Invalid triple\n"); return 0; }
        rowsum[r[i]] += v[i];                 /* work directly on the compact form */
    }
    printf("Coordinate list (row col value):\n");
    for (i = 0; i < k; i++) printf("  %d %d %d\n", r[i], c[i], v[i]);

    printf("Expanded matrix:\n");
    for (i = 0; i < rows; i++) {
        for (j = 0; j < cols; j++) {
            int x = 0, t;
            for (t = 0; t < k; t++) if (r[t] == i && c[t] == j) x = v[t];
            printf("%4d", x);
        }
        printf("   | row sum = %d\n", rowsum[i]);
    }
    printf("Memory: %d triples instead of %d cells\n", k, rows * cols);
    return 0;
}

#include <stdio.h>
