#define CAP 8

/* Overwriting circular buffer: when full, the oldest byte is dropped. */
struct Circ { uint8_t buf[CAP]; unsigned head, count; };

static void push(struct Circ *c, uint8_t b)
{
    c->buf[c->head] = b;
    c->head = (c->head + 1) % CAP;
    if (c->count < CAP) c->count++;
}

int main(void)
{
    struct Circ c = {{0}, 0, 0};
    unsigned i;

    for (i = 1; i <= 12; i++) {
        push(&c, (uint8_t)(i * 3));
        printf("pushed %2u -> count %u, head %u\n", i * 3, c.count, c.head);
    }
    printf("Contents oldest to newest:");
    for (i = 0; i < c.count; i++)
        printf(" %u", (unsigned)c.buf[(c.head + CAP - c.count + i) % CAP]);
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <stdint.h>

#define NBITS 256

static uint32_t filter[NBITS / 32];

static unsigned hash(const char *s, unsigned seed)
{
    unsigned h = seed;
    while (*s) h = (h ^ (unsigned char)*s++) * 16777619u;
    return h % NBITS;
}

static void add_word(const char *s)
{
    unsigned k;
    for (k = 0; k < 3; k++) {
        unsigned b = hash(s, 2166136261u + k * 101u);
        filter[b / 32] |= (uint32_t)1 << (b % 32);
    }
}

static int maybe_has(const char *s)
{
    unsigned k;
    for (k = 0; k < 3; k++) {
        unsigned b = hash(s, 2166136261u + k * 101u);
        if (!(filter[b / 32] & ((uint32_t)1 << (b % 32)))) return 0;
    }
    return 1;
}

int main(void)
{
    int n, i;
    char w[40];

    if (scanf("%d", &n) != 1) return 0;
    printf("Adding %d records:\n", n);
    for (i = 0; i < n; i++) {
        if (scanf("%39s", &w[0]) != 1) break;
        add_word(w);
        printf("  + %s\n", w);
    }
    if (scanf("%d", &n) != 1) return 0;
    printf("Checking %d records:\n", n);
    for (i = 0; i < n; i++) {
        if (scanf("%39s", &w[0]) != 1) break;
        printf("  ? %-8s -> %s\n", w, maybe_has(w) ? "maybe in set" : "definitely not in set");
    }
    return 0;
}

