#include <stdio.h>
#include <stdint.h>

#define CAP 4

/* Bounded circular buffer: a push on a full buffer is rejected. */
struct Buf { uint8_t data[CAP]; int head, tail, count; };

static int push(struct Buf *b, uint8_t v) {
    if (b->count == CAP) return 0;       /* bounded: refuse */
    b->data[b->tail] = v;
    b->tail = (b->tail + 1) % CAP;
    b->count++;
    return 1;
}
static int pop(struct Buf *b, uint8_t *v) {
    if (b->count == 0) return 0;
    *v = b->data[b->head];
    b->head = (b->head + 1) % CAP;
    b->count--;
    return 1;
}

int main(void) {
    struct Buf b = {{0}, 0, 0, 0};
    uint8_t incoming[] = {0x10, 0x20, 0x30, 0x40, 0x50, 0x60};
    for (unsigned i = 0; i < sizeof incoming; i++) {
        if (push(&b, incoming[i])) printf("stored 0x%02X (count=%d)\n", (unsigned)incoming[i], b.count);
        else printf("buffer full, dropped 0x%02X\n", (unsigned)incoming[i]);
    }
    uint8_t v;
    while (pop(&b, &v)) printf("read 0x%02X\n", (unsigned)v);
    push(&b, 0x70);                       /* wraps around correctly */
    if (pop(&b, &v)) printf("after wrap read 0x%02X\n", (unsigned)v);
    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <stddef.h>

/* 8-bit additive checksum: two's complement of the byte sum, so that
   sum(data) + checksum == 0 (mod 256). */
static uint8_t checksum(const uint8_t *d, size_t n) {
    uint8_t sum = 0;
    for (size_t i = 0; i < n; i++) sum = (uint8_t)(sum + d[i]);
    return (uint8_t)(~sum + 1);
}

int main(void) {
    uint8_t data[] = {0x01, 0x02, 0x03, 0x04, 0xFF};
    uint8_t cs = checksum(data, sizeof data);
    unsigned total = cs;
    for (size_t i = 0; i < sizeof data; i++) total += data[i];
    printf("checksum = 0x%02X\n", (unsigned)cs);      /* sum=0x109 -> 0x09 -> 0xF7 */
    printf("sum of data + checksum mod 256 = %u\n", total & 0xFFu);
    data[2] ^= 0x01;                                    /* corrupt a byte */
    printf("after corruption checksum = 0x%02X\n", (unsigned)checksum(data, sizeof data));
    return 0;
}

