}

#include <stdio.h>
#include <stdint.h>

/* 16-bit message: [15:13] type (3 bits) | [12:8] id (5 bits) | [7:0] value */
static uint16_t pack(unsigned type, unsigned id, unsigned value) {
    return (uint16_t)(((type & 0x7u) << 13) | ((id & 0x1Fu) << 8) | (value & 0xFFu));
}
static void unpack(uint16_t m, unsigned *type, unsigned *id, unsigned *value) {
    *type  = (m >> 13) & 0x7u;
    *id    = (m >> 8) & 0x1Fu;
    *value = m & 0xFFu;
}

int main(void) {
    uint16_t m = pack(5, 19, 0xA7);
    unsigned t, id, v;
    printf("packed  = 0x%04X\n", (unsigned)m);     /* 101 10011 10100111 = 0xB3A7 */
    unpack(m, &t, &id, &v);
    printf("type=%u id=%u value=0x%02X\n", t, id, v);
    return 0;
}

