#define MAGIC 0xA5
#define MAX_PAYLOAD 8

/* Frame: [magic][length][payload...] */
static const char *validate(const uint8_t *f, size_t total) {
    if (total < 2) return "too short for header";
    if (f[0] != MAGIC) return "bad magic";
    if (f[1] > MAX_PAYLOAD) return "length exceeds maximum";
    if ((size_t)f[1] != total - 2) return "length does not match payload";
    return "OK";
}

