    uint8_t d[] = {0xA5, 9, 0, 0, 0, 0, 0, 0, 0, 0, 0};
    uint8_t e[] = {0xA5};
    printf("a: %s\n", validate(a, sizeof a));
    printf("b: %s\n", validate(b, sizeof b));
    printf("c: %s\n", validate(c, sizeof c));
    printf("d: %s\n", validate(d, sizeof d));
    printf("e: %s\n", validate(e, sizeof e));
    return 0;
}

