#define N 5

static int q[N];
static int head = 0, tail = 0, count = 0;

static int enqueue(int v) {
    if (count == N) return 0;
    q[tail] = v; tail = (tail + 1) % N; count++;
    return 1;
}
static int dequeue(int *v) {
    if (count == 0) return 0;
    *v = q[head]; head = (head + 1) % N; count--;
    return 1;
}

