#include <stdio.h>
#include <stdint.h>
#include <stddef.h>

struct Sample { uint8_t id; uint16_t value; uint32_t stamp; };

/* Write fields one by one in big-endian order; avoids struct padding issues.
   Returns number of bytes written. */
static size_t serialize(const struct Sample *s, uint8_t *buf) {
    size_t n = 0;
    buf[n++] = s->id;
    buf[n++] = (uint8_t)(s->value >> 8);
    buf[n++] = (uint8_t)(s->value & 0xFF);
    buf[n++] = (uint8_t)(s->stamp >> 24);
    buf[n++] = (uint8_t)(s->stamp >> 16);
    buf[n++] = (uint8_t)(s->stamp >> 8);
    buf[n++] = (uint8_t)(s->stamp);
    return n;
}

int main(void) {
    struct Sample s = { 0x2A, 0x1234, 0xDEADBEEFu };
    uint8_t buf[16];
    size_t n = serialize(&s, buf);
    printf("sizeof(struct)=%zu, serialized=%zu bytes:", sizeof s, n);
    for (size_t i = 0; i < n; i++) printf(" %02X", (unsigned)buf[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <stdint.h>

struct Sample { uint8_t id; uint16_t value; uint32_t stamp; };

/* Read big-endian fields from the buffer. */
static void deserialize(const uint8_t *b, struct Sample *s) {
    s->id = b[0];
    s->value = (uint16_t)((b[1] << 8) | b[2]);
    s->stamp = ((uint32_t)b[3] << 24) | ((uint32_t)b[4] << 16) |
               ((uint32_t)b[5] << 8) | (uint32_t)b[6];
}

int main(void) {
    uint8_t buf[] = {0x07, 0x01, 0xF4, 0x00, 0x00, 0x03, 0xE8};
    struct Sample s;
    deserialize(buf, &s);
    printf("id    = %u\n", (unsigned)s.id);
    printf("value = %u\n", (unsigned)s.value);      /* 0x01F4 = 500 */
    printf("stamp = %lu\n", (unsigned long)s.stamp); /* 0x3E8 = 1000 */
    return 0;
}

#include <stdio.h>
#include <stdint.h>

/* Simulated millisecond tick counter (a real system would read a timer). */
static uint32_t now_ms = 0;
static void advance(uint32_t ms) { now_ms += ms; }

/* Unsigned subtraction keeps the elapsed time correct even on wraparound. */
static int timed_out(uint32_t start, uint32_t timeout) {
    return (uint32_t)(now_ms - start) >= timeout;
}

int main(void) {
    uint32_t start = now_ms;
    int response_after = 70;          /* device answers after 70 ms */
    int waited = 0;
    while (!timed_out(start, 50)) {   /* timeout 50 ms: do other work, don't spin forever */
        advance(10);
        waited += 10;
        printf("t=%u ms, waiting...\n", (unsigned)(now_ms - start));
        if (waited >= response_after) break;
    }
    if (timed_out(start, 50)) printf("Timeout after %u ms\n", (unsigned)(now_ms - start));
    else printf("Got response\n");

    now_ms = 0xFFFFFFF0u;             /* counter about to wrap */
    start = now_ms;
    advance(0x20);
    printf("wrapped: elapsed=%u ms, timed out(30)=%d\n", (unsigned)(now_ms - start), timed_out(start, 30));
    return 0;
}

