/* Parse "1,2,3" into out[]. Returns count, or -1 on any error. */
static int parse_csv(const char *s, int *out, int max) {
    int n = 0;
    while (1) {
        char *end;
        errno = 0;
        long v = strtol(s, &end, 10);
        if (end == s || errno == ERANGE || v > INT_MAX || v < INT_MIN) return -1;
        if (n >= max) return -1;
        out[n++] = (int)v;
        if (*end == '\0') return n;
        if (*end != ',') return -1;
        s = end + 1;
    }
}

int main(void) {
    const char *tests[] = {"10,20,-30,40", "5", "1,,2", "1,x,3", "7,8,", "99999999999"};
    for (int i = 0; i < 6; i++) {
        int v[8];
        int n = parse_csv(tests[i], v, 8);
        printf("\"%s\": ", tests[i]);
        if (n < 0) printf("invalid\n");
        else {
            int sum = 0;
            for (int k = 0; k < n; k++) sum += v[k];
            printf("%d values, sum=%d\n", n, sum);
        }
    }
    return 0;
}

