struct ByteBuf { uint8_t data[8]; size_t capacity; size_t length; };

static void bb_init(struct ByteBuf *b) { b->capacity = sizeof b->data; b->length = 0; }

static int bb_append(struct ByteBuf *b, const uint8_t *src, size_t n) {
    if (n > b->capacity - b->length) return 0;   /* would overflow */
    for (size_t i = 0; i < n; i++) b->data[b->length + i] = src[i];
    b->length += n;
    return 1;
}

static void bb_print(const struct ByteBuf *b) {
    printf("length=%zu/%zu:", b->length, b->capacity);
    for (size_t i = 0; i < b->length; i++) printf(" %02X", (unsigned)b->data[i]);
    printf("\n");
}

int main(void) {
    struct ByteBuf b;
    uint8_t a[] = {1, 2, 3}, c[] = {4, 5, 6, 7, 8, 9};
    bb_init(&b);
    printf("append 3: %s\n", bb_append(&b, a, sizeof a) ? "ok" : "rejected");
    bb_print(&b);
    printf("append 6: %s\n", bb_append(&b, c, sizeof c) ? "ok" : "rejected");
    printf("append 5: %s\n", bb_append(&b, c, 5) ? "ok" : "rejected");
    bb_print(&b);
    return 0;
}

