/* Frame: 0x7E | len | payload[len] | checksum (sum of len+payload, mod 256) */
static uint8_t sum8(const uint8_t *d, size_t n) {
    uint8_t s = 0;
    for (size_t i = 0; i < n; i++) s = (uint8_t)(s + d[i]);
    return s;
}

static const char *check(const uint8_t *f, size_t n) {
    if (n < 3) return "too short";
    if (f[0] != 0x7E) return "bad start byte";
    if ((size_t)f[1] + 3 != n) return "length mismatch";
    if (sum8(f + 1, (size_t)f[1] + 1) != f[n - 1]) return "checksum error";
    return "valid";
}

int main(void) {
    uint8_t ok[]  = {0x7E, 2, 0x10, 0x20, 0x32};   /* 2+0x10+0x20 = 0x32 */
    uint8_t bad[] = {0x7E, 2, 0x10, 0x21, 0x32};
    uint8_t len[] = {0x7E, 5, 0x10, 0x20, 0x32};
    uint8_t st[]  = {0x00, 2, 0x10, 0x20, 0x32};
    printf("ok : %s\n", check(ok, sizeof ok));
    printf("bad: %s\n", check(bad, sizeof bad));
    printf("len: %s\n", check(len, sizeof len));
    printf("st : %s\n", check(st, sizeof st));
    return 0;
}

