/* Tiny language: sequence of  I (increment), D (decrement), P (print), digits N followed by 'S' (set).
   Example: "5SIIP D P" */
enum St { START, NUMBER };

int main(void) {
    const char *prog = "5SIIPDP";
    int acc = 0, num = 0;
    enum St st = START;
    for (const char *p = prog; *p; p++) {
        char c = *p;
        switch (st) {
        case START:
            if (isdigit((unsigned char)c)) { num = c - '0'; st = NUMBER; }
            else if (c == 'I') acc++;
            else if (c == 'D') acc--;
            else if (c == 'P') printf("PRINT %d\n", acc);
            else printf("error: unexpected '%c'\n", c);
            break;
        case NUMBER:
            if (isdigit((unsigned char)c)) num = num * 10 + (c - '0');
            else if (c == 'S') { acc = num; st = START; printf("SET %d\n", acc); }
            else { printf("error: expected S after number\n"); st = START; }
            break;
        }
    }
    printf("final acc = %d\n", acc);
    return 0;
}

