/* Packet layout (5 bytes, little-endian 16-bit fields):
   [type u8][seq u16][value u16] */
static size_t put_u8(uint8_t *b, size_t o, uint8_t v) { b[o] = v; return o + 1; }
static size_t put_u16(uint8_t *b, size_t o, uint16_t v) {
    b[o] = (uint8_t)(v & 0xFF);
    b[o + 1] = (uint8_t)(v >> 8);
    return o + 2;
}

