#define CAP 3

/* Keeping a separate 'count' lets us tell full from empty even though
   head == tail in both cases. */
static int buf[CAP], head = 0, tail = 0, count = 0;

static int is_empty(void) { return count == 0; }
static int is_full(void)  { return count == CAP; }

static void state(void) {
    printf("  head=%d tail=%d count=%d empty=%d full=%d\n", head, tail, count, is_empty(), is_full());
}

int main(void) {
    printf("start:\n"); state();
    for (int i = 1; i <= 3; i++) { buf[tail] = i; tail = (tail + 1) % CAP; count++; }
    printf("after 3 pushes (head==tail but full):\n"); state();
    while (!is_empty()) { printf("pop %d\n", buf[head]); head = (head + 1) % CAP; count--; }
    printf("after popping all (head==tail but empty):\n"); state();
    return 0;
}

