#define CAP 4

struct Ring { uint8_t d[CAP]; int head, tail, count; };

static int put(struct Ring *r, uint8_t v) {
    if (r->count == CAP) return 0;
    r->d[r->tail] = v; r->tail = (r->tail + 1) % CAP; r->count++;
    return 1;
}

int main(void) {
    struct Ring r = {{0}, 0, 0, 0};
    int v;
    printf("Enter incoming byte values (0-255), any non-number stops: ");
    for (;;) {
        int rc = scanf("%d", &v);
        if (rc == EOF) break;
        if (rc == 0) { printf("\nError: non-numeric input, stopping.\n"); break; }
        if (v < 0 || v > 255) { printf("\nError: %d is not a valid byte, skipped.", v); continue; }
        if (!put(&r, (uint8_t)v)) printf("\nError: buffer full (capacity %d), %d rejected.", CAP, v);
    }
    printf("\nBuffered %d byte(s):", r.count);
    for (int i = 0; i < r.count; i++) printf(" %u", (unsigned)r.d[(r.head + i) % CAP]);
    printf("\n");
