/* Simple 8-bit checksum: sum of bytes modulo 256. */
static unsigned char checksum(const unsigned char *d, size_t n) {
    unsigned s = 0;
    for (size_t i = 0; i < n; i++) s += d[i];
    return (unsigned char)(s & 0xFFu);
}

int main(void) {
    /* three sample inputs */
    unsigned char t1[] = {1, 2, 3, 4};             /* 10 -> 0x0A */
    unsigned char t2[] = {0xFF, 0x01};             /* 256 -> 0x00 */
    unsigned char t3[] = {0x80, 0x80, 0x80, 0x05}; /* 389 -> 0x85 */
    printf("test 1: checksum = 0x%02X\n", (unsigned)checksum(t1, sizeof t1));
    printf("test 2: checksum = 0x%02X\n", (unsigned)checksum(t2, sizeof t2));
    printf("test 3: checksum = 0x%02X\n", (unsigned)checksum(t3, sizeof t3));
    printf("empty : checksum = 0x%02X\n", (unsigned)checksum(t1, 0));
    return 0;
}

