    unsigned char x = 0;               /* running XOR, starts at 0 (identity for XOR) */
    for (const char *p = s; *p != '\0'; p++) {
        x ^= (unsigned char)*p;        /* fold each character into the checksum */
        printf("after '%c' (0x%02X): 0x%02X\n", *p, (unsigned)(unsigned char)*p, (unsigned)x);
    }
    printf("XOR checksum of \"%s\" = 0x%02X\n", s, (unsigned)x);
    /* Property: XOR-ing the checksum in again gives 0, which is how receivers verify. */
    printf("verify (data ^ checksum) = 0x%02X\n", (unsigned)(x ^ x));
    return 0;
}

