/* 12-bit value + 4-bit channel in one 16-bit word: [15:12] channel | [11:0] value */
static uint16_t pack(unsigned ch, unsigned val) {
    return (uint16_t)(((ch & 0xFu) << 12) | (val & 0xFFFu));   /* masks guard overflow */
}

int main(void) {
    unsigned cases[][2] = {{0, 0}, {15, 4095}, {1, 4096}, {16, 1}, {7, 2048}};
    for (int i = 0; i < 5; i++) {
        uint16_t w = pack(cases[i][0], cases[i][1]);
        printf("pack(ch=%2u, val=%4u) = 0x%04X -> ch=%u val=%u%s\n", cases[i][0], cases[i][1],
               (unsigned)w, (unsigned)(w >> 12), (unsigned)(w & 0xFFFu),
               (cases[i][0] > 15 || cases[i][1] > 4095) ? "  (input exceeded field, truncated)" : "");
    }
    return 0;
}

