        case 2: h.version = 2; h.length = 5;  actual = 5;  break;
        case 3: h.version = 1; h.length = 40; actual = 40; break;
        case 4: h.version = 1; h.length = 8;  actual = 6;  break;
        default: printf("\nunknown option\n"); continue;
        }
        printf("\nversion=%u length=%u actual=%zu -> %s\n", (unsigned)h.version, (unsigned)h.length,
               actual, check(h, actual));
