#include <stdio.h>

struct Debounce { int stable; int counter; int need; };

/* Takes a pointer to the state and one raw sample; returns 1 if output changed. */
static int update(struct Debounce *d, int sample) {
    if (sample == d->stable) { d->counter = 0; return 0; }
    if (++d->counter >= d->need) { d->stable = sample; d->counter = 0; return 1; }
    return 0;
}

int main(void) {
    int samples[] = {0, 1, 0, 0, 1, 1, 1, 1, 0, 1, 0, 0, 0};
    int *p = samples;
    int *end = samples + sizeof samples / sizeof samples[0];
    struct Debounce d = {0, 0, 3};
    while (p < end) {
        int changed = update(&d, *p);
        printf("sample %d -> output %d%s\n", *p, d.stable, changed ? "  (edge)" : "");
        p++;
    }
    return 0;
}

