/* A simulated device register block. volatile members model hardware that
   can change behind the program's back. */
struct Device {
    volatile unsigned status;   /* set by "hardware" */
    volatile unsigned data;
    int reads;                  /* ordinary bookkeeping */
};

static void hardware_tick(struct Device *d, unsigned n) {
    d->data = n * 100;
    d->status = 1;              /* data ready */
}

int main(void) {
    struct Device dev = {0, 0, 0};
    for (unsigned i = 1; i <= 3; i++) {
        hardware_tick(&dev, i);
        if (dev.status) {       /* each access re-reads memory because of volatile */
            printf("data ready: %u\n", dev.data);
            dev.reads++;
            dev.status = 0;
        }
    }
    printf("reads performed: %d\n", dev.reads);
    return 0;
}

