#include <stddef.h>

struct Msg { uint8_t kind; int16_t temp; uint16_t volts_mv; };

static size_t put8(uint8_t *b, size_t o, uint8_t v) { b[o] = v; return o + 1; }
static size_t put16(uint8_t *b, size_t o, uint16_t v) {
    o = put8(b, o, (uint8_t)(v >> 8));
    return put8(b, o, (uint8_t)v);
}
static size_t serialize(const struct Msg *m, uint8_t *b) {
    size_t o = 0;
    o = put8(b, o, m->kind);
    o = put16(b, o, (uint16_t)m->temp);      /* two's complement kept as-is */
    o = put16(b, o, m->volts_mv);
    return o;
}
static void print_bytes(const uint8_t *b, size_t n) {
    for (size_t i = 0; i < n; i++) printf("%02X ", (unsigned)b[i]);
    printf("\n");
}

int main(void) {
    struct Msg a = {1, 250, 3300}, c = {2, -40, 5000};
    uint8_t buf[8];
    size_t n = serialize(&a, buf);
    printf("a (%zu bytes): ", n); print_bytes(buf, n);
    n = serialize(&c, buf);
    printf("c (%zu bytes): ", n); print_bytes(buf, n);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

struct Msg { uint8_t kind; int16_t temp; uint16_t volts_mv; };

/* Cost: O(1) time (fixed 5 byte reads) and O(1) extra space - results go
   straight into the output struct, no copies of the buffer are made. */
static void deserialize(const uint8_t *b, struct Msg *m) {
    m->kind = b[0];
    m->temp = (int16_t)(uint16_t)((b[1] << 8) | b[2]);
    m->volts_mv = (uint16_t)((b[3] << 8) | b[4]);
}

int main(void) {
    uint8_t wire[] = {0x02, 0xFF, 0xD8, 0x13, 0x88};
    struct Msg m;
    deserialize(wire, &m);
    printf("kind     = %u\n", (unsigned)m.kind);
    printf("temp     = %d (raw 0xFFD8)\n", (int)m.temp);     /* -40 */
    printf("volts_mv = %u\n", (unsigned)m.volts_mv);          /* 5000 */
    return 0;
}

#include <stdio.h>
