/* Elapsed-time check: cost is O(1), no busy-waiting loop inside. */
static int expired(uint32_t start, uint32_t now, uint32_t timeout) {
    return (uint32_t)(now - start) >= timeout;
}

static void test(const char *label, uint32_t start, uint32_t now, uint32_t timeout) {
    printf("%-8s start=%10u now=%10u timeout=%10u -> %s\n", label, (unsigned)start,
           (unsigned)now, (unsigned)timeout, expired(start, now, timeout) ? "EXPIRED" : "waiting");
}

int main(void) {
    test("normal", 1000, 1400, 500);          /* 400 < 500 */
    test("normal2", 1000, 1500, 500);         /* exactly equal */
    test("minimum", 0, 0, 0);                 /* zero timeout expires at once */
    test("minimum2", 0, 0, 1);
    test("maximum", 0, 0xFFFFFFFEu, 0xFFFFFFFFu);
    test("wrap", 0xFFFFFF00u, 0x00000100u, 0x200); /* elapsed = 0x200 across wrap */
    return 0;
}

