#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>
#include <stddef.h>

enum Status { OK, ERR_EMPTY, ERR_SYNTAX, ERR_RANGE, ERR_FULL };

static enum Status parse(const char *s, int *out, size_t cap, size_t *count) {
    *count = 0;
    if (s == NULL || *s == '\0') return ERR_EMPTY;
    for (;;) {
        char *end;
        errno = 0;
        long v = strtol(s, &end, 10);
        if (end == s) return ERR_SYNTAX;
        if (errno == ERANGE || v > INT_MAX || v < INT_MIN) return ERR_RANGE;
        if (*count >= cap) return ERR_FULL;
        out[(*count)++] = (int)v;
        if (*end == '\0') return OK;
        if (*end != ',') return ERR_SYNTAX;
        s = end + 1;
    }
}

int main(void) {
    static const char *msg[] = {"ok", "empty input", "syntax error", "value out of range", "too many values"};
    const char *tests[] = {"1,2,3", "", "4,,5", "9999999999,1", "1,2,3,4,5,6", "12abc", NULL};
    for (int i = 0; i < 7; i++) {
        int v[5]; size_t n;
        enum Status st = parse(tests[i], v, 5, &n);
        printf("%-14s -> %s", tests[i] ? tests[i] : "(null)", msg[st]);
        if (st == OK) { printf(":"); for (size_t k = 0; k < n; k++) printf(" %d", v[k]); }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <stddef.h>

/* Header: [sync 0xC3][type][len_hi][len_lo] followed by payload.
   Time cost: O(1) - only four header bytes and one comparison are examined.
   Space cost: O(1) - nothing is copied. */
static int validate(const uint8_t *p, size_t total, size_t max_payload) {
    if (total < 4) return -1;
    if (p[0] != 0xC3) return -2;
    size_t len = ((size_t)p[2] << 8) | p[3];
    if (len > max_payload) return -3;
    if (len != total - 4) return -4;
    return 0;
}

int main(void) {
    uint8_t good[] = {0xC3, 1, 0, 2, 0xAA, 0xBB};
    uint8_t shrt[] = {0xC3, 1};
    uint8_t sync[] = {0x00, 1, 0, 0};
    uint8_t big[]  = {0xC3, 1, 0x04, 0x00};
    uint8_t mism[] = {0xC3, 1, 0, 3, 0xAA};
    printf("good: %d\nshort: %d\nbad sync: %d\ntoo big: %d\nmismatch: %d\n",
           validate(good, sizeof good, 64), validate(shrt, sizeof shrt, 64),
           validate(sync, sizeof sync, 64), validate(big, sizeof big, 64),
           validate(mism, sizeof mism, 64));
    return 0;
}

