#include <stdio.h>

#define N 4

/* Character ring buffer. When full, enqueue overwrites the oldest item. */
struct Ring { char d[N]; int head; int count; };

static void enqueue(struct Ring *r, char c) {
    int tail = (r->head + r->count) % N;      /* next free slot */
    r->d[tail] = c;
    if (r->count == N) r->head = (r->head + 1) % N;   /* full: drop oldest */
    else r->count++;
}

static int dequeue(struct Ring *r, char *c) {
    if (r->count == 0) return 0;
    *c = r->d[r->head];
    r->head = (r->head + 1) % N;              /* advance read position */
    r->count--;
    return 1;
}

int main(void) {
    struct Ring r = {{0}, 0, 0};
    const char *text = "ABCDEF";
    char c;
    for (const char *p = text; *p; p++) {
        enqueue(&r, *p);
        printf("enqueue %c (count=%d)\n", *p, r.count);
    }
    printf("dequeue order:");
    while (dequeue(&r, &c)) printf(" %c", c);
    printf("\n");
    return 0;
}

