#include <stdio.h>
#include <stdint.h>
#include <inttypes.h>
/* Simple protocol packet: exact sizes matter on the wire */
struct Header {
    uint8_t  version;
    uint8_t  type;
    uint16_t length;
    uint32_t seq;
};
int main(void) {
    struct Header h = {1, 7, 512, 100000u};
    printf("version=%u type=%u length=%u seq=%" PRIu32 "\n",
           (unsigned)h.version, (unsigned)h.type, (unsigned)h.length, h.seq);
    uint8_t wire[8];
    wire[0] = h.version; wire[1] = h.type;
    wire[2] = (uint8_t)(h.length >> 8); wire[3] = (uint8_t)(h.length & 0xFF);
    for (int i = 0; i < 4; i++) wire[4 + i] = (uint8_t)(h.seq >> (24 - 8 * i));
    printf("Bytes on wire (big-endian):");
    for (int i = 0; i < 8; i++) printf(" %02X", (unsigned)wire[i]);
    putchar('\n');
    return 0;
}

