#include <stdio.h>
#include <limits.h>
static int safe_mul(int a, int b, int *res) {
    if (a > 0) {
        if (b > 0 ? a > INT_MAX / b : b < INT_MIN / a) return 0;
    } else if (a < 0) {
        if (b > 0 ? a < INT_MIN / b : (a != 0 && b < INT_MAX / a)) return 0;
    }
    *res = a * b;
    return 1;
}
int main(void) {
    int pairs[][2] = {{1000, 1000}, {100000, 100000}, {-50000, 50000}, {-65536, -32768}, {0, INT_MAX}};
    for (int i = 0; i < 5; i++) {
        int r;
        if (safe_mul(pairs[i][0], pairs[i][1], &r))
            printf("%d * %d = %d\n", pairs[i][0], pairs[i][1], r);
        else
            printf("%d * %d would overflow\n", pairs[i][0], pairs[i][1]);
    }
    return 0;
}

#include <stdio.h>
#include <math.h>
static int nearly_equal(double a, double b, double rel) {
    double diff = fabs(a - b);
    double scale = fmax(fabs(a), fabs(b));
    return diff <= rel * scale || diff < 1e-12;
}
int main(void) {
    double x = 0.0;
    for (int i = 0; i < 10; i++) x += 0.1;
    printf("sum of ten 0.1 = %.17g\n", x);
    printf("x == 1.0 : %d\n", x == 1.0);
    printf("nearly_equal(x, 1.0) : %d\n", nearly_equal(x, 1.0, 1e-9));
    double big1 = 1e10 + 0.0001, big2 = 1e10;
    printf("big values nearly equal (relative): %d\n", nearly_equal(big1, big2, 1e-9));
    printf("sqrt(2)^2 == 2 : %d, nearly : %d\n", sqrt(2.0) * sqrt(2.0) == 2.0,
           nearly_equal(sqrt(2.0) * sqrt(2.0), 2.0, 1e-9));
    return 0;
}

