#include <stdio.h>
#include <stdint.h>

// A tiny protocol packet: 1 byte version, 1 byte type, 2 byte length, 4 byte id
struct Packet {
    uint8_t  version;
    uint8_t  type;
    uint16_t length;
    uint32_t id;
};

// Serialize into exactly 8 bytes in network (big-endian) order
static void pack(const struct Packet *p, uint8_t out[8]) {
    out[0] = p->version;
    out[1] = p->type;
    out[2] = (uint8_t)(p->length >> 8);
    out[3] = (uint8_t)(p->length & 0xFF);
    out[4] = (uint8_t)(p->id >> 24);
    out[5] = (uint8_t)(p->id >> 16);
    out[6] = (uint8_t)(p->id >> 8);
    out[7] = (uint8_t)(p->id);
}

// Rebuild the struct from the bytes
static struct Packet unpack(const uint8_t in[8]) {
    struct Packet p;
    p.version = in[0];
    p.type = in[1];
    p.length = (uint16_t)((in[2] << 8) | in[3]);
    p.id = ((uint32_t)in[4] << 24) | ((uint32_t)in[5] << 16) | ((uint32_t)in[6] << 8) | in[7];
    return p;
}

int main(void) {
    struct Packet p = {1, 7, 0x0102, 0xCAFEBABE};
    uint8_t wire[8];
    pack(&p, wire);
    printf("Wire bytes:");
    for (int i = 0; i < 8; i++) printf(" %02X", wire[i]);
    printf("\n");
    struct Packet q = unpack(wire);
    printf("version=%u type=%u length=%u id=0x%08X\n",
           (unsigned)q.version, (unsigned)q.type, (unsigned)q.length, (unsigned)q.id);
    return 0;
}

#include <stdio.h>
#include <limits.h>

// a + b would overflow when it leaves [INT_MIN, INT_MAX]; test BEFORE adding
static int safe_add(int a, int b, int *result) {
    if (b > 0 && a > INT_MAX - b) return 0;   // would exceed max
    if (b < 0 && a < INT_MIN - b) return 0;   // would go below min
    *result = a + b;
    return 1;
}

int main(void) {
    struct { int a, b; } cases[] = {
        {1, 2}, {INT_MAX, 0}, {INT_MAX, 1}, {INT_MIN, -1},
        {INT_MIN, 0}, {INT_MAX, INT_MIN}, {-100, -200}
    };
    // Signed overflow is undefined behaviour, so we never perform it.
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        int r;
        if (safe_add(cases[i].a, cases[i].b, &r))
            printf("%11d + %11d = %d\n", cases[i].a, cases[i].b, r);
        else
            printf("%11d + %11d -> overflow avoided\n", cases[i].a, cases[i].b);
    }
    // Unsigned arithmetic is well defined (wraps modulo 2^N)
    unsigned int u = UINT_MAX;
    printf("UINT_MAX + 1u wraps to %u\n", u + 1u);
    return 0;
}

