// Equal if the difference is within an absolute OR relative tolerance
static int nearly_equal(double a, double b, double eps) {
    double diff = fabs(a - b);
    double scale = fmax(fabs(a), fabs(b));
    printf("  diff = %.3e, allowed = %.3e (absolute) / %.3e (relative)\n", diff, eps, eps * scale);
    return diff <= eps || diff <= eps * scale;
}

