    printf("x == y ? %s\n", x == y ? "yes" : "no");
    printf("Tolerance test with eps = 1e-9:\n");
    printf("  -> %s\n", nearly_equal(x, y, 1e-9) ? "equal" : "different");
    printf("Compare 1000000.0 and 1000000.5:\n");
    printf("  -> %s\n", nearly_equal(1000000.0, 1000000.5, 1e-9) ? "equal" : "different");
    return 0;
}

