// size_t is unsigned: it is the right type for sizes and indexes.
static long sum_array(const int *first, size_t n) {
    long total = 0;
    const int *end = first + n;                 // one past the last element
    for (const int *p = first; p != end; p++)   // pointer walk
        total += *p;
    return total;
}

