#include <stdio.h>
#include <stdint.h>

/* Unsigned types have no sign bit and no undefined shifts, so they are the
   right choice for bit manipulation. Every operation below is O(1) time and
   uses O(1) extra space (a single machine word). */

static uint32_t set_bit(uint32_t v, unsigned n)    { return v | (1u << n); }
static uint32_t clear_bit(uint32_t v, unsigned n)  { return v & ~(1u << n); }
static uint32_t toggle_bit(uint32_t v, unsigned n) { return v ^ (1u << n); }
static int      test_bit(uint32_t v, unsigned n)   { return (v >> n) & 1u; }

// Kernighan's trick: loops once per set bit, so O(popcount) time
static int count_bits(uint32_t v) {
    int c = 0;
    while (v) { v &= v - 1; c++; }
    return c;
}

int main(void) {
    uint32_t flags = 0;
    flags = set_bit(flags, 0);
    flags = set_bit(flags, 3);
    flags = set_bit(flags, 31);
    printf("after set 0,3,31 : 0x%08X\n", (unsigned)flags);
    flags = clear_bit(flags, 3);
    printf("after clear 3    : 0x%08X\n", (unsigned)flags);
    flags = toggle_bit(flags, 4);
    printf("after toggle 4   : 0x%08X\n", (unsigned)flags);
    printf("bit 4 = %d, bit 3 = %d\n", test_bit(flags, 4), test_bit(flags, 3));
    printf("bits set         : %d\n", count_bits(flags));
    return 0;
}

