/* Never assume int is 32 bits: use CHAR_BIT, sizeof and limits.h instead.
   On x86-64 Linux gcc the output shows 32 bits, but the code is portable. */

// Absolute value that reports failure for INT_MIN (cannot be negated)
static int safe_abs(int x, int *out) {
    if (x == INT_MIN) return 0;
    *out = x < 0 ? -x : x;
    return 1;
}

int main(void) {
    int bits = (int)(sizeof(int) * CHAR_BIT);
    printf("int has %d bits\n", bits);
    printf("INT_MIN = %d, INT_MAX = %d\n", INT_MIN, INT_MAX);

    int tests[] = {25, -25, 0, INT_MAX, INT_MIN, INT_MIN + 1};
    for (size_t i = 0; i < sizeof tests / sizeof tests[0]; i++) {
        int r;
        const char *kind = tests[i] == INT_MIN ? "minimum" : tests[i] == INT_MAX ? "maximum" : "normal";
        if (safe_abs(tests[i], &r))
            printf("%-8s abs(%d) = %d\n", kind, tests[i], r);
        else
            printf("%-8s abs(%d) not representable\n", kind, tests[i]);
    }
    return 0;
}

