// Returns 1 and stores the value only if the WHOLE string is a valid int
static int parse_int(const char *s, int *out) {
    char *end;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (end == s) return 0;              // no digits
    if (*end != '\0') return 0;          // trailing junk
    if (errno == ERANGE || v < INT_MIN || v > INT_MAX) return 0;   // too big
    *out = (int)v;
    return 1;
}

int main(void) {
    const char *inputs[] = {"123", "-45", "  7", "12abc", "", "abc", "2147483647", "2147483648", "99999999999999999999"};
    for (size_t i = 0; i < sizeof inputs / sizeof inputs[0]; i++) {
        int v;
        if (parse_int(inputs[i], &v))
            printf("\"%s\" -> %d\n", inputs[i], v);
        else
            printf("\"%s\" -> rejected\n", inputs[i]);
    }
    return 0;
}

