#include <stdio.h>
#include <limits.h>

/* Cost: every check below is a few comparisons, O(1) time and O(1) space.
   The checks are far cheaper than the undefined behaviour they prevent. */

static int mul_ok(int a, int b) {
    if (a == 0 || b == 0) return 1;
    if (a > 0 && b > 0) return a <= INT_MAX / b;
    if (a < 0 && b < 0) return a >= INT_MAX / b;
    if (a > 0) return b >= INT_MIN / a;       // a > 0, b < 0
    return a >= INT_MIN / b;                  // a < 0, b > 0
}

static int div_ok(int a, int b) {
    return b != 0 && !(a == INT_MIN && b == -1);
}

int main(void) {
    int pairs[][2] = {{6, 7}, {65536, 32768}, {-65536, 32768}, {-65536, 32769}, {INT_MIN, -1}, {9, 0}};
    printf("%12s %12s  %-9s %-9s\n", "a", "b", "a*b", "a/b");
    for (size_t i = 0; i < sizeof pairs / sizeof pairs[0]; i++) {
        int a = pairs[i][0], b = pairs[i][1];
        printf("%12d %12d  %-9s %-9s\n", a, b,
               mul_ok(a, b) ? "safe" : "overflow", div_ok(a, b) ? "safe" : "invalid");
    }
    return 0;
}

