#include <stdio.h>
#include <stdlib.h>

// A singly linked list: NULL marks "no next node"
struct Node {
    int value;
    struct Node *next;
};

int main(void) {
    struct Node *head = NULL;                 // empty list = NULL head

    // Always check malloc for NULL (allocation failure)
    for (int i = 3; i >= 1; i--) {
        struct Node *n = malloc(sizeof *n);
        if (n == NULL) {
            printf("out of memory\n");
            return 1;
        }
        n->value = i * 10;
        n->next = head;                       // new node points at old head
        head = n;
    }

    // Traverse until we reach NULL
    for (struct Node *p = head; p != NULL; p = p->next)
        printf("node %d -> %s\n", p->value, p->next ? "next" : "NULL");

    // Free every node, then reset the pointer so it is never used dangling
    while (head != NULL) {
        struct Node *tmp = head->next;
        free(head);
        head = tmp;
    }
    printf("head is %s after freeing\n", head == NULL ? "NULL" : "not NULL");
    free(NULL);                               // free(NULL) is legal and does nothing
    return 0;
}

