#define MAX 20
#define FILE_NAME "students.dat"

struct Student { int roll; char name[30]; float marks; };

static struct Student list[MAX];
static int count = 0;

static int find(int roll)
{
    for (int i = 0; i < count; i++)
        if (list[i].roll == roll) return i;
    return -1;
}

static void add_student(int roll, const char *name, float marks)
{
    if (count == MAX || find(roll) >= 0) { printf("Add failed for roll %d\n", roll); return; }
    list[count].roll = roll;
    strcpy(list[count].name, name);
    list[count].marks = marks;
    count++;
    printf("Added %s\n", name);
}

static void show_all(void)
{
    printf("Roll  Name        Marks\n");
    for (int i = 0; i < count; i++)
        printf("%-5d %-11s %.1f\n", list[i].roll, list[i].name, list[i].marks);
}

static void save(void)
{
    FILE *fp = fopen(FILE_NAME, "wb");
    if (fp == NULL) { printf("Cannot save\n"); return; }
    fwrite(&count, sizeof count, 1, fp);
    fwrite(list, sizeof list[0], (size_t)count, fp);
    fclose(fp);
    printf("Saved %d records to file\n", count);
}

