#define FILE_NAME "employees.txt"

struct Employee { int id; char name[20]; char dept[12]; double salary; };

int main(void)
{
    struct Employee e[4] = {
        {1, "Anil", "Sales", 32000},
        {2, "Bela", "IT", 54000},
        {3, "Chen", "IT", 61000},
        {4, "Dina", "HR", 28500}
    };
    struct Employee r;
    FILE *fp = fopen(FILE_NAME, "w");
    double total = 0, best = 0;
    char best_name[20] = "";
