#include <stdio.h>
#include <string.h>

#define NB 4
#define MAXLOG 20

struct Book { int id; char title[24]; int issued; char holder[16]; };
struct Record { int id; char member[16]; char action[7]; };

static struct Book books[NB] = {
    {1, "C Primer", 0, ""}, {2, "Data Structs", 0, ""},
    {3, "Algorithms", 0, ""}, {4, "Networks", 0, ""}
};
static struct Record log_[MAXLOG];
static int nlog = 0;

static void record(int id, const char *m, const char *a)
{
    if (nlog < MAXLOG) { log_[nlog].id = id; strcpy(log_[nlog].member, m); strcpy(log_[nlog].action, a); nlog++; }
}

static void issue(int id, const char *m)
{
    if (id < 1 || id > NB) { printf("Issue: no book %d\n", id); return; }
    struct Book *b = &books[id - 1];
    if (b->issued) { printf("Issue: '%s' already issued to %s\n", b->title, b->holder); return; }
    b->issued = 1; strcpy(b->holder, m);
    record(id, m, "ISSUE");
    printf("Issued '%s' to %s\n", b->title, m);
}

static void give_back(int id)
{
    if (id < 1 || id > NB) { printf("Return: no book %d\n", id); return; }
    struct Book *b = &books[id - 1];
    if (!b->issued) { printf("Return: '%s' was not issued\n", b->title); return; }
    record(id, b->holder, "RETURN");
    printf("Returned '%s' from %s\n", b->title, b->holder);
    b->issued = 0; b->holder[0] = '\0';
}

int main(void)
{
    char cmd[10], who[16];
    int id;
    while (scanf("%9s", cmd) == 1) {
        if (strcmp(cmd, "issue") == 0 && scanf("%d %15s", &id, who) == 2) issue(id, who);
        else if (strcmp(cmd, "return") == 0 && scanf("%d", &id) == 1) give_back(id);
        else if (strcmp(cmd, "end") == 0) break;
        else printf("Bad command\n");
    }
    printf("\n--- Book status ---\n");
    for (int i = 0; i < NB; i++)
        printf("%d %-13s %s %s\n", books[i].id, books[i].title,
               books[i].issued ? "ISSUED to" : "available", books[i].holder);
    printf("--- Transaction history ---\n");
    for (int i = 0; i < nlog; i++)
        printf("%2d. %-6s book %d  %s\n", i + 1, log_[i].action, log_[i].id, log_[i].member);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAX 10
#define LOW 5

struct Item { char name[16]; int qty; double price; };

static struct Item inv[MAX];
static int n = 0;

static int find(const char *name)
{
    for (int i = 0; i < n; i++)
        if (strcmp(inv[i].name, name) == 0) return i;
    return -1;
}

static void low_report(void)
{
    int any = 0;
    printf("Low-stock report (qty < %d):\n", LOW);
    for (int i = 0; i < n; i++)
        if (inv[i].qty < LOW) { printf("  %-8s only %d left\n", inv[i].name, inv[i].qty); any = 1; }
    if (!any) printf("  none\n");
}

int main(void)
{
    char cmd[10], name[16];
    int q;
    double p, value = 0;
    while (scanf("%9s", cmd) == 1) {
        if (strcmp(cmd, "add") == 0 && scanf("%15s %d %lf", name, &q, &p) == 3 && n < MAX && find(name) < 0) {
            strcpy(inv[n].name, name); inv[n].qty = q; inv[n].price = p; n++;
            printf("Added %s (%d @ %.2f)\n", name, q, p);
        } else if (strcmp(cmd, "sell") == 0 && scanf("%15s %d", name, &q) == 2) {
            int i = find(name);
            if (i < 0) printf("Unknown item %s\n", name);
            else if (inv[i].qty < q) printf("Not enough %s (have %d)\n", name, inv[i].qty);
            else { inv[i].qty -= q; printf("Sold %d %s, left %d\n", q, name, inv[i].qty); }
        } else if (strcmp(cmd, "restock") == 0 && scanf("%15s %d", name, &q) == 2) {
            int i = find(name);
            if (i < 0) printf("Unknown item %s\n", name);
            else { inv[i].qty += q; printf("Restocked %s, now %d\n", name, inv[i].qty); }
        } else if (strcmp(cmd, "report") == 0) low_report();
        else printf("Bad command %s\n", cmd);
    }
    printf("\nFinal stock:\n");
    for (int i = 0; i < n; i++) {
        printf("  %-8s %3d x %6.2f\n", inv[i].name, inv[i].qty, inv[i].price);
        value += inv[i].qty * inv[i].price;
    }
    printf("Total stock value: %.2f\n", value);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXT 30

struct Account { int no; char owner[16]; double balance; int first, last; };
struct Txn { int acc; char type; double amount; double after; };

static struct Account acct[3] = {
    {1001, "Asha", 500.0, 0, 0}, {1002, "Ravi", 150.0, 0, 0}, {1003, "Meena", 0.0, 0, 0}
};
static struct Txn txn[MAXT];
static int nt = 0;

static struct Account *find(int no)
{
    for (int i = 0; i < 3; i++) if (acct[i].no == no) return &acct[i];
    return NULL;
}

static void log_txn(int no, char type, double amt, double after)
{
    if (nt < MAXT) { txn[nt].acc = no; txn[nt].type = type; txn[nt].amount = amt; txn[nt].after = after; nt++; }
}

int main(void)
{
    char op;
    int no, to;
    double amt;
    while (scanf(" %c", &op) == 1) {
        if (op == 'D' && scanf("%d %lf", &no, &amt) == 2) {
            struct Account *a = find(no);
            if (!a || amt <= 0) { printf("Deposit rejected\n"); continue; }
            a->balance += amt; log_txn(no, 'D', amt, a->balance);
            printf("Deposited %.2f into %d\n", amt, no);
        } else if (op == 'W' && scanf("%d %lf", &no, &amt) == 2) {
            struct Account *a = find(no);
            if (!a || amt <= 0 || amt > a->balance) { printf("Withdrawal rejected for %d\n", no); continue; }
            a->balance -= amt; log_txn(no, 'W', amt, a->balance);
            printf("Withdrew %.2f from %d\n", amt, no);
        } else if (op == 'T' && scanf("%d %d %lf", &no, &to, &amt) == 3) {
            struct Account *a = find(no), *b = find(to);
            if (!a || !b || amt <= 0 || amt > a->balance) { printf("Transfer rejected\n"); continue; }
            a->balance -= amt; b->balance += amt;
            log_txn(no, 'W', amt, a->balance); log_txn(to, 'D', amt, b->balance);
            printf("Transferred %.2f from %d to %d\n", amt, no, to);
        } else if (op == 'Q') break;
        else printf("Bad input\n");
    }
    printf("\nBalances:\n");
    for (int i = 0; i < 3; i++) printf("  %d %-6s %8.2f\n", acct[i].no, acct[i].owner, acct[i].balance);
    printf("Transaction history:\n");
    for (int i = 0; i < nt; i++)
        printf("  #%d acct %d %s %7.2f -> balance %7.2f\n", i + 1, txn[i].acc,
               txn[i].type == 'D' ? "deposit " : "withdraw", txn[i].amount, txn[i].after);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define SEATS 10

int main(void)
{
    char name[SEATS][16];          /* empty string = free seat */
    char cmd[10], who[16];
    int seat;

    for (int i = 0; i < SEATS; i++) name[i][0] = '\0';

    while (scanf("%9s", cmd) == 1) {
        if (strcmp(cmd, "book") == 0 && scanf("%d %15s", &seat, who) == 2) {
            if (seat < 1 || seat > SEATS) printf("Seat %d does not exist\n", seat);
            else if (name[seat - 1][0] != '\0') printf("Seat %d already taken by %s\n", seat, name[seat - 1]);
            else { strcpy(name[seat - 1], who); printf("Seat %d booked for %s\n", seat, who); }
        } else if (strcmp(cmd, "cancel") == 0 && scanf("%d", &seat) == 1) {
            if (seat < 1 || seat > SEATS) printf("Seat %d does not exist\n", seat);
            else if (name[seat - 1][0] == '\0') printf("Seat %d is not booked\n", seat);
            else { printf("Cancelled seat %d (%s)\n", seat, name[seat - 1]); name[seat - 1][0] = '\0'; }
        } else if (strcmp(cmd, "show") == 0) {
            int free_count = 0;
            printf("Seat map: ");
            for (int i = 0; i < SEATS; i++) {
                printf("%c", name[i][0] ? 'X' : '_');
                if (!name[i][0]) free_count++;
            }
            printf("  (%d free)\n", free_count);
        } else printf("Bad command\n");
    }
    printf("Passenger list:\n");
    for (int i = 0; i < SEATS; i++)
        if (name[i][0]) printf("  Seat %2d : %s\n", i + 1, name[i]);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXP 5
#define MAXA 8

struct Patient { int id; char name[16]; int age; char history[40]; };
struct Appt { int pid; int slot; };   /* slot = hour of day */

static struct Patient pat[MAXP];
static int np = 0;
static struct Appt ap[MAXA];
static int na = 0;

static int find(int id)
{
    for (int i = 0; i < np; i++) if (pat[i].id == id) return i;
    return -1;
}

int main(void)
{
    char cmd[10], text[16];
    int id, age, slot;
    while (scanf("%9s", cmd) == 1) {
        if (strcmp(cmd, "register") == 0 && scanf("%d %15s %d", &id, text, &age) == 3 && np < MAXP) {
            pat[np].id = id; strcpy(pat[np].name, text); pat[np].age = age;
            strcpy(pat[np].history, "none"); np++;
            printf("Registered patient %d (%s)\n", id, text);
        } else if (strcmp(cmd, "book") == 0 && scanf("%d %d", &id, &slot) == 2) {
            int clash = 0;
            for (int i = 0; i < na; i++) if (ap[i].slot == slot) clash = 1;
            if (find(id) < 0) printf("Unknown patient %d\n", id);
            else if (clash) printf("Slot %d:00 is already taken\n", slot);
            else if (na == MAXA) printf("Schedule full\n");
            else { ap[na].pid = id; ap[na].slot = slot; na++; printf("Booked patient %d at %d:00\n", id, slot); }
        } else if (strcmp(cmd, "note") == 0 && scanf("%d %15s", &id, text) == 2) {
            int i = find(id);
            if (i < 0) printf("Unknown patient %d\n", id);
            else { strcpy(pat[i].history, text); printf("Record updated for %d\n", id); }
        } else printf("Bad command\n");
    }
    printf("\nPatients:\n");
    for (int i = 0; i < np; i++)
        printf("  %d %-6s age %d history: %s\n", pat[i].id, pat[i].name, pat[i].age, pat[i].history);
    printf("Appointments (in booking order):\n");
    for (int i = 0; i < na; i++)
        printf("  %2d:00  %s\n", ap[i].slot, pat[find(ap[i].pid)].name);
    return 0;
}

