#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define FILE_NAME "contacts.txt"

struct Contact { char name[20]; char phone[16]; };

static void lower(char *d, const char *s)
{
    while ((*d++ = (char)tolower((unsigned char)*s++)) != '\0') { }
}

int main(void)
{
    struct Contact c[10];
    int n = 0;
    char term[20], a[20], b[20];
    FILE *fp;

    /* read contacts typed as "name phone" until the word END */
    while (n < 10 && scanf("%19s", c[n].name) == 1 && strcmp(c[n].name, "END") != 0) {
        if (scanf("%15s", c[n].phone) != 1) break;
        n++;
    }
    /* save to file */
    fp = fopen(FILE_NAME, "w");
    if (fp == NULL) return 1;
    for (int i = 0; i < n; i++) fprintf(fp, "%s %s\n", c[i].name, c[i].phone);
    fclose(fp);
    printf("Saved %d contacts\n", n);

    /* reload from file to prove persistence */
    n = 0;
    fp = fopen(FILE_NAME, "r");
    if (fp == NULL) return 1;
    while (n < 10 && fscanf(fp, "%19s %15s", c[n].name, c[n].phone) == 2) n++;
    fclose(fp);
    remove(FILE_NAME);
    printf("Reloaded %d contacts\n", n);

    /* search: case-insensitive partial match */
    while (scanf("%19s", term) == 1) {
        int hits = 0;
        lower(b, term);
        printf("Search \"%s\":\n", term);
        for (int i = 0; i < n; i++) {
            lower(a, c[i].name);
            if (strstr(a, b) != NULL) { printf("  %-8s %s\n", c[i].name, c[i].phone); hits++; }
        }
        if (hits == 0) printf("  no match\n");
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXLINES 10
#define FILE_NAME "note.txt"

int main(void)
{
    char text[MAXLINES][60];
    int n = 0;
    char line[80], cmd[10];
    FILE *fp;

    /* each input line is a command: "append <text>", "display", "save" */
    while (fgets(line, sizeof line, stdin) != NULL) {
        line[strcspn(line, "\n")] = '\0';
        if (sscanf(line, "%9s", cmd) != 1) continue;
        if (strcmp(cmd, "append") == 0) {
            if (n == MAXLINES) { printf("Editor full\n"); continue; }
            const char *body = line + 6;
            while (*body == ' ') body++;
            strncpy(text[n], body, 59); text[n][59] = '\0';
            n++;
            printf("Line %d added\n", n);
        } else if (strcmp(cmd, "display") == 0) {
            printf("---- document ----\n");
            for (int i = 0; i < n; i++) printf("%2d| %s\n", i + 1, text[i]);
            printf("------------------\n");
        } else if (strcmp(cmd, "save") == 0) {
            fp = fopen(FILE_NAME, "w");
            if (fp == NULL) { printf("Save failed\n"); continue; }
            for (int i = 0; i < n; i++) fprintf(fp, "%s\n", text[i]);
            fclose(fp);
            printf("Saved %d lines to %s\n", n, FILE_NAME);
        } else printf("Unknown command: %s\n", cmd);
    }
    /* verify the saved file */
    fp = fopen(FILE_NAME, "r");
    if (fp != NULL) {
        int chars = 0, c;
        while ((c = fgetc(fp)) != EOF) chars++;
        fclose(fp);
        printf("File holds %d characters\n", chars);
        remove(FILE_NAME);
    }
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <math.h>

#define FILE_NAME "data.csv"

int main(void)
{
    const char *rows =
        "name,math,physics,age\n"
        "Asha,90,85,17\n"
        "Ravi,72,64,18\n"
        "Meena,88,91,17\n"
        "Kiran,65,70,19\n";
    FILE *fp = fopen(FILE_NAME, "w");
    char line[100];
    double sum[3] = {0}, mn[3], mx[3], sq[3] = {0};
    char head[4][12];
    int n = 0;

    if (fp == NULL) return 1;
    fputs(rows, fp);
    fclose(fp);

    fp = fopen(FILE_NAME, "r");
    if (fp == NULL) return 1;
    /* header line: split on commas */
    if (fgets(line, sizeof line, fp) == NULL) return 1;
    line[strcspn(line, "\n")] = '\0';
    char *tok = strtok(line, ",");
    for (int c = 0; tok != NULL && c < 4; c++, tok = strtok(NULL, ",")) strcpy(head[c], tok);

    while (fgets(line, sizeof line, fp) != NULL) {
        char nm[12];
        double v[3];
        if (sscanf(line, "%11[^,],%lf,%lf,%lf", nm, &v[0], &v[1], &v[2]) != 4) continue;
        for (int c = 0; c < 3; c++) {
            if (n == 0 || v[c] < mn[c]) mn[c] = v[c];
            if (n == 0 || v[c] > mx[c]) mx[c] = v[c];
            sum[c] += v[c];
            sq[c] += v[c] * v[c];
        }
        n++;
    }
    fclose(fp);
    remove(FILE_NAME);

    printf("Rows read: %d\n", n);
    printf("%-8s %7s %7s %7s %7s\n", "Column", "Min", "Max", "Mean", "StdDev");
    for (int c = 0; c < 3; c++) {
        double mean = sum[c] / n;
        printf("%-8s %7.1f %7.1f %7.2f %7.2f\n", head[c + 1], mn[c], mx[c], mean,
               sqrt(sq[c] / n - mean * mean));
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

#define FILE_NAME "app.log"

int main(void)
{
    const char *log =
        "2024-03-01 INFO server started\n"
        "2024-03-01 ERROR disk full\n"
        "2024-03-02 WARN low memory\n"
        "2024-03-02 ERROR timeout while reading\n"
        "2024-03-02 ERROR bad request\n"
        "2024-03-03 INFO backup done\n";
    FILE *fp = fopen(FILE_NAME, "w");
    char line[100];
    char dates[10][11];
    int per_date[10] = {0};
    int nd = 0, errors = 0, warns = 0, lines = 0;

    if (fp == NULL) return 1;
    fputs(log, fp);
    fclose(fp);

    fp = fopen(FILE_NAME, "r");
    if (fp == NULL) return 1;
    while (fgets(line, sizeof line, fp) != NULL) {
        char date[11];
        lines++;
        if (sscanf(line, "%10s", date) != 1) continue;
        if (strstr(line, "ERROR") != NULL) {
            int k;
            errors++;
            /* find (or add) this date in the table */
            for (k = 0; k < nd; k++) if (strcmp(dates[k], date) == 0) break;
            if (k == nd && nd < 10) { strcpy(dates[nd], date); nd++; }
            if (k < 10) per_date[k]++;
        }
        if (strstr(line, "WARN") != NULL) warns++;
    }
    fclose(fp);
    remove(FILE_NAME);

    printf("Lines read : %d\n", lines);
    printf("ERROR count: %d\n", errors);
    printf("WARN count : %d\n", warns);
    printf("Errors per date:\n");
    for (int k = 0; k < nd; k++) printf("  %s : %d\n", dates[k], per_date[k]);
    return 0;
}

#include <stdio.h>
#include <ctype.h>

/* Recursive-descent parser:
   expr   = term   { (+|-) term }
   term   = factor { (*|/) factor }
   factor = number | '(' expr ')' | '-' factor            */
static const char *p;
static int error;

static double expr(void);

static void skip(void) { while (*p == ' ') p++; }

static double factor(void)
{
    double v = 0;
    skip();
    if (*p == '-') { p++; return -factor(); }
    if (*p == '(') {
        p++;
        v = expr();
        skip();
        if (*p == ')') p++; else error = 1;
        return v;
    }
    if (isdigit((unsigned char)*p) || *p == '.') {
        double scale = 0;
        while (isdigit((unsigned char)*p) || (*p == '.' && scale == 0)) {
            if (*p == '.') scale = 1;
            else { v = v * 10 + (*p - '0'); scale *= 10; }
            p++;
        }
        return scale > 0 ? v / scale : v;
    }
    error = 1;
    return 0;
}

static double term(void)
{
    double v = factor();
    for (;;) {
        skip();
        if (*p == '*') { p++; v *= factor(); }
        else if (*p == '/') {
            p++;
            double d = factor();
            if (d == 0) { error = 2; return 0; }
            v /= d;
        } else return v;
    }
}

static double expr(void)
{
    double v = term();
    for (;;) {
        skip();
        if (*p == '+') { p++; v += term(); }
        else if (*p == '-') { p++; v -= term(); }
        else return v;
    }
}

int main(void)
{
    char line[100];
    while (fgets(line, sizeof line, stdin) != NULL) {
        double r;
        for (char *q = line; *q; q++) if (*q == '\n') *q = '\0';
        p = line;
        error = 0;
        r = expr();
        skip();
        if (*p != '\0') error = error ? error : 1;
        if (error == 2) printf("%-22s => division by zero\n", line);
        else if (error) printf("%-22s => syntax error\n", line);
        else printf("%-22s => %g\n", line, r);
    }
    return 0;
}

#include <stdio.h>

#define R 6
#define C 7

static const char *maze[R] = {
    "S.#....",
    ".##.##.",
    "...#...",
    ".#...#.",
    ".#.#.#.",
    "...#..E"
};

int main(void)
{
    char grid[R][C + 1];
    int dist[R][C];
    int qr[R * C], qc[R * C], head = 0, tail = 0;
    int pr[R][C], pc[R][C];          /* parent cell of each cell */
    int sr = 0, sc = 0, er = 0, ec = 0;
    const int dr[4] = {-1, 1, 0, 0}, dc[4] = {0, 0, -1, 1};

    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            grid[i][j] = maze[i][j];
            dist[i][j] = -1;
            if (maze[i][j] == 'S') { sr = i; sc = j; }
            if (maze[i][j] == 'E') { er = i; ec = j; }
        }
        grid[i][C] = '\0';
    }
    /* BFS finds the shortest path in an unweighted grid */
    dist[sr][sc] = 0;
    qr[tail] = sr; qc[tail++] = sc;
    while (head < tail) {
        int r = qr[head], c = qc[head++];
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
            if (grid[nr][nc] == '#' || dist[nr][nc] != -1) continue;
            dist[nr][nc] = dist[r][c] + 1;
            pr[nr][nc] = r; pc[nr][nc] = c;
            qr[tail] = nr; qc[tail++] = nc;
        }
    }
    printf("Maze:\n");
    for (int i = 0; i < R; i++) printf("  %s\n", maze[i]);
    if (dist[er][ec] < 0) { printf("No path exists\n"); return 0; }
    printf("Shortest path length: %d steps\n", dist[er][ec]);
    /* walk back from E to S, marking the path */
    for (int r = pr[er][ec], c = pc[er][ec]; !(r == sr && c == sc);) {
        int t = pr[r][c];
        grid[r][c] = '*';
        c = pc[r][c];
        r = t;
    }
    printf("Path marked with *:\n");
    for (int i = 0; i < R; i++) printf("  %s\n", grid[i]);
    return 0;
}

#include <stdio.h>

#define N 6
#define INF 1000000

int main(void)
{
    const char *city[N] = {"A", "B", "C", "D", "E", "F"};
    int w[N][N] = {{0}};              /* 0 = no road */
    int dist[N], prev[N], done[N];
    int edges, u, v, c, src, dst;

    /* input: number of roads, then "u v cost" per road, then source and destination */
    if (scanf("%d", &edges) != 1) return 0;
    for (int i = 0; i < edges; i++) {
        if (scanf("%d %d %d", &u, &v, &c) != 3 || u < 0 || v < 0 || u >= N || v >= N || c <= 0) {
            printf("Bad road %d\n", i + 1);
            continue;
        }
        w[u][v] = w[v][u] = c;
    }
    if (scanf("%d %d", &src, &dst) != 2 || src < 0 || src >= N || dst < 0 || dst >= N) {
        printf("Bad source/destination\n");
        return 0;
    }
    for (int i = 0; i < N; i++) { dist[i] = INF; prev[i] = -1; done[i] = 0; }
    dist[src] = 0;
    /* Dijkstra: repeatedly settle the closest unvisited city */
    for (int k = 0; k < N; k++) {
        int best = -1;
        for (int i = 0; i < N; i++)
            if (!done[i] && dist[i] < INF && (best < 0 || dist[i] < dist[best])) best = i;
        if (best < 0) break;
        done[best] = 1;
        for (int j = 0; j < N; j++)
            if (w[best][j] && dist[best] + w[best][j] < dist[j]) {
                dist[j] = dist[best] + w[best][j];
                prev[j] = best;
            }
    }
    printf("Shortest distances from %s:\n", city[src]);
    for (int i = 0; i < N; i++) {
        if (dist[i] == INF) printf("  to %s : unreachable\n", city[i]);
        else printf("  to %s : %d\n", city[i], dist[i]);
    }
    if (dist[dst] == INF) { printf("No route from %s to %s\n", city[src], city[dst]); return 0; }
    int path[N], len = 0;
    for (int x = dst; x != -1; x = prev[x]) path[len++] = x;
    printf("Route %s to %s (cost %d): ", city[src], city[dst], dist[dst]);
    for (int i = len - 1; i >= 0; i--) printf("%s%s", city[path[i]], i ? " -> " : "\n");
    return 0;
}

#include <stdio.h>

int g[9][9] = {
    {5,3,0,0,7,0,0,0,0},{6,0,0,1,9,5,0,0,0},{0,9,8,0,0,0,0,6,0},
    {8,0,0,0,6,0,0,0,3},{4,0,0,8,0,3,0,0,1},{7,0,0,0,2,0,0,0,6},
    {0,6,0,0,0,0,2,8,0},{0,0,0,4,1,9,0,0,5},{0,0,0,0,8,0,0,7,9}};

/* can value v sit at (r,c) without clashing with row, column or box? */
int ok(int r, int c, int v) {
    for (int i = 0; i < 9; i++) {
        if (i != c && g[r][i] == v) return 0;
        if (i != r && g[i][c] == v) return 0;
    }
    int br = r / 3 * 3, bc = c / 3 * 3;
    for (int i = br; i < br + 3; i++)
        for (int j = bc; j < bc + 3; j++)
            if ((i != r || j != c) && g[i][j] == v) return 0;
    return 1;
}

/* validator: every filled cell must be consistent */
int valid(void) {
    for (int r = 0; r < 9; r++)
        for (int c = 0; c < 9; c++)
            if (g[r][c] && !ok(r, c, g[r][c])) return 0;
    return 1;
}

/* backtracking solver */
int solve(void) {
    for (int r = 0; r < 9; r++)
        for (int c = 0; c < 9; c++)
            if (g[r][c] == 0) {
                for (int v = 1; v <= 9; v++)
                    if (ok(r, c, v)) {
                        g[r][c] = v;
                        if (solve()) return 1;
                        g[r][c] = 0;
                    }
                return 0;
            }
    return 1;
}

void show(const char *t) {
    printf("%s\n", t);
    for (int r = 0; r < 9; r++) {
        for (int c = 0; c < 9; c++) {
            if (g[r][c]) printf("%d ", g[r][c]); else printf(". ");
            if (c % 3 == 2 && c < 8) printf("| ");
        }
        printf("\n");
        if (r % 3 == 2 && r < 8) printf("------+-------+------\n");
    }
}

int main(void) {
    show("Puzzle:");
    printf("Puzzle valid so far: %s\n", valid() ? "yes" : "no");
    if (solve()) {
        show("Solved:");
        printf("Solution valid: %s\n", valid() ? "yes" : "no");
    } else printf("No solution\n");
    g[0][0] = 3;   /* break the grid: 3 already in row 0 */
    printf("After setting cell(0,0)=3, valid: %s\n", valid() ? "yes" : "no");
    return 0;
}

