/* case-insensitive count of occurrences of q in s */
int count(const char *s, const char *q) {
    int n = 0, lq = (int)strlen(q);
    for (int i = 0; s[i]; i++) {
        int j = 0;
        while (j < lq && s[i + j] && tolower((unsigned char)s[i + j]) == tolower((unsigned char)q[j])) j++;
        if (j == lq) n++;
    }
    return n;
}

void search(const char *file, const char *q) {
    FILE *f = fopen(file, "r");
    char line[200];
    int ln = 0, hits = 0, lines = 0;
    if (!f) { printf("Cannot open %s\n", file); return; }
    printf("Searching for \"%s\":\n", q);
    while (fgets(line, sizeof line, f)) {
        ln++;
        int c = count(line, q);
        if (c) {
            line[strcspn(line, "\n")] = 0;
            printf("  line %d (%d match%s): %s\n", ln, c, c > 1 ? "es" : "", line);
            hits += c; lines++;
        }
    }
    fclose(f);
    printf("  total: %d match(es) on %d line(s)\n", hits, lines);
}

