#include <stdio.h>
#include <string.h>

/* RLE: each run is written as <char><count>, e.g. AAAB -> A3B1 */
int rle(const char *in, char *out) {
    int o = 0;
    for (int i = 0; in[i];) {
        int j = i;
        while (in[j] == in[i]) j++;
        o += sprintf(out + o, "%c%d", in[i], j - i);
        i = j;
    }
    return o;
}

int main(void) {
    const char *tests[] = {"AAAABBBCCDAA", "abcd", "zzzzzzzzzzzz", "aabbbbbbbbbbbbc"};
    char out[200];
    printf("%-18s %-18s %s\n", "Original", "Compressed", "Ratio");
    for (int i = 0; i < 4; i++) {
        int n = rle(tests[i], out);
        printf("%-18s %-18s %d -> %d chars\n", tests[i], out, (int)strlen(tests[i]), n);
    }
    printf("Note: strings with few repeats (abcd) get longer, not shorter.\n");
    return 0;
}

#include <stdio.h>
#include <ctype.h>

/* Decode "<char><count>" pairs (the format of the RLE compressor).
   Returns 0 on success, -1 if the encoded text is malformed. */
int unrle(const char *in, char *out, int cap) {
    int o = 0;
    for (int i = 0; in[i];) {
        char ch = in[i++];
        if (!isdigit((unsigned char)in[i])) return -1;
        int n = 0;
        while (isdigit((unsigned char)in[i])) n = n * 10 + (in[i++] - '0');
        if (o + n >= cap) return -1;
        while (n--) out[o++] = ch;
    }
    out[o] = 0;
    return 0;
}

int main(void) {
    char enc[100], dec[500];
    printf("Enter encoded strings (end with 'quit'):\n");
    while (scanf("%99s", enc) == 1) {
        if (enc[0] == 'q' && enc[1] == 'u') break;
        if (unrle(enc, dec, sizeof dec) == 0) printf("%s -> %s\n", enc, dec);
        else printf("%s -> invalid encoded data\n", enc);
    }
    return 0;
}

