#include <stdio.h>
#include <stdlib.h>

#define N 5
int st[N], top = -1;
int q[N], head = 0, cnt = 0;
struct Node { int v; struct Node *next; } *list = NULL;

void showStack(void) {
    printf("Stack (bottom->top): [");
    for (int i = 0; i <= top; i++) printf(" %d", st[i]);
    printf(" ]  top=%d\n", top);
}
void showQueue(void) {
    printf("Queue (front->rear): [");
    for (int i = 0; i < cnt; i++) printf(" %d", q[(head + i) % N]);
    printf(" ]  size=%d\n", cnt);
}
void showList(void) {
    printf("List: ");
    for (struct Node *p = list; p; p = p->next) printf("%d -> ", p->v);
    printf("NULL\n");
}
void insertFront(int v) {
    struct Node *p = malloc(sizeof *p);
    if (!p) return;
    p->v = v; p->next = list; list = p;
}

int main(void) {
    printf("--- Stack ---\n");
    for (int i = 1; i <= 3; i++) { st[++top] = i * 10; printf("push %d\n", i * 10); showStack(); }
    printf("pop %d\n", st[top--]); showStack();
    printf("--- Queue ---\n");
    for (int i = 1; i <= 4; i++) { q[(head + cnt) % N] = i; cnt++; printf("enqueue %d\n", i); showQueue(); }
    printf("dequeue %d\n", q[head]); head = (head + 1) % N; cnt--; showQueue();
    printf("--- Linked list ---\n");
    for (int i = 1; i <= 3; i++) { insertFront(i * 5); printf("insert front %d\n", i * 5); showList(); }
    while (list) { struct Node *t = list; list = list->next; free(t); }
    return 0;
}

#include <stdio.h>
#include <string.h>

long cmp, swp;

void bubble(int *a, int n) {
    for (int i = 0; i < n - 1; i++)
        for (int j = 0; j < n - 1 - i; j++) {
            cmp++;
            if (a[j] > a[j + 1]) { int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t; swp++; }
        }
}
void selection(int *a, int n) {
    for (int i = 0; i < n - 1; i++) {
        int m = i;
        for (int j = i + 1; j < n; j++) { cmp++; if (a[j] < a[m]) m = j; }
        if (m != i) { int t = a[i]; a[i] = a[m]; a[m] = t; swp++; }
    }
}
void insertion(int *a, int n) {
    for (int i = 1; i < n; i++) {
        int k = a[i], j = i - 1;
        while (j >= 0) {
            cmp++;
            if (a[j] <= k) break;
            a[j + 1] = a[j]; swp++; j--;     /* one shift counted as one swap */
        }
        a[j + 1] = k;
    }
}

void bench(const char *label, const int *data, int n) {
    void (*fn[3])(int *, int) = {bubble, selection, insertion};
    const char *nm[3] = {"Bubble", "Selection", "Insertion"};
    int a[16];
    printf("%s\n  %-10s %12s %8s\n", label, "Algorithm", "Comparisons", "Swaps");
    for (int k = 0; k < 3; k++) {
        memcpy(a, data, n * sizeof(int));
        cmp = swp = 0;
        fn[k](a, n);
        printf("  %-10s %12ld %8ld\n", nm[k], cmp, swp);
    }
}

