#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

#define MAXH 10
static char hist[MAXH][100];   /* command history */
static int nh = 0;

/* run one command line; returns 1 when the shell should exit */
static int run(char *line)
{
    char copy[100];
    char *cmd;
    snprintf(copy, sizeof copy, "%s", line);
    cmd = strtok(line, " ");
    if (cmd == NULL) return 0;
    if (nh < MAXH) snprintf(hist[nh++], sizeof hist[0], "%s", copy);

    if (strcmp(cmd, "help") == 0) {
        printf("built-ins: help echo add upper words history exit\n");
    } else if (strcmp(cmd, "echo") == 0) {
        char *rest = strtok(NULL, "");
        printf("%s\n", rest ? rest : "");
    } else if (strcmp(cmd, "add") == 0) {
        char *a = strtok(NULL, " "), *b = strtok(NULL, " ");
        if (!a || !b) printf("usage: add X Y\n");
        else printf("%d\n", atoi(a) + atoi(b));
    } else if (strcmp(cmd, "upper") == 0) {
        char *rest = strtok(NULL, "");
        if (rest) for (; *rest; rest++) putchar(toupper((unsigned char)*rest));
        putchar('\n');
    } else if (strcmp(cmd, "words") == 0) {
        int n = 0;
        while (strtok(NULL, " ") != NULL) n++;
        printf("%d word(s)\n", n);
    } else if (strcmp(cmd, "history") == 0) {
        for (int i = 0; i < nh; i++) printf("  %d  %s\n", i + 1, hist[i]);
    } else if (strcmp(cmd, "exit") == 0) {
        printf("bye\n");
        return 1;
    } else {
        printf("%s: command not found\n", cmd);
    }
    return 0;
}

int main(void)
{
    char line[100];
    printf("MiniShell (type help)\n");
    while (1) {
        printf("mysh> ");
        if (fgets(line, sizeof line, stdin) == NULL) break;
        line[strcspn(line, "\n")] = '\0';
        printf("%s\n", line);          /* echo the command, since input is piped */
        if (run(line)) break;
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define BUCKETS 17

struct node { char word[20]; int count; struct node *next; };
static struct node *table[BUCKETS];

/* djb2 hash function */
static unsigned hash(const char *s)
{
    unsigned h = 5381;
    while (*s) h = h * 33 + (unsigned char)*s++;
    return h % BUCKETS;
}

static void add_word(const char *w)
{
    unsigned h = hash(w);
    struct node *n;
    for (n = table[h]; n; n = n->next)
        if (strcmp(n->word, w) == 0) { n->count++; return; }
    n = malloc(sizeof *n);
    if (!n) return;
    snprintf(n->word, sizeof n->word, "%s", w);
    n->count = 1;
    n->next = table[h];          /* insert at head of the chain */
    table[h] = n;
}

static int cmp(const void *a, const void *b)
{
    const struct node *x = *(struct node *const *)a, *y = *(struct node *const *)b;
    if (x->count != y->count) return y->count - x->count;
    return strcmp(x->word, y->word);
}

int main(void)
{
    const char *text = "The quick brown fox jumps over the lazy dog. The fox, being quick, "
                       "jumps again; the dog sleeps.";
    char w[20];
    int len = 0, total = 0, distinct = 0;
    struct node *list[100];

    for (const char *p = text; ; p++) {
        if (isalpha((unsigned char)*p) && len < 19) {
            w[len++] = (char)tolower((unsigned char)*p);
        } else if (len > 0) {
            w[len] = '\0';
            add_word(w);
            total++;
            len = 0;
        }
        if (*p == '\0') break;
    }
    for (int b = 0; b < BUCKETS; b++)
        for (struct node *n = table[b]; n; n = n->next)
            if (distinct < 100) list[distinct++] = n;
    qsort(list, (size_t)distinct, sizeof list[0], cmp);

    printf("Text: %s\n\n", text);
    printf("%-10s %s\n", "Word", "Count");
    for (int i = 0; i < distinct; i++) printf("%-10s %d\n", list[i]->word, list[i]->count);
    printf("\nTotal words: %d, distinct words: %d\n", total, distinct);

    for (int b = 0; b < BUCKETS; b++) {      /* free the chains */
        struct node *n = table[b];
        while (n) { struct node *t = n->next; free(n); n = t; }
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

static void swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }

static void utility(int c)
{
    switch (c) {
    case 1: printf("Square of 12 = %d\n", 12 * 12); break;
    case 2: printf("Cube of 5 = %d\n", 5 * 5 * 5); break;
    case 3: printf("7 is %s\n", 7 % 2 ? "odd" : "even"); break;
    case 4: { long f = 1; for (int i = 2; i <= 6; i++) f *= i; printf("6! = %ld\n", f); break; }
    case 5: { int a = 0, b = 1; printf("Fibonacci:"); for (int i = 0; i < 8; i++) { printf(" %d", a); int t = a + b; a = b; b = t; } printf("\n"); break; }
    case 6: { int n = 29, p = 1; for (int i = 2; i * i <= n; i++) if (n % i == 0) p = 0; printf("29 is %s\n", p ? "prime" : "not prime"); break; }
    case 7: { int a = 48, b = 18; while (b) { int t = a % b; a = b; b = t; } printf("GCD(48,18) = %d\n", a); break; }
    case 8: { int n = 1234, r = 0; while (n) { r = r * 10 + n % 10; n /= 10; } printf("Reverse of 1234 = %d\n", r); break; }
    case 9: { const char *s = "level"; int n = (int)strlen(s), ok = 1; for (int i = 0; i < n / 2; i++) if (s[i] != s[n - 1 - i]) ok = 0; printf("\"%s\" is %sa palindrome\n", s, ok ? "" : "not "); break; }
    case 10: { int n = 9875, s = 0; while (n) { s += n % 10; n /= 10; } printf("Digit sum of 9875 = %d\n", s); break; }
    case 11: printf("37 C = %.1f F\n", 37 * 9.0 / 5 + 32); break;
    case 12: printf("Area of circle r=3 = %.2f\n", 3.14159 * 3 * 3); break;
    case 13: { int a = 4, b = 9, d = 2, m = a; if (b > m) m = b; if (d > m) m = d; printf("Largest of 4,9,2 = %d\n", m); break; }
    case 14: { int x = 5, y = 8; swap(&x, &y); printf("After swap x=%d y=%d\n", x, y); break; }
    case 15: { long r = 1; for (int i = 0; i < 10; i++) r *= 2; printf("2^10 = %ld\n", r); break; }
    case 16: { const char *s = "programming"; int v = 0; for (; *s; s++) if (strchr("aeiou", *s)) v++; printf("Vowels in programming = %d\n", v); break; }
    case 17: { char s[] = "hello"; int n = (int)strlen(s); for (int i = 0; i < n / 2; i++) { char t = s[i]; s[i] = s[n - 1 - i]; s[n - 1 - i] = t; } printf("Reverse of hello = %s\n", s); break; }
    case 18: { int a[] = {3, 8, 1, 9, 4}, s = 0; for (int i = 0; i < 5; i++) s += a[i]; printf("Array sum = %d\n", s); break; }
    case 19: { int y = 2024; printf("%d is %sa leap year\n", y, (y % 4 == 0 && y % 100 != 0) || y % 400 == 0 ? "" : "not "); break; }
    case 20: for (int i = 1; i <= 5; i++) printf("7 x %d = %d\n", i, 7 * i); break;
    default: printf("Invalid choice %d (use 1-20, 0 to quit)\n", c);
    }
}

