#include <stdio.h>
#include <string.h>

#define MAXREG 20
#define NCOURSE 3

struct Reg { int sid; char name[20]; int course; };
static struct Reg regs[MAXREG];
static int nreg = 0;
static const char *cname[NCOURSE] = {"C Programming", "Data Structures", "Databases"};
static const int cap[NCOURSE] = {2, 2, 1};   /* seats per exam */

static int seats_used(int c)
{
    int n = 0;
    for (int i = 0; i < nreg; i++) if (regs[i].course == c) n++;
    return n;
}

static void do_register(int sid, const char *name, int c)
{
    if (c < 1 || c > NCOURSE) { printf("Error: exam %d does not exist\n", c); return; }
    for (int i = 0; i < nreg; i++)
        if (regs[i].sid == sid && regs[i].course == c - 1) { printf("Error: %d already registered for %s\n", sid, cname[c - 1]); return; }
    if (seats_used(c - 1) >= cap[c - 1]) { printf("Error: %s is full\n", cname[c - 1]); return; }
    if (nreg >= MAXREG) { printf("Error: system full\n"); return; }
    regs[nreg].sid = sid;
    snprintf(regs[nreg].name, sizeof regs[nreg].name, "%s", name);
    regs[nreg].course = c - 1;
    nreg++;
    printf("Registered %s (%d) for %s\n", name, sid, cname[c - 1]);
}

static void do_cancel(int sid, int c)
{
    for (int i = 0; i < nreg; i++)
        if (regs[i].sid == sid && regs[i].course == c - 1) {
            for (int j = i; j < nreg - 1; j++) regs[j] = regs[j + 1];
            nreg--;
            printf("Cancelled registration of %d for %s\n", sid, cname[c - 1]);
            return;
        }
    printf("Error: no such registration (%d, exam %d)\n", sid, c);
}

int main(void)
{
    char op, name[20];
    int sid, c;
    printf("=== Exam Registration ===\n");
    while (scanf(" %c", &op) == 1 && op != 'Q') {
        if (op == 'R' && scanf("%d %19s %d", &sid, name, &c) == 3) do_register(sid, name, c);
        else if (op == 'C' && scanf("%d %d", &sid, &c) == 2) do_cancel(sid, c);
        else if (op == 'L') {
            for (int k = 0; k < NCOURSE; k++) {
                printf("%s (%d/%d):", cname[k], seats_used(k), cap[k]);
                for (int i = 0; i < nreg; i++) if (regs[i].course == k) printf(" %s", regs[i].name);
                printf("\n");
            }
        } else printf("Unknown command '%c'\n", op);
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

struct Team { char name[20]; int played, won, drawn, lost, gf, ga, pts; };
static struct Team t[8];
static int nt = 0;

static int find(const char *n)
{
    for (int i = 0; i < nt; i++) if (strcmp(t[i].name, n) == 0) return i;
    snprintf(t[nt].name, sizeof t[nt].name, "%s", n);
    return nt++;
}

static void record(int i, int f, int a)
{
    t[i].played++; t[i].gf += f; t[i].ga += a;
    if (f > a) { t[i].won++; t[i].pts += 3; }
    else if (f == a) { t[i].drawn++; t[i].pts += 1; }
    else t[i].lost++;
}

int main(void)
{
    int n, s1, s2;
    char a[20], b[20];
    FILE *fp = fopen("scores.txt", "w");
    if (!fp) return 1;
    printf("Reading match results\n");
    if (scanf("%d", &n) != 1) { fclose(fp); return 1; }
    for (int i = 0; i < n; i++)
        if (scanf("%19s %d %19s %d", a, &s1, b, &s2) == 4) {
            fprintf(fp, "%s %d %s %d\n", a, s1, b, s2);   /* save each match to the file */
            printf("Saved: %s %d - %d %s\n", a, s1, s2, b);
        }
    fclose(fp);

    fp = fopen("scores.txt", "r");
    if (!fp) return 1;
    while (fscanf(fp, "%19s %d %19s %d", a, &s1, b, &s2) == 4) {   /* read them back */
        int i = find(a), j = find(b);
        record(i, s1, s2);
        record(j, s2, s1);
    }
    fclose(fp);
    remove("scores.txt");

    for (int i = 0; i < nt; i++)              /* sort table: points, then goal difference */
        for (int j = i + 1; j < nt; j++)
            if (t[j].pts > t[i].pts || (t[j].pts == t[i].pts && t[j].gf - t[j].ga > t[i].gf - t[i].ga)) {
                struct Team x = t[i]; t[i] = t[j]; t[j] = x;
            }
    printf("\n%-8s %2s %2s %2s %2s %3s %3s %3s\n", "Team", "P", "W", "D", "L", "GF", "GA", "Pts");
    for (int i = 0; i < nt; i++)
        printf("%-8s %2d %2d %2d %2d %3d %3d %3d\n", t[i].name, t[i].played, t[i].won, t[i].drawn, t[i].lost, t[i].gf, t[i].ga, t[i].pts);
    return 0;
}

#include <stdio.h>
