#define DAYS 5
#define PERIODS 6
#define NSUB 6

int main(void)
{
    const char *days[DAYS] = {"Mon", "Tue", "Wed", "Thu", "Fri"};
    const char *sub[NSUB] = {"Maths", "English", "Physics", "Chem", "CS", "PE"};
    int left[NSUB] = {5, 4, 4, 4, 5, 2};          /* periods per week */
    int placed[NSUB] = {0};
    int tt[DAYS][PERIODS];

    for (int d = 0; d < DAYS; d++)
        for (int p = 0; p < PERIODS; p++) tt[d][p] = -1;

    /* fill period by period, rotating the starting subject, one period per subject per day */
    for (int p = 0; p < PERIODS; p++)
        for (int d = 0; d < DAYS; d++)
            for (int k = 0; k < NSUB; k++) {
                int s = (d + p + k) % NSUB, used = 0;
                for (int q = 0; q < p; q++) if (tt[d][q] == s) used = 1;
                if (left[s] > 0 && !used) {
                    tt[d][p] = s; left[s]--; placed[s]++;
                    break;
                }
            }

    printf("Weekly Timetable\n%-5s", "");
    for (int p = 0; p < PERIODS; p++) printf(" P%-7d", p + 1);
    printf("\n");
    for (int d = 0; d < DAYS; d++) {
        printf("%-5s", days[d]);
        for (int p = 0; p < PERIODS; p++) printf(" %-8s", tt[d][p] < 0 ? "Free" : sub[tt[d][p]]);
        printf("\n");
    }
    printf("\nPeriods allotted per subject:\n");
    for (int s = 0; s < NSUB; s++) printf("  %-8s %d (unplaced %d)\n", sub[s], placed[s], left[s]);
    return 0;
}

#include <stdio.h>

struct Item { int id; const char *name; int qty; };

/* items MUST be sorted by id for binary search */
static const struct Item inv[] = {
    {101, "Pen", 120}, {105, "Notebook", 45}, {110, "Stapler", 12}, {123, "Marker", 60},
    {130, "Folder", 33}, {147, "Scissors", 8}, {152, "Glue", 70}, {160, "Tape", 25}
};
#define N ((int)(sizeof inv / sizeof inv[0]))

static int bsearch_id(int key, int *steps)
{
    int lo = 0, hi = N - 1;
    *steps = 0;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        (*steps)++;
        if (inv[mid].id == key) return mid;
        if (inv[mid].id < key) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main(void)
{
    int key, steps, sorted = 1;
    for (int i = 1; i < N; i++) if (inv[i - 1].id >= inv[i].id) sorted = 0;
    printf("Inventory sorted: %s\n", sorted ? "yes" : "NO");
    printf("Enter item ids to search (0 to stop):\n");
    while (scanf("%d", &key) == 1 && key != 0) {
        int pos = bsearch_id(key, &steps);
        if (pos >= 0) printf("Item %d: %s, qty %d (found at index %d in %d step(s))\n", key, inv[pos].name, inv[pos].qty, pos, steps);
        else printf("Item %d: not found (%d step(s))\n", key, steps);
    }
    return 0;
}

#include <stdio.h>

#define LOAN_DAYS 14
#define RATE1 2      /* Rs per day, first 7 late days */
#define RATE2 5      /* Rs per day after that */

static int fine_for(int days_kept)
{
    int late = days_kept - LOAN_DAYS;
    if (late <= 0) return 0;
    if (late <= 7) return late * RATE1;
    return 7 * RATE1 + (late - 7) * RATE2;
}

int main(void)
{
    int n, days, book, total = 0, lines = 0;
    char member[20];
    FILE *log = fopen("fines.log", "w");
    if (!log) return 1;
    if (scanf("%d", &n) != 1) { fclose(log); return 1; }
    for (int i = 0; i < n; i++) {
        if (scanf("%19s %d %d", member, &book, &days) != 3) break;
        int f = fine_for(days);
        fprintf(log, "%s book=%d kept=%d fine=%d\n", member, book, days, f);   /* log each return */
    }
    fclose(log);

    log = fopen("fines.log", "r");
    if (!log) return 1;
    printf("Transaction log:\n");
    while (fscanf(log, "%19s book=%d kept=%d fine=%d", member, &book, &days, &n) == 4) {
        printf("%2d. %-6s book %d kept %2d days -> fine Rs %d\n", ++lines, member, book, days, n);
        total += n;
    }
    fclose(log);
    remove("fines.log");
    printf("Transactions: %d, total fines collected: Rs %d\n", lines, total);
    return 0;
}

