            else { st[n].id = id; snprintf(st[n].name, sizeof st[n].name, "%s", name); st[n].marks = m; n++; printf("Added %s\n", name); }
            break;
        case 2:
            if (scanf("%d", &id) != 1) return 0;
            i = find(id);
            if (i < 0) printf("Search: id %d not found\n", id);
            else printf("Found: %d %s %d\n", st[i].id, st[i].name, st[i].marks);
            break;
        case 3:
            if (scanf("%d %d", &id, &m) != 2) return 0;
            i = find(id);
            if (i < 0) printf("Update: id %d not found\n", id);
            else { st[i].marks = m; printf("Updated %s marks to %d\n", st[i].name, m); }
            break;
        case 4:
            if (scanf("%d", &id) != 1) return 0;
            i = find(id);
            if (i < 0) printf("Delete: id %d not found\n", id);
            else { for (; i < n - 1; i++) st[i] = st[i + 1]; n--; printf("Deleted id %d\n", id); }
            break;
        case 5:
            printf("%-4s %-10s %s\n", "ID", "Name", "Marks");
            for (i = 0; i < n; i++) printf("%-4d %-10s %d\n", st[i].id, st[i].name, st[i].marks);
            break;
        case 6: save(); break;
        default: printf("Invalid menu choice\n");
        }
    }
    return 0;
}

#include <stdio.h>

struct Employee { int id; char name[20]; char dept[15]; double salary; };

/* write all employees to a binary file */
static int save_all(const char *fn, const struct Employee *e, int n)
{
    FILE *fp = fopen(fn, "wb");
    if (!fp) return 0;
    size_t w = fwrite(e, sizeof *e, (size_t)n, fp);
    fclose(fp);
    return (int)w;
}

/* read employees back from the binary file */
static int load_all(const char *fn, struct Employee *e, int max)
{
    FILE *fp = fopen(fn, "rb");
    if (!fp) return 0;
    size_t r = fread(e, sizeof *e, (size_t)max, fp);
    fclose(fp);
    return (int)r;
}

static void give_raise(struct Employee *e, double percent) { e->salary += e->salary * percent / 100.0; }

int main(void)
{
    struct Employee in[10], out[10];
    int n, m;
    double total = 0;
    if (scanf("%d", &n) != 1 || n < 1 || n > 10) { printf("Invalid count\n"); return 0; }
    for (int i = 0; i < n; i++)
        if (scanf("%d %19s %14s %lf", &in[i].id, in[i].name, in[i].dept, &in[i].salary) != 4) return 0;

    printf("Saved %d employee(s) to file\n", save_all("emp.dat", in, n));
    m = load_all("emp.dat", out, 10);
    remove("emp.dat");
    printf("Loaded %d employee(s) from file\n\n", m);

    for (int i = 0; i < m; i++)
        if (out[i].dept[0] == 'I') give_raise(&out[i], 10);   /* 10 percent raise for IT */

    printf("%-4s %-8s %-6s %10s\n", "ID", "Name", "Dept", "Salary");
    for (int i = 0; i < m; i++) {
        printf("%-4d %-8s %-6s %10.2f\n", out[i].id, out[i].name, out[i].dept, out[i].salary);
        total += out[i].salary;
    }
    printf("Payroll total: %.2f, average: %.2f\n", total, total / m);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define NBOOK 5
#define NMEM 3
#define LIMIT 2

static const char *title[NBOOK] = {"C Primer", "Algorithms", "Databases", "Networks", "Compilers"};
static int holder[NBOOK];          /* 0 = on shelf, otherwise member id */
static int issued[NMEM + 1];       /* books currently held per member */

static void issue(int m, int b)
{
    if (m < 1 || m > NMEM) { printf("Error: member %d is invalid (1-%d)\n", m, NMEM); return; }
    if (b < 1 || b > NBOOK) { printf("Error: book %d is invalid (1-%d)\n", b, NBOOK); return; }
    if (holder[b - 1] != 0) { printf("Error: '%s' is already issued to member %d\n", title[b - 1], holder[b - 1]); return; }
    if (issued[m] >= LIMIT) { printf("Error: member %d reached the limit of %d books\n", m, LIMIT); return; }
    holder[b - 1] = m; issued[m]++;
    printf("Issued '%s' to member %d\n", title[b - 1], m);
}

static void giveback(int m, int b)
{
    if (m < 1 || m > NMEM || b < 1 || b > NBOOK) { printf("Error: invalid member or book number\n"); return; }
    if (holder[b - 1] != m) { printf("Error: member %d does not hold '%s'\n", m, title[b - 1]); return; }
    holder[b - 1] = 0; issued[m]--;
    printf("Returned '%s' from member %d\n", title[b - 1], m);
}

int main(void)
{
    char op;
    int m, b;
    while (scanf(" %c", &op) == 1 && op != 'Q') {
        if (op == 'I' && scanf("%d %d", &m, &b) == 2) issue(m, b);
        else if (op == 'R' && scanf("%d %d", &m, &b) == 2) giveback(m, b);
        else if (op == 'S') {
            printf("--- Status ---\n");
            for (int i = 0; i < NBOOK; i++) {
                if (holder[i]) printf("%-11s issued to member %d\n", title[i], holder[i]);
                else printf("%-11s available\n", title[i]);
            }
        } else printf("Error: bad command '%c' or missing numbers\n", op);
    }
    return 0;
}

#include <stdio.h>

#define N 5
#define LOW 10

static const char *name[N] = {"Bolts", "Nuts", "Washers", "Screws", "Nails"};
static const int start[N] = {50, 8, 25, 12, 30};

static void report(const int *q)
{
    int low = 0;
    printf("  Stock:");
    for (int i = 0; i < N; i++) printf(" %s=%d", name[i], q[i]);
    printf("\n  Low-stock (<= %d):", LOW);
    for (int i = 0; i < N; i++) if (q[i] <= LOW) { printf(" %s", name[i]); low++; }
    if (!low) printf(" none");
    printf("\n");
}

int main(void)
{
    int tests, q[N];
    if (scanf("%d", &tests) != 1) return 0;
    for (int t = 1; t <= tests; t++) {
        int k, idx, delta;
        for (int i = 0; i < N; i++) q[i] = start[i];     /* fresh stock for each test */
        if (scanf("%d", &k) != 1) return 0;
        printf("Test %d (%d update(s))\n", t, k);
        for (int u = 0; u < k; u++) {
            if (scanf("%d %d", &idx, &delta) != 2) return 0;
            if (idx < 0 || idx >= N) { printf("  rejected: item %d does not exist\n", idx); continue; }
            if (q[idx] + delta < 0) { printf("  rejected: only %d %s in stock, cannot change by %d\n", q[idx], name[idx], delta); continue; }
            q[idx] += delta;
            printf("  %s %+d -> %d\n", name[idx], delta, q[idx]);
        }
        report(q);
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

#define NACC 3
#define MAXTX 40

struct Account { int no; char owner[12]; int balance; };
struct Tx { int acc; char type[10]; int amount; int after; };

static struct Account acc[NACC] = {{1001, "Asha", 5000}, {1002, "Ravi", 1200}, {1003, "Meena", 0}};
static struct Tx tx[MAXTX];
static int ntx = 0;

static int find(int no)
{
    for (int i = 0; i < NACC; i++) if (acc[i].no == no) return i;
    return -1;
}

static void log_tx(int i, const char *type, int amt)
{
    if (ntx >= MAXTX) return;
    tx[ntx].acc = acc[i].no;
    snprintf(tx[ntx].type, sizeof tx[ntx].type, "%s", type);
    tx[ntx].amount = amt;
    tx[ntx].after = acc[i].balance;
    ntx++;
}

int main(void)
{
    char op;
    int a, b, amt;
    while (scanf(" %c", &op) == 1 && op != 'Q') {
        if (op == 'D' && scanf("%d %d", &a, &amt) == 2) {            /* deposit */
            int i = find(a);
            if (i < 0 || amt <= 0) printf("Deposit failed: bad account or amount\n");
            else { acc[i].balance += amt; log_tx(i, "DEPOSIT", amt); printf("Deposited %d into %d, balance %d\n", amt, a, acc[i].balance); }
        } else if (op == 'W' && scanf("%d %d", &a, &amt) == 2) {     /* withdraw */
            int i = find(a);
            if (i < 0 || amt <= 0) printf("Withdraw failed: bad account or amount\n");
            else if (acc[i].balance < amt) printf("Withdraw failed: insufficient funds in %d (balance %d)\n", a, acc[i].balance);
            else { acc[i].balance -= amt; log_tx(i, "WITHDRAW", amt); printf("Withdrew %d from %d, balance %d\n", amt, a, acc[i].balance); }
        } else if (op == 'T' && scanf("%d %d %d", &a, &b, &amt) == 3) {   /* transfer = withdraw + deposit */
            int i = find(a), j = find(b);
            if (i < 0 || j < 0 || amt <= 0 || i == j) printf("Transfer failed: bad accounts or amount\n");
            else if (acc[i].balance < amt) printf("Transfer failed: insufficient funds\n");
            else {
                acc[i].balance -= amt; acc[j].balance += amt;
                log_tx(i, "XFER-OUT", amt); log_tx(j, "XFER-IN", amt);
                printf("Transferred %d from %d to %d\n", amt, a, b);
            }
        } else if (op == 'H' && scanf("%d", &a) == 1) {              /* history */
            printf("History for %d:\n", a);
            for (int k = 0; k < ntx; k++)
                if (tx[k].acc == a) printf("  %-9s %5d  balance %5d\n", tx[k].type, tx[k].amount, tx[k].after);
        } else printf("Bad command\n");
    }
    printf("Final balances:\n");
    for (int i = 0; i < NACC; i++) printf("  %d %-6s %d\n", acc[i].no, acc[i].owner, acc[i].balance);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define SEATS 10

static char who[SEATS + 1][16];     /* index 1..SEATS, empty string = free */

static void book(int s, const char *name)
{
    if (s < 1 || s > SEATS) { printf("Seat %d is out of range (1-%d)\n", s, SEATS); return; }
    if (who[s][0]) { printf("Seat %d is already booked by %s\n", s, who[s]); return; }
    snprintf(who[s], sizeof who[s], "%s", name);
    printf("Seat %d booked for %s\n", s, name);
}

static void cancel(int s)
{
    if (s < 1 || s > SEATS) { printf("Seat %d is out of range (1-%d)\n", s, SEATS); return; }
    if (!who[s][0]) { printf("Seat %d is not booked, nothing to cancel\n", s); return; }
    printf("Cancelled seat %d (%s)\n", s, who[s]);
    who[s][0] = '\0';
}

static void show(void)
{
    int free_n = 0;
    printf("Seat map: ");
    for (int i = 1; i <= SEATS; i++) {
        printf("[%d%c]", i, who[i][0] ? 'X' : '_');
        if (!who[i][0]) free_n++;
    }
    printf("\nFree seats: %d, booked: %d\n", free_n, SEATS - free_n);
}

int main(void)
{
    char op, name[16];
    int s;
    while (scanf(" %c", &op) == 1 && op != 'Q') {
        if (op == 'B' && scanf("%d %15s", &s, name) == 2) book(s, name);
        else if (op == 'C' && scanf("%d", &s) == 1) cancel(s);
        else if (op == 'S') show();
        else printf("Bad command\n");
    }
    return 0;
}

#include <stdio.h>

#define MAXP 10
#define SLOTS 6

struct Patient { int id; char name[16]; int age; };
static struct Patient pat[MAXP];
static int np = 0;
static int slot[SLOTS];                                   /* patient id, 0 = free */
static const char *time_of[SLOTS] = {"09:00", "10:00", "11:00", "12:00", "14:00", "15:00"};

static int find(int id)
{
    for (int i = 0; i < np; i++) if (pat[i].id == id) return i;
    return -1;
}

int main(void)
{
    int ch, id, s;
    printf("1 Add patient  2 Book  3 Cancel  4 Patients  5 Schedule  0 Exit\n");
    while (scanf("%d", &ch) == 1 && ch != 0) {
        if (ch == 1) {
            struct Patient p;
            if (scanf("%d %15s %d", &p.id, p.name, &p.age) != 3) break;
            if (np >= MAXP || find(p.id) >= 0 || p.age <= 0) printf("Cannot add patient %d\n", p.id);
            else { pat[np++] = p; printf("Patient %s registered\n", p.name); }
        } else if (ch == 2) {
            if (scanf("%d %d", &id, &s) != 2) break;
            if (find(id) < 0) printf("Unknown patient %d\n", id);
            else if (s < 1 || s > SLOTS) printf("Slot %d invalid\n", s);
            else if (slot[s - 1]) printf("Slot %s is taken\n", time_of[s - 1]);
            else { slot[s - 1] = id; printf("Booked %s for patient %d\n", time_of[s - 1], id); }
        } else if (ch == 3) {
            if (scanf("%d", &s) != 1) break;
            if (s < 1 || s > SLOTS || !slot[s - 1]) printf("Nothing to cancel in slot %d\n", s);
            else { printf("Cancelled %s (patient %d)\n", time_of[s - 1], slot[s - 1]); slot[s - 1] = 0; }
        } else if (ch == 4) {
            for (int i = 0; i < np; i++) printf("  #%d %-8s age %d\n", pat[i].id, pat[i].name, pat[i].age);
        } else if (ch == 5) {
            for (int i = 0; i < SLOTS; i++) {
                printf("  %s ", time_of[i]);
                if (slot[i]) printf("%s\n", pat[find(slot[i])].name);
                else printf("free\n");
            }
        } else printf("Invalid choice\n");
    }
    return 0;
}

