#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* The text buffer is a char pointer that grows as lines are appended. */
static void append(char **buf, const char *line)
{
    size_t old = *buf ? strlen(*buf) : 0;
    char *p = realloc(*buf, old + strlen(line) + 2);
    if (!p) return;
    *buf = p;
    strcpy(*buf + old, line);
    strcat(*buf + old, "\n");
}

static void display(const char *buf)
{
    const char *p = buf;
    int no = 1;
    while (p && *p) {                     /* walk with a pointer, line by line */
        const char *e = strchr(p, '\n');
        printf("%2d| %.*s\n", no++, (int)(e - p), p);
        p = e + 1;
    }
}

int main(void)
{
    char *buf = NULL;
    char cmd[10], line[100];
    while (scanf("%9s", cmd) == 1) {
        if (strcmp(cmd, "append") == 0) {
            if (scanf(" %99[^\n]", line) == 1) { append(&buf, line); printf("[appended]\n"); }
        } else if (strcmp(cmd, "display") == 0) {
            printf("--- document ---\n");
            display(buf);
            printf("----------------\n");
        } else if (strcmp(cmd, "save") == 0) {
            FILE *f = fopen("doc.txt", "w");
            if (f) { if (buf) fputs(buf, f); fclose(f); }
            printf("[saved]\n");
        } else if (strcmp(cmd, "quit") == 0) break;
        else printf("unknown command %s\n", cmd);
    }
    /* check the saved file */
    FILE *f = fopen("doc.txt", "r");
    if (f) {
        int lines = 0, ch;
        while ((ch = fgetc(f)) != EOF) if (ch == '\n') lines++;
        fclose(f);
        printf("File doc.txt holds %d line(s)\n", lines);
        remove("doc.txt");
    }
    free(buf);
    return 0;
}

#include <stdio.h>
