#define ROWS 10
#define COLS 3

int main(void)
{
    /* sample CSV is written to a file first, then read back */
    FILE *f = fopen("data.csv", "w");
    if (!f) return 1;
    fputs("name,math,science\nAsha,82,90\nRavi,67,75\nMeena,91,88\nKiran,55,60\n", f);
    fclose(f);

    f = fopen("data.csv", "r");
    if (!f) return 1;
    double v[COLS][ROWS];                  /* one array per numeric column */
    char head[COLS + 1][20], line[100];
    int n = 0;
    if (fgets(line, sizeof line, f)) {
        char *t = strtok(line, ",\n");
        for (int c = 0; t && c <= COLS; c++, t = strtok(NULL, ",\n")) strcpy(head[c], t);
    }
    while (n < ROWS && fgets(line, sizeof line, f)) {
        char *t = strtok(line, ",\n");     /* skip the name column */
        for (int c = 0; c < COLS && t; c++) {
            t = strtok(NULL, ",\n");
            if (t) v[c][n] = atof(t);
        }
        n++;
    }
    fclose(f);
    remove("data.csv");
    printf("Rows read: %d\n", n);
    printf("%-9s %6s %6s %6s %6s\n", "Column", "Sum", "Mean", "Min", "Max");
    for (int c = 0; c < 2; c++) {
        double sum = 0, mn = v[c][0], mx = v[c][0];
        for (int i = 0; i < n; i++) {
            sum += v[c][i];
            if (v[c][i] < mn) mn = v[c][i];
            if (v[c][i] > mx) mx = v[c][i];
        }
        printf("%-9s %6.1f %6.2f %6.1f %6.1f\n", head[c + 1], sum, sum / n, mn, mx);
    }
    return 0;
}

