#include <stdio.h>
#include <ctype.h>

/* Recursive descent: expr = term {(+|-) term}; term = factor {(*|/) factor};
   factor = number | ( expr ) | -factor */
static const char *p;
static int err;
static double expr(void);

static void skip(void) { while (*p == ' ') p++; }

static double factor(void)
{
    skip();
    if (*p == '-') { p++; return -factor(); }
    if (*p == '(') {
        p++;
        double v = expr();
        skip();
        if (*p == ')') p++; else err = 1;
        return v;
    }
    if (isdigit((unsigned char)*p) || *p == '.') {
        double v = 0, d = 10;
        while (isdigit((unsigned char)*p)) v = v * 10 + (*p++ - '0');
        if (*p == '.') { p++; while (isdigit((unsigned char)*p)) { v += (*p++ - '0') / d; d *= 10; } }
        return v;
    }
    err = 1;
    return 0;
}

static double term(void)
{
    double v = factor();
    for (;;) {
        skip();
        if (*p == '*') { p++; v *= factor(); }
        else if (*p == '/') {
            p++;
            double d = factor();
            if (d == 0) { err = 2; return 0; }
            v /= d;
        } else return v;
    }
}

static double expr(void)
{
    double v = term();
    for (;;) {
        skip();
        if (*p == '+') { p++; v += term(); }
        else if (*p == '-') { p++; v -= term(); }
        else return v;
    }
}

int main(void)
{
    char line[100];
    while (fgets(line, sizeof line, stdin)) {        /* many expressions */
        int len = 0;
        while (line[len] && line[len] != '\n') len++;
        line[len] = '\0';
        if (len == 0) continue;
        p = line; err = 0;
        double v = expr();
        skip();
        if (*p != '\0') err = err ? err : 1;
        if (err == 2) printf("%s = error: division by zero\n", line);
        else if (err) printf("%s = error: bad expression\n", line);
        else printf("%s = %g\n", line, v);
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

#define R 7
#define C 9

/* '#' wall, '.' open, 'S' start, 'E' exit */
static char maze[R][C + 1] = {
    "#########",
    "#S..#...#",
    "#.#.#.#.#",
    "#.#...#.#",
    "#.#####.#",
    "#......E#",
    "#########"
};

int main(void)
{
    int dist[R][C], px[R * C], py[R * C];        /* BFS distances and parents */
    int qx[R * C], qy[R * C], head = 0, tail = 0;
    int sr = 0, sc = 0, er = 0, ec = 0;
    memset(dist, -1, sizeof dist);
    for (int r = 0; r < R; r++)
        for (int c = 0; c < C; c++) {
            if (maze[r][c] == 'S') { sr = r; sc = c; }
            if (maze[r][c] == 'E') { er = r; ec = c; }
        }
    printf("Maze (S=start, E=exit, #=wall):\n");
    for (int r = 0; r < R; r++) printf("  %s\n", maze[r]);

    dist[sr][sc] = 0; qx[tail] = sr; qy[tail++] = sc;
    int dr[4] = {-1, 1, 0, 0}, dc[4] = {0, 0, -1, 1};
    while (head < tail) {                         /* breadth-first search */
        int r = qx[head], c = qy[head++];
        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
            if (maze[nr][nc] == '#' || dist[nr][nc] != -1) continue;
            dist[nr][nc] = dist[r][c] + 1;
            px[nr * C + nc] = r; py[nr * C + nc] = c;
            qx[tail] = nr; qy[tail++] = nc;
        }
    }
    if (dist[er][ec] < 0) { printf("No path found\n"); return 0; }
    printf("Shortest path length: %d steps\n", dist[er][ec]);
    int r = er, c = ec;
    while (!(r == sr && c == sc)) {               /* walk back, marking path */
        int pr = px[r * C + c], pc = py[r * C + c];
        if (maze[r][c] == '.') maze[r][c] = '*';
        r = pr; c = pc;
    }
    printf("Solved maze (* = path):\n");
    for (int i = 0; i < R; i++) printf("  %s\n", maze[i]);
    return 0;
}

#include <stdio.h>

#define N 6
#define INF 1000000

static const char *city[N] = {"A", "B", "C", "D", "E", "F"};

int main(void)
{
    int w[N][N] = {{0}};
    int edges, i;
    printf("Enter number of roads, then 'from to cost' for each:\n");
    if (scanf("%d", &edges) != 1 || edges < 0) { printf("Invalid road count\n"); return 0; }
    for (i = 0; i < edges; i++) {
        int a, b, c;
        if (scanf("%d %d %d", &a, &b, &c) != 3) { printf("Invalid road line\n"); return 0; }
        if (a < 0 || a >= N || b < 0 || b >= N || c <= 0) {      /* validate */
            printf("Road %d ignored: invalid values (%d %d %d)\n", i + 1, a, b, c);
            continue;
        }
        w[a][b] = w[b][a] = c;
    }
    int src, dst;
    if (scanf("%d %d", &src, &dst) != 2 || src < 0 || src >= N || dst < 0 || dst >= N) {
        printf("Invalid source or destination\n");
        return 0;
    }
    int dist[N], prev[N], done[N];
    for (i = 0; i < N; i++) { dist[i] = INF; prev[i] = -1; done[i] = 0; }
    dist[src] = 0;
    for (int step = 0; step < N; step++) {             /* Dijkstra */
        int u = -1;
        for (i = 0; i < N; i++) if (!done[i] && (u < 0 || dist[i] < dist[u])) u = i;
        if (u < 0 || dist[u] == INF) break;
        done[u] = 1;
        for (int v = 0; v < N; v++)
            if (w[u][v] && dist[u] + w[u][v] < dist[v]) { dist[v] = dist[u] + w[u][v]; prev[v] = u; }
    }
    printf("Shortest route from %s to %s: ", city[src], city[dst]);
    if (dist[dst] == INF) { printf("no route\n"); return 0; }
    int path[N], len = 0;
    for (int v = dst; v != -1; v = prev[v]) path[len++] = v;
    for (i = len - 1; i >= 0; i--) printf("%s%s", city[path[i]], i ? " -> " : "");
    printf("\nTotal cost: %d\n", dist[dst]);
    printf("Distances from %s:", city[src]);
    for (i = 0; i < N; i++) {
        if (dist[i] == INF) printf(" %s=inf", city[i]);
        else printf(" %s=%d", city[i], dist[i]);
    }
    printf("\n");
    return 0;
}

