int main(void)
{
    int A = 2, B = 3, C = 4, D = 5, E = 6, F = 7, G = 8;
    int r;

    /* a. A+B*C+(D*E)+F*G : * first, then + left to right */
    r = A + B * C + (D * E) + F * G;
    printf("a. A+B*C+(D*E)+F*G = %d\n", r);

    /* b. A/B*C-B+A*D/3 : integer division, left to right */
    r = A / B * C - B + A * D / 3;
    printf("b. A/B*C-B+A*D/3   = %d\n", r);

    /* c. A+++B---A is tokenised as (A++) + (B--) - A */
    int a = 5, b = 8;
    int t1 = a;  a++;                    /* A++ gives old A */
    int t2 = b;  b--;                    /* B-- gives old B */
    r = t1 + t2 - a;                     /* A is now 6 */
    printf("c. A+++B---A with A=5,B=8: (5)+(8)-6 = %d, A=%d, B=%d\n", r, a, b);

    /* d. J=(i++)+(++i) modifies i twice without a sequence point:
          undefined behaviour, so show two well-defined readings */
    int i = 5, j;
    j = i; i++;                          /* reading 1: i++ first */
    j = j + (++i);
    printf("d. reading 1: J=%d, i=%d\n", j, i);
    i = 5;
    int pre = ++i;                       /* reading 2: ++i first */
    j = pre + i++;
    printf("d. reading 2: J=%d, i=%d\n", j, i);
    printf("   (the real expression is undefined/compiler dependent)\n");
    return 0;
}

