int main(void)
{
    char bin[64], ones[64], twos[64];
    int len, i, carry;
    printf("Enter a binary number: ");
    if (scanf("%60s", bin) != 1) return 1;
    len = (int)strlen(bin);
    /* Step 1: 1's complement - flip every bit */
    for (i = 0; i < len; i++) ones[i] = (bin[i] == '0') ? '1' : '0';
    ones[len] = '\0';
    /* Step 2: add 1 to the 1's complement */
    strcpy(twos, ones);
    carry = 1;
    for (i = len - 1; i >= 0; i--) {
        if (twos[i] == '1' && carry == 1) twos[i] = '0';
        else if (twos[i] == '0' && carry == 1) { twos[i] = '1'; carry = 0; }
    }
    printf("Binary number  : %s\n", bin);
    printf("1's complement : %s\n", ones);
    printf("2's complement : %s\n", twos);
    return 0;
}

