/* Reverse WITHOUT built-in functions */
void reverse_manual(const char *src, char *dst)
{
    int len = 0, i;
    while (src[len] != '\0') len++;
    for (i = 0; i < len; i++) dst[i] = src[len - 1 - i];
    dst[len] = '\0';
}

