/* n! as a function */
long fact(int n)
{
    long f = 1;
    int i;
    for (i = 2; i <= n; i++) f *= i;
    return f;
}

/* nCr = n! / (r! * (n-r)!) */
long ncr(int n, int r)
{
    return fact(n) / (fact(r) * fact(n - r));
}

