/* differential equation dy/dx = f(x, y) */
double f(double x, double y)
{
    return x + y;
}

/* Euler's method: y(n+1) = y(n) + h * f(x(n), y(n)) */
double euler(double x0, double y0, double h, double xn)
{
    double x = x0, y = y0;
    int step = 0;
    printf("%5s %8s %10s\n", "Step", "x", "y");
    printf("%5d %8.2f %10.5f\n", step, x, y);
    while (step < 100 && x < xn - 1e-9) {
        y = y + h * f(x, y);
        x = x + h;
        step++;
        printf("%5d %8.2f %10.5f\n", step, x, y);
    }
    return y;
}

