#include <stdio.h>

int gcd(int a, int b)
{
    if (b == 0) return a;
    return gcd(b, a % b);                 /* Euclid's algorithm */
}

/* recursive lcm: keep adding the larger number until divisible by the other */
int lcm(int a, int b, int multiple)
{
    if (multiple % b == 0) return multiple;
    return lcm(a, b, multiple + a);
}

