/* sum of series 1 + 1/2 + 1/3 + ... + 1/n */
double series(int n)
{
    if (n == 0) return 0.0;
    return 1.0 / n + series(n - 1);
}

/* sum of natural numbers 1 + 2 + ... + n */
int sum_natural(int n)
{
    if (n == 0) return 0;
    return n + sum_natural(n - 1);
}

