#include <stdio.h>

struct byte_bits {
    unsigned int value : 8;               /* 8-bit field */
};

static void print_bits(unsigned int v)
{
    int i;
    for (i = 7; i >= 0; i--) printf("%u", (v >> i) & 1u);
}

int main(void)
{
    struct byte_bits b;
    unsigned int v, n = 2;
    b.value = 0xB5;                       /* 10110101 */
    printf("Original      : "); print_bits(b.value); printf("  (%u)\n", (unsigned)b.value);

    v = b.value;
    b.value = (v << n) & 0xFFu;           /* shift left, extra bits are lost */
    printf("Shift left  %u : ", n); print_bits(b.value); printf("  (%u)\n", (unsigned)b.value);

    b.value = 0xB5;
    v = b.value;
    b.value = (v >> n) & 0xFFu;           /* shift right */
    printf("Shift right %u : ", n); print_bits(b.value); printf("  (%u)\n", (unsigned)b.value);

    b.value = 0xB5;
    v = b.value;
    b.value = ((v << n) | (v >> (8 - n))) & 0xFFu;   /* rotate left */
    printf("Rotate left %u : ", n); print_bits(b.value); printf("  (%u)\n", (unsigned)b.value);

    b.value = 0xB5;
    v = b.value;
    b.value = ((v >> n) | (v << (8 - n))) & 0xFFu;   /* rotate right */
    printf("Rotate right %u: ", n); print_bits(b.value); printf("  (%u)\n", (unsigned)b.value);
    return 0;
}

