    if (fp == NULL) return 1;
    n = fwrite(out, sizeof(struct student), 2, fp);   /* write 2 records */
    fclose(fp);
    printf("Records written: %zu\n", n);

    fp = fopen("lab_data.bin", "rb");
    if (fp == NULL) return 1;
    n = fread(in, sizeof(struct student), 2, fp);     /* read them back */
    fclose(fp);
    printf("Records read   : %zu\n", n);
    for (i = 0; i < n; i++)
        printf("  Roll=%d Name=%s Marks=%.1f\n", in[i].roll, in[i].name, in[i].marks);
    remove("lab_data.bin");
    return 0;
}

