#include <stdio.h>

/* Usage: prog file1 file2 file3  (file3 = file1 followed by file2) */
static int append(FILE *out, const char *name)
{
    FILE *in = fopen(name, "r");
    int ch;
    if (in == NULL) { printf("Cannot open %s\n", name); return 1; }
    while ((ch = fgetc(in)) != EOF) fputc(ch, out);
    fclose(in);
    return 0;
}

int main(int argc, char *argv[])
{
    const char *f1 = "file1.txt", *f2 = "file2.txt", *f3 = "merged.txt";
    int defaults = (argc < 4), ch;
    FILE *fp, *out;

    if (defaults) {
        printf("Fewer than 3 arguments, using default files: file1.txt file2.txt merged.txt\n");
        fp = fopen(f1, "w");
        if (fp == NULL) return 1;
        fputs("Contents of the first file.\n", fp);
        fclose(fp);
        fp = fopen(f2, "w");
        if (fp == NULL) return 1;
        fputs("Contents of the second file.\n", fp);
        fclose(fp);
    } else {
        f1 = argv[1]; f2 = argv[2]; f3 = argv[3];
    }

    out = fopen(f3, "w");
    if (out == NULL) return 1;
    if (append(out, f1) || append(out, f2)) { fclose(out); return 1; }
    fclose(out);
    printf("Merged %s and %s into %s\n", f1, f2, f3);

    fp = fopen(f3, "r");
    if (fp == NULL) return 1;
    printf("Merged file contents:\n");
    while ((ch = fgetc(fp)) != EOF) putchar(ch);
    fclose(fp);

    if (defaults) { remove(f1); remove(f2); remove(f3); }
    return 0;
}

