#include <stdio.h>

int main(int argc, char *argv[])
{
    const char *name = "last.txt";
    long n = 10, size, start;
    int ch, made = 0;
    FILE *fp;

    if (argc >= 3) {                      /* usage: prog filename n */
        name = argv[1];
        if (sscanf(argv[2], "%ld", &n) != 1 || n < 0) n = 10;
    } else {
        printf("No arguments, using defaults: file last.txt, n = 10\n");
        fp = fopen(name, "w");
        if (fp == NULL) return 1;
        fputs("The quick brown fox jumps over the lazy dog.", fp);
        fclose(fp);
        made = 1;
    }

    fp = fopen(name, "r");
    if (fp == NULL) { printf("Cannot open %s\n", name); return 1; }
    fseek(fp, 0L, SEEK_END);              /* go to end to find the size */
    size = ftell(fp);
    start = (n > size) ? 0 : size - n;
    fseek(fp, start, SEEK_SET);           /* move back n characters */
    printf("Last %ld characters: \"", n);
    while ((ch = fgetc(fp)) != EOF) putchar(ch);
    printf("\"\n");
    fclose(fp);
    if (made) remove(name);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int A, B, C, D, E, F, G;
    int t1, t2, t3, t4, t5, result;
    printf("Enter A B C D E F G: ");
    if (scanf("%d %d %d %d %d %d %d", &A, &B, &C, &D, &E, &F, &G) != 7) return 1;
    printf("\nExpression: A + B*C + (D*E) + F*G\n");
    t1 = B * C;                           /* * has higher precedence than + */
    printf("Step 1: B*C       = %d*%d = %d\n", B, C, t1);
    t2 = D * E;                           /* brackets first, same here */
    printf("Step 2: (D*E)     = %d*%d = %d\n", D, E, t2);
    t3 = F * G;
    printf("Step 3: F*G       = %d*%d = %d\n", F, G, t3);
    t4 = A + t1;                          /* + is evaluated left to right */
    printf("Step 4: A + B*C   = %d + %d = %d\n", A, t1, t4);
    t5 = t4 + t2;
    printf("Step 5: + (D*E)   = %d + %d = %d\n", t4, t2, t5);
    result = t5 + t3;
    printf("Step 6: + F*G     = %d + %d = %d\n", t5, t3, result);
    printf("\nResult = %d\n", result);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int A, B, C, D;
    int t1, t2, t3, t4, t5, result;
    printf("Enter A B C D: ");
    if (scanf("%d %d %d %d", &A, &B, &C, &D) != 4) return 1;
    printf("\nExpression: A/B*C - B + A*D/3\n");
    printf("Rule: / and * have equal precedence and go left to right (integer division).\n\n");
    t1 = A / B;
    printf("Step 1: A/B     = %d/%d = %d\n", A, B, t1);
    t2 = t1 * C;
    printf("Step 2: (A/B)*C = %d*%d = %d\n", t1, C, t2);
    t3 = A * D;
    printf("Step 3: A*D     = %d*%d = %d\n", A, D, t3);
    t4 = t3 / 3;
    printf("Step 4: (A*D)/3 = %d/3 = %d\n", t3, t4);
    t5 = t2 - B;
    printf("Step 5: %d - B  = %d - %d = %d\n", t2, t2, B, t5);
    result = t5 + t4;
    printf("Step 6: %d + %d = %d\n", t5, t4, result);
    printf("\nResult = %d\n", result);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int A = 5, B = 3, t1, t2, result;
    printf("Initial: A = %d, B = %d\n", A, B);
    printf("Expression A+++B---A is parsed (longest match) as (A++) + (B--) - A\n\n");

    /* Evaluated step by step to avoid unsequenced access to A */
    t1 = A;  A = A + 1;                   /* post-increment: use old value, then add 1 */
    printf("Step 1: A++ gives %d, A becomes %d\n", t1, A);
    t2 = B;  B = B - 1;                   /* post-decrement */
    printf("Step 2: B-- gives %d, B becomes %d\n", t2, B);
    result = t1 + t2 - A;                 /* last A is the updated value here */
    printf("Step 3: %d + %d - %d = %d\n", t1, t2, A, result);

    printf("\nFinal: result = %d, A = %d, B = %d\n", result, A, B);
    printf("Note: the original one-line form reads and modifies A in the same\n");
    printf("expression without sequencing, so its value is compiler dependent.\n");
    return 0;
}

#include <stdio.h>

int main(void)
{
    int i, a, b, J;
    printf("Expression: J = (i++) + (++i), with i = 5\n\n");

    /* Order 1: left operand first */
    i = 5;
    a = i; i = i + 1;                     /* i++ : value 5, i becomes 6 */
    i = i + 1; b = i;                     /* ++i : i becomes 7, value 7 */
    J = a + b;
    printf("Order 1 (left first)  : i++ = %d, ++i = %d, J = %d, i = %d\n", a, b, J, i);

    /* Order 2: right operand first */
    i = 5;
    i = i + 1; b = i;                     /* ++i : value 6 */
    a = i; i = i + 1;                     /* i++ : value 6, i becomes 7 */
    J = a + b;
    printf("Order 2 (right first) : ++i = %d, i++ = %d, J = %d, i = %d\n", b, a, J, i);

    /* Order 3: both side effects done before the values are read */
    i = 5;
    i = i + 1; i = i + 1;
    J = i + i;
    printf("Order 3 (both first)  : i = %d, J = %d\n", i, J);

    printf("\nNote: i is modified twice without a sequence point, so the original\n");
    printf("expression is undefined behaviour; the result is compiler dependent.\n");
    return 0;
}
